/* ═══ functions ═══ */
CREATE FUNCTION AUDITLOG.fn_GetClientIP()
RETURNS NVARCHAR(50)
AS
BEGIN
    DECLARE @ctx NVARCHAR(128) = RTRIM(LTRIM(REPLACE(CAST(CONTEXT_INFO() AS NVARCHAR(128)), NCHAR(0), N' ')));
    IF @ctx = N'' OR @ctx IS NULL RETURN NULL;
    DECLARE @p1 INT = CHARINDEX(N'|', @ctx);
    DECLARE @p2 INT = CASE WHEN @p1 > 0 THEN CHARINDEX(N'|', @ctx, @p1 + 1) ELSE 0 END;
    IF @p1 > 0 AND @p2 > @p1
        RETURN NULLIF(RTRIM(LTRIM(SUBSTRING(@ctx, @p1 + 1, @p2 - @p1 - 1))), N'');
    IF @p1 > 0
        RETURN NULLIF(RTRIM(LTRIM(SUBSTRING(@ctx, @p1 + 1, 128))), N'');
    RETURN NULL;
END;
GO

CREATE FUNCTION [dbo].[FN_GET_PRIMARY_KEY_COLUMNS]
    (@SchemaName NVARCHAR(100), @TableName NVARCHAR(255))
RETURNS NVARCHAR(MAX)
AS
BEGIN
    DECLARE @Result NVARCHAR(MAX) = '';
    DECLARE @ColumnName NVARCHAR(255);
    
    -- Get primary key columns
    DECLARE pk_cursor CURSOR FOR
    SELECT CAST(kcu.COLUMN_NAME AS NVARCHAR(255))
    FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc
    INNER JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE kcu 
        ON tc.CONSTRAINT_NAME = kcu.CONSTRAINT_NAME
        AND tc.TABLE_SCHEMA = kcu.TABLE_SCHEMA
        AND tc.TABLE_NAME = kcu.TABLE_NAME
    WHERE tc.TABLE_SCHEMA = @SchemaName 
        AND tc.TABLE_NAME = @TableName
        AND tc.CONSTRAINT_TYPE = 'PRIMARY KEY'
    ORDER BY kcu.ORDINAL_POSITION;
    
    OPEN pk_cursor;
    FETCH NEXT FROM pk_cursor INTO @ColumnName;
    
    WHILE @@FETCH_STATUS = 0
    BEGIN
        IF @Result <> ''
            SET @Result = @Result + '+'',''+';
        SET @Result = @Result + 'CAST(COALESCE(i.[' + @ColumnName + '], d.[' + @ColumnName + ']) AS NVARCHAR(255))';
        FETCH NEXT FROM pk_cursor INTO @ColumnName;
    END
    
    CLOSE pk_cursor;
    DEALLOCATE pk_cursor;
    
    -- If no primary key, use first column
    IF @Result = ''
    BEGIN
        SELECT TOP 1 @ColumnName = CAST(COLUMN_NAME AS NVARCHAR(255))
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = @SchemaName AND TABLE_NAME = @TableName
        ORDER BY ORDINAL_POSITION;
        
        IF @ColumnName IS NOT NULL
            SET @Result = 'CAST(COALESCE(i.[' + @ColumnName + '], d.[' + @ColumnName + ']) AS NVARCHAR(255))';
    END
    
    RETURN @Result;
END
GO

CREATE FUNCTION [dbo].[fn_GetClientIP]()
RETURNS NVARCHAR(45)
AS
BEGIN
    DECLARE @IP NVARCHAR(45)
    SELECT @IP = client_net_address 
    FROM sys.dm_exec_connections 
    WHERE session_id = @@SPID
    RETURN ISNULL(@IP, 'Unknown')
END;
GO

/* ------------------------------------------------------------------ *
 * 5. Helper + validation
 * ------------------------------------------------------------------ */
CREATE   FUNCTION FINCORE.fn_coa_full_code(@parentAccountId int, @code nvarchar(20))
RETURNS nvarchar(80)
AS
BEGIN
    /* What FULL_CODE must be for a child of @parentAccountId. The application
       calls this when building an account; the trigger below checks the result. */
    RETURN ISNULL((SELECT FULL_CODE FROM FINCORE.COA_ACCOUNT WHERE ACCOUNT_ID = @parentAccountId), N'')
           + @code;
END
GO

/* �� 1. The predicate function �������������������������������������������������
 * Inline table-valued, SCHEMABINDING - both required for a security predicate.
 * Returns a row (meaning "visible") when the caller may see this country.
 * ���������������������������������������������������������������������������� */
CREATE   FUNCTION MOHECORE.fn_tenant_predicate(@CountryId INT)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
    SELECT 1 AS is_visible
    WHERE
        -- Ministry users and system work (migrations, startup, elevated jobs).
        TRY_CAST(CAST(SESSION_CONTEXT(N'TenantAll') AS NVARCHAR(4)) AS BIT) = 1
        -- Rows with no country belong to the ministry as a whole.
        OR @CountryId IS NULL
        -- Otherwise the row's country must be one of the caller's.
        OR @CountryId IN (
            SELECT TRY_CAST(value AS INT)
            FROM STRING_SPLIT(CAST(SESSION_CONTEXT(N'TenantCountryIds') AS NVARCHAR(4000)), ',')
            WHERE TRY_CAST(value AS INT) IS NOT NULL
        );
GO

/* ---- 1. The predicate ------------------------------------------------------ */
CREATE   FUNCTION MOHECORE.fn_wafar_write_predicate(@CountryId INT)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
    SELECT 1 AS is_writable
    WHERE
        -- The connection may write Wafar at all (country account or system work).
        TRY_CAST(CAST(SESSION_CONTEXT(N'TenantWafarWrite') AS NVARCHAR(4)) AS BIT) = 1
        AND (
            -- ...and the row is inside its scope, as for every other tenanted table.
            TRY_CAST(CAST(SESSION_CONTEXT(N'TenantAll') AS NVARCHAR(4)) AS BIT) = 1
            OR @CountryId IS NULL
            OR @CountryId IN (
                SELECT TRY_CAST(value AS INT)
                FROM STRING_SPLIT(CAST(SESSION_CONTEXT(N'TenantCountryIds') AS NVARCHAR(4000)), ',')
                WHERE TRY_CAST(value AS INT) IS NOT NULL
            )
        );
GO

/* �� 1. The predicate ���������������������������������������������������������
 * Inline table-valued and SCHEMABINDING, both required of a security predicate.
 * Returns a row - "visible" - when the caller may see this staff account.
 * ���������������������������������������������������������������������������� */
CREATE   FUNCTION UMSCORE.fn_staff_predicate(@UserId BIGINT)
RETURNS TABLE
WITH SCHEMABINDING
AS
RETURN
    SELECT 1 AS is_visible
    WHERE
        -- 1. Ministry tiers and system work (startup, migrations, @Scheduled jobs,
        --    and the sign-in paths that run before a scope exists).
        TRY_CAST(CAST(SESSION_CONTEXT(N'TenantAll') AS NVARCHAR(4)) AS BIT) = 1

        -- 2. We share an attach�. Intersection, not subset - see the header.
        OR EXISTS (
            SELECT 1
            FROM UMSCORE.UserCountries uc
            WHERE uc.UserId = @UserId
              AND uc.IsActive = 1
              AND uc.CountryId IN (
                  SELECT TRY_CAST(value AS INT)
                  FROM STRING_SPLIT(CAST(SESSION_CONTEXT(N'TenantCountryIds') AS NVARCHAR(4000)), ',')
                  WHERE TRY_CAST(value AS INT) IS NOT NULL
              )
        )

        -- 3. Awaiting assignment: no active attach�, so it belongs to nobody yet
        --    and the account nobody can see is the account nobody can fix.
        OR NOT EXISTS (
            SELECT 1
            FROM UMSCORE.UserCountries uc
            WHERE uc.UserId = @UserId
              AND uc.IsActive = 1
        );
GO

/* ═══ views (dependency order) ═══ */
/* ------------------------------------------------------------------ *
 * 8. Reconciliation: does the stored balance match its own detail?
 *
 *    The service layer maintains the running totals, so they can drift
 *    from the rows that produced them. This view recomputes from source
 *    and shows the difference. Every *_DELTA column must be zero.
 * ------------------------------------------------------------------ */
CREATE   VIEW FINCORE.V_ADVANCE_RECONCILIATION
AS
SELECT
    b.BALANCE_ID,
    b.FISCAL_YEAR_ID,
    b.STUDY_COUNTRY_IN_ID,
    b.CURRENCY_ID,
    b.OPENING_BALANCE,
    b.TRANSFERRED,
    src.TRANSFERRED_FROM_ALLOCATIONS,
    b.TRANSFERRED - src.TRANSFERRED_FROM_ALLOCATIONS AS TRANSFERRED_DELTA,
    b.DISBURSED,
    src.DISBURSED_FROM_SOURCES,
    b.DISBURSED - src.DISBURSED_FROM_SOURCES         AS DISBURSED_DELTA,
    b.WAFAR_EARMARKED,
    src.EARMARKED_FROM_ROWS,
    b.WAFAR_EARMARKED - src.EARMARKED_FROM_ROWS      AS EARMARKED_DELTA,
    b.WAFAR_SPENT,
    src.SPENT_FROM_ROWS,
    b.WAFAR_SPENT - src.SPENT_FROM_ROWS              AS SPENT_DELTA,
    b.WAFAR_BALANCE,
    b.AVAILABLE
FROM FINCORE.ATTACHE_ADVANCE_BALANCE b
CROSS APPLY (
    SELECT
        TRANSFERRED_FROM_ALLOCATIONS = ISNULL((
            SELECT SUM(a.AMOUNT) FROM FINCORE.ATTACHE_ALLOCATION a
            WHERE a.FISCAL_YEAR_ID = b.FISCAL_YEAR_ID
              AND a.STUDY_COUNTRY_IN_ID = b.STUDY_COUNTRY_IN_ID
              AND a.CURRENCY_ID = b.CURRENCY_ID
              AND a.STATUS = 'TRANSFERRED'), 0),
        /* Cash out to beneficiaries from BOTH sources. A Wafar use is cash
           leaving the attache exactly as a batch payment is, so DISBURSED has
           to count it -- otherwise the stored total and its own detail differ
           by the value of every Wafar payment ever made. The two are disjoint
           by construction: a Wafar use is never also a batch line. */
        DISBURSED_FROM_SOURCES = ISNULL((
            SELECT SUM(l.DISBURSED_AMOUNT)
            FROM FINCORE.PAYMENT_BATCH_LINE l
            JOIN FINCORE.PAYMENT_BATCH pb ON pb.BATCH_ID = l.BATCH_ID
            WHERE pb.FISCAL_YEAR_ID = b.FISCAL_YEAR_ID
              AND pb.STUDY_COUNTRY_IN_ID = b.STUDY_COUNTRY_IN_ID
              AND pb.CURRENCY_ID = b.CURRENCY_ID
              AND pb.STATUS IN ('DISBURSED','CLOSED')), 0)
          + ISNULL((
            SELECT SUM(u.AMOUNT) FROM FINCORE.WAFAR_USE u
            WHERE u.FISCAL_YEAR_ID = b.FISCAL_YEAR_ID
              AND u.STUDY_COUNTRY_IN_ID = b.STUDY_COUNTRY_IN_ID
              AND u.CURRENCY_ID = b.CURRENCY_ID), 0),
        EARMARKED_FROM_ROWS = ISNULL((
            SELECT SUM(e.AMOUNT) FROM FINCORE.WAFAR_EARMARK e
            WHERE e.FISCAL_YEAR_ID = b.FISCAL_YEAR_ID
              AND e.STUDY_COUNTRY_IN_ID = b.STUDY_COUNTRY_IN_ID
              AND e.CURRENCY_ID = b.CURRENCY_ID), 0),
        SPENT_FROM_ROWS = ISNULL((
            SELECT SUM(u.AMOUNT) FROM FINCORE.WAFAR_USE u
            WHERE u.FISCAL_YEAR_ID = b.FISCAL_YEAR_ID
              AND u.STUDY_COUNTRY_IN_ID = b.STUDY_COUNTRY_IN_ID
              AND u.CURRENCY_ID = b.CURRENCY_ID), 0)
) src;
GO

/* -- Q_STUD_DATA_ALL --------------------------------------------- */
CREATE   VIEW MOHECORE.Q_STUD_DATA_ALL AS

SELECT 

    SD.STUDENT_ID,

    SD.STUDENT_NAME,

    SD.STUDENT_COUNTRY_ID,

    SD.STUDENT_DELEGATION_DECISION_YEAR,

    SD.STUDENT_DEGREE_ID,

    SD.STUDENT_MAJOR_ID,

    SD.STUDENT_DELEGATE_DECISION_NO,

    SD.STUDENT_STUDY_NO_OF_YEARS,

    SD.STUDENT_CURRENT_LEVEL_ID,

    SD.STUDENT_FIRST_RECEIPT_OF_DUE,

    SD.STUDENT_AMOUNT,

    SD.STUDENT_NOTE_1,

    SD.STUDENT_NOTE_2,

    SD.STUDENT_STUDY_STATUS_ID,

    SD.STUDENT_AGENCY_TYPE_ID,

    SD.STUDENT_MINISTRY_TYPE_ID,

    SD.STUDENT_STUDY_TYPE_ID,

    SD.STUDENT_UNIVERSITY_TYPE_ID,

    SSS.STUDENT_STUDY_STATUS_NAME,
    COALESCE(NULLIF(SSS.STUDENT_STUDY_STATUS_NAME_EN, N''), SSS.STUDENT_STUDY_STATUS_NAME) AS STUDENT_STUDY_STATUS_NAME_EN,

    SAT.STUDENT_AGENCY_TYPE_NAME,
    COALESCE(NULLIF(SAT.STUDENT_AGENCY_TYPE_NAME_EN, N''), SAT.STUDENT_AGENCY_TYPE_NAME) AS STUDENT_AGENCY_TYPE_NAME_EN,

    SC.STUDENT_COUNTRY_NAME,
    COALESCE(NULLIF(SC.STUDENT_COUNTRY_NAME_EN, N''), SC.STUDENT_COUNTRY_NAME) AS STUDENT_COUNTRY_NAME_EN,

    SDG.STUDENT_DEGREE_NAME,
    COALESCE(NULLIF(SDG.STUDENT_DEGREE_NAME_EN, N''), SDG.STUDENT_DEGREE_NAME) AS STUDENT_DEGREE_NAME_EN,

    SMJ.STUDENT_MAJOR_NAME,
    COALESCE(NULLIF(SMJ.STUDENT_MAJOR_NAME_EN, N''), SMJ.STUDENT_MAJOR_NAME) AS STUDENT_MAJOR_NAME_EN,

    SMT.STUDENT_MINISTRY_TYPE_NAME,
    COALESCE(NULLIF(SMT.STUDENT_MINISTRY_TYPE_NAME_EN, N''), SMT.STUDENT_MINISTRY_TYPE_NAME) AS STUDENT_MINISTRY_TYPE_NAME_EN,

    SUT.STUDENT_UNIVERSITY_TYPE_NAME,
    COALESCE(NULLIF(SUT.STUDENT_UNIVERSITY_TYPE_NAME_EN, N''), SUT.STUDENT_UNIVERSITY_TYPE_NAME) AS STUDENT_UNIVERSITY_TYPE_NAME_EN,

    SCI.STUDY_COUNTRY_IN_NAME,
    COALESCE(NULLIF(SCI.STUDY_COUNTRY_IN_NAME_EN, N''), SCI.STUDY_COUNTRY_IN_NAME) AS STUDY_COUNTRY_IN_NAME_EN,

    SF.STUDENT_FIN_RECIEVED_YEAR,

    SF.STUDENT_FIN_RECIEVED_MONTH,

    N'??????? ??? ??????? ????? ????? ' 

        + CAST(SF.STUDENT_FIN_RECIEVED_MONTH AS NVARCHAR(10)) 

        + N' ????? ' 

        + CAST(SF.STUDENT_FIN_RECIEVED_YEAR AS NVARCHAR(10)) 

        AS HEAD_TITLE

FROM 

    MOHECORE.STUDENT_FINANCE SF

INNER JOIN MOHECORE.STUDENT_DATA SD 

    ON SF.STUDENT_ID = SD.STUDENT_ID

INNER JOIN MOHECORE.STUDENT_STUDY_STATUS SSS 

    ON SD.STUDENT_STUDY_STATUS_ID = SSS.STUDENT_STUDY_STATUS_ID

INNER JOIN MOHECORE.STUDENT_CURRENT_LEVEL SCL 

    ON SD.STUDENT_CURRENT_LEVEL_ID = SCL.STUDENT_CURRENT_LEVEL_ID

INNER JOIN MOHECORE.STUDENT_AGENCY_TYPE SAT 

    ON SD.STUDENT_AGENCY_TYPE_ID = SAT.STUDENT_AGENCY_TYPE_ID

INNER JOIN MOHECORE.STUDENT_COUNTRY SC 

    ON SD.STUDENT_COUNTRY_ID = SC.STUDENT_COUNTRY_ID

INNER JOIN MOHECORE.STUDENT_DEGREE SDG 

    ON SD.STUDENT_DEGREE_ID = SDG.STUDENT_DEGREE_ID

INNER JOIN MOHECORE.STUDENT_MAJOR SMJ 

    ON SD.STUDENT_MAJOR_ID = SMJ.STUDENT_MAJOR_ID

INNER JOIN MOHECORE.STUDENT_MINISTRY_TYPE SMT 

    ON SD.STUDENT_MINISTRY_TYPE_ID = SMT.STUDENT_MINISTRY_TYPE_ID

INNER JOIN MOHECORE.STUDENT_UNIVERSITY_TYPE SUT 

    ON SD.STUDENT_UNIVERSITY_TYPE_ID = SUT.STUDENT_UNIVERSITY_TYPE_ID

INNER JOIN MOHECORE.STUDY_COUNTRY_IN SCI 

    ON SCI.STUDY_COUNTRY_IN_ID = SD.STUDENT_COUNTRY_ID;
GO

/* �� Q_Stud_Financial_Data_Form ������������������������������������������� */
CREATE   VIEW MOHECORE.Q_Stud_Financial_Data_Form AS


SELECT

    sd.STUDENT_ID,

    sd.STUDENT_NAME,

    sd.STUDENT_COUNTRY_ID,

    sd.STUDENT_DELEGATION_DECISION_YEAR,

    sd.STUDENT_DEGREE_ID,

    sd.STUDENT_MAJOR_ID,

    sd.STUDENT_DELEGATE_DECISION_NO,

    sd.STUDENT_STUDY_NO_OF_YEARS,

    sd.STUDENT_CURRENT_LEVEL_ID,

    sd.STUDENT_FIRST_RECEIPT_OF_DUE,

    sd.STUDENT_AMOUNT,

    sd.STUDENT_NOTE_1,

    sd.STUDENT_NOTE_2,

    sd.STUDENT_STUDY_STATUS_ID,

    sd.STUDENT_AGENCY_TYPE_ID,

    sd.STUDENT_MINISTRY_TYPE_ID,

    sd.STUDENT_STUDY_TYPE_ID,

    sd.STUDENT_UNIVERSITY_TYPE_ID,

    ISNULL(sss.STUDENT_STUDY_STATUS_NAME, N'')   AS STUDENT_STUDY_STATUS_NAME,
    ISNULL(COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME), N'') AS STUDENT_STUDY_STATUS_NAME_EN,

    ISNULL(sat.STUDENT_AGENCY_TYPE_NAME, N'')    AS STUDENT_AGENCY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sat.STUDENT_AGENCY_TYPE_NAME_EN, N''), sat.STUDENT_AGENCY_TYPE_NAME), N'') AS STUDENT_AGENCY_TYPE_NAME_EN,

    ISNULL(sc.STUDENT_COUNTRY_NAME, N'')         AS STUDENT_COUNTRY_NAME,
    ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME), N'') AS STUDENT_COUNTRY_NAME_EN,

    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'')        AS STUDENT_DEGREE_NAME,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'') AS STUDENT_DEGREE_NAME_EN,

    ISNULL(sm.STUDENT_MAJOR_NAME, N'')           AS STUDENT_MAJOR_NAME,
    ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'') AS STUDENT_MAJOR_NAME_EN,

    ISNULL(smt.STUDENT_MINISTRY_TYPE_NAME, N'')  AS STUDENT_MINISTRY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(smt.STUDENT_MINISTRY_TYPE_NAME_EN, N''), smt.STUDENT_MINISTRY_TYPE_NAME), N'') AS STUDENT_MINISTRY_TYPE_NAME_EN,

    ISNULL(sut.STUDENT_UNIVERSITY_TYPE_NAME, N'') AS STUDENT_UNIVERSITY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sut.STUDENT_UNIVERSITY_TYPE_NAME_EN, N''), sut.STUDENT_UNIVERSITY_TYPE_NAME), N'') AS STUDENT_UNIVERSITY_TYPE_NAME_EN,

    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'')       AS STUDY_COUNTRY_IN_NAME,
    ISNULL(COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME), N'') AS STUDY_COUNTRY_IN_NAME_EN,

    sf.STUDENT_FIN_RECIEVED_YEAR,

    sf.STUDENT_FIN_RECIEVED_MONTH,

    ISNULL(sd.STUDENT_NAME, N'') + N' - ' +

        ISNULL(CAST(sf.STUDENT_FIN_RECIEVED_YEAR AS NVARCHAR(4)), N'') AS HEAD_TITLE

FROM MOHECORE.STUDENT_DATA sd

LEFT JOIN MOHECORE.STUDENT_FINANCE           sf  ON sf.STUDENT_ID             = sd.STUDENT_ID

LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS      sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID

LEFT JOIN MOHECORE.STUDENT_AGENCY_TYPE       sat ON sat.STUDENT_AGENCY_TYPE_ID  = sd.STUDENT_AGENCY_TYPE_ID

LEFT JOIN MOHECORE.STUDENT_COUNTRY           sc  ON sc.STUDENT_COUNTRY_ID       = sd.STUDENT_COUNTRY_ID

LEFT JOIN MOHECORE.STUDENT_DEGREE            sdeg ON sdeg.STUDENT_DEGREE_ID     = sd.STUDENT_DEGREE_ID

LEFT JOIN MOHECORE.STUDENT_MAJOR             sm  ON sm.STUDENT_MAJOR_ID         = sd.STUDENT_MAJOR_ID

LEFT JOIN MOHECORE.STUDENT_MINISTRY_TYPE     smt ON smt.STUDENT_MINISTRY_TYPE_ID = sd.STUDENT_MINISTRY_TYPE_ID

LEFT JOIN MOHECORE.STUDENT_UNIVERSITY_TYPE   sut ON sut.STUDENT_UNIVERSITY_TYPE_ID = sd.STUDENT_UNIVERSITY_TYPE_ID

LEFT JOIN MOHECORE.STUDY_COUNTRY_IN          sci ON sci.STUDY_COUNTRY_IN_ID     = sf.STUDY_COUNTRY_IN_ID

WHERE ISNULL(sd.IS_DELETED, 0) = 0;
GO

/* �� Q_Stud_Financial_Data_Form_V2 ������������������������������������������� */
CREATE   VIEW MOHECORE.Q_Stud_Financial_Data_Form_V2 AS

SELECT
    sd.STUDENT_ID,
    ISNULL(sd.STUDENT_NAME, N'')                                   AS STUDENT_NAME,
    -- ?????: university -> ministry -> agency, never NULL
    COALESCE(NULLIF(LTRIM(RTRIM(sut.STUDENT_UNIVERSITY_TYPE_NAME)), N''),
             NULLIF(LTRIM(RTRIM(smt.STUDENT_MINISTRY_TYPE_NAME)),   N''),
             NULLIF(LTRIM(RTRIM(sat.STUDENT_AGENCY_TYPE_NAME)),     N''),
             N'')                                                  AS ENTITY_NAME,
    -- The English form answers with the same lookup the Arabic one did: the
    -- COALESCE order is repeated over the _EN columns, each falling back to its
    -- own Arabic name, so the two columns can never describe different bodies.
    COALESCE(NULLIF(LTRIM(RTRIM(COALESCE(NULLIF(sut.STUDENT_UNIVERSITY_TYPE_NAME_EN, N''), sut.STUDENT_UNIVERSITY_TYPE_NAME))), N''),
             NULLIF(LTRIM(RTRIM(COALESCE(NULLIF(smt.STUDENT_MINISTRY_TYPE_NAME_EN,   N''), smt.STUDENT_MINISTRY_TYPE_NAME))),   N''),
             NULLIF(LTRIM(RTRIM(COALESCE(NULLIF(sat.STUDENT_AGENCY_TYPE_NAME_EN,     N''), sat.STUDENT_AGENCY_TYPE_NAME))),     N''),
             N'')                                                  AS ENTITY_NAME_EN,
    ISNULL(sat.STUDENT_AGENCY_TYPE_NAME, N'')                      AS STUDENT_AGENCY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sat.STUDENT_AGENCY_TYPE_NAME_EN, N''), sat.STUDENT_AGENCY_TYPE_NAME), N'') AS STUDENT_AGENCY_TYPE_NAME_EN,
    ISNULL(smt.STUDENT_MINISTRY_TYPE_NAME, N'')                    AS STUDENT_MINISTRY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(smt.STUDENT_MINISTRY_TYPE_NAME_EN, N''), smt.STUDENT_MINISTRY_TYPE_NAME), N'') AS STUDENT_MINISTRY_TYPE_NAME_EN,
    ISNULL(sut.STUDENT_UNIVERSITY_TYPE_NAME, N'')                  AS STUDENT_UNIVERSITY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sut.STUDENT_UNIVERSITY_TYPE_NAME_EN, N''), sut.STUDENT_UNIVERSITY_TYPE_NAME), N'') AS STUDENT_UNIVERSITY_TYPE_NAME_EN,
    sf.STUDY_COUNTRY_IN_ID,
    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'')                         AS STUDY_COUNTRY_IN_NAME,
    ISNULL(COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME), N'') AS STUDY_COUNTRY_IN_NAME_EN,
    ISNULL(sc.STUDENT_COUNTRY_NAME, N'')                           AS STUDENT_COUNTRY_NAME,
    ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME), N'') AS STUDENT_COUNTRY_NAME_EN,
    sd.STUDENT_DELEGATION_DECISION_YEAR,
    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'')                          AS STUDENT_DEGREE_NAME,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'') AS STUDENT_DEGREE_NAME_EN,
    ISNULL(sm.STUDENT_MAJOR_NAME, N'')                             AS STUDENT_MAJOR_NAME,
    ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'') AS STUDENT_MAJOR_NAME_EN,
    sd.STUDENT_DELEGATE_DECISION_NO,
    sd.STUDENT_STUDY_NO_OF_YEARS,
    sd.STUDENT_CURRENT_LEVEL_ID,
    ISNULL(scl.STUDENT_CURRENT_LEVEL_NAME, N'')                    AS CURRENT_LEVEL_NAME,
    ISNULL(NULLIF(scl.STUDENT_CURRENT_LEVEL_NAME_EN, ''),
           scl.STUDENT_CURRENT_LEVEL_NAME)                         AS CURRENT_LEVEL_NAME_EN,
    scl.STUDENT_CURRENT_LEVEL_ORDER_NO                             AS CURRENT_LEVEL_ORDER_NO,
    -- "??????? ??????" as the form prints it: the year number, else the level name
    CASE WHEN scl.STUDENT_CURRENT_LEVEL_ORDER_NO IS NOT NULL
          AND (scl.STUDENT_CURRENT_LEVEL_NAME_EN LIKE '%Year%'
               OR scl.STUDENT_CURRENT_LEVEL_NAME LIKE N'?????%')
         THEN CAST(scl.STUDENT_CURRENT_LEVEL_ORDER_NO AS NVARCHAR(10))
         ELSE ISNULL(scl.STUDENT_CURRENT_LEVEL_NAME, N'') END      AS CURRENT_LEVEL_LABEL,
    sd.STUDENT_FIRST_RECEIPT_OF_DUE,
    sd.STUDENT_AMOUNT,
    sf.STUDENT_FIN_RECIEVED_AMOUNT,
    CAST(sd.STUDENT_NOTE_1 AS NVARCHAR(MAX))                       AS STUDENT_NOTE_1,
    CAST(sd.STUDENT_NOTE_2 AS NVARCHAR(MAX))                       AS STUDENT_NOTE_2,
    ISNULL(sss.STUDENT_STUDY_STATUS_NAME, N'')                     AS STUDENT_STUDY_STATUS_NAME,
    ISNULL(COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME), N'') AS STUDENT_STUDY_STATUS_NAME_EN,
    sf.STUDENT_FIN_RECIEVED_YEAR,
    sf.STUDENT_FIN_RECIEVED_MONTH,
    sf.MOHE_QUARTER_ID
FROM MOHECORE.STUDENT_DATA sd
JOIN      MOHECORE.STUDENT_FINANCE          sf   ON sf.STUDENT_ID                  = sd.STUDENT_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS     sss  ON sss.STUDENT_STUDY_STATUS_ID    = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_AGENCY_TYPE      sat  ON sat.STUDENT_AGENCY_TYPE_ID     = sd.STUDENT_AGENCY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_MINISTRY_TYPE    smt  ON smt.STUDENT_MINISTRY_TYPE_ID   = sd.STUDENT_MINISTRY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_UNIVERSITY_TYPE  sut  ON sut.STUDENT_UNIVERSITY_TYPE_ID = sd.STUDENT_UNIVERSITY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_COUNTRY          sc   ON sc.STUDENT_COUNTRY_ID          = sd.STUDENT_COUNTRY_ID
LEFT JOIN MOHECORE.STUDENT_DEGREE           sdeg ON sdeg.STUDENT_DEGREE_ID         = sd.STUDENT_DEGREE_ID
LEFT JOIN MOHECORE.STUDENT_MAJOR            sm   ON sm.STUDENT_MAJOR_ID            = sd.STUDENT_MAJOR_ID
LEFT JOIN MOHECORE.STUDENT_CURRENT_LEVEL    scl  ON scl.STUDENT_CURRENT_LEVEL_ID   = sd.STUDENT_CURRENT_LEVEL_ID
LEFT JOIN MOHECORE.STUDY_COUNTRY_IN         sci  ON sci.STUDY_COUNTRY_IN_ID        = sf.STUDY_COUNTRY_IN_ID
WHERE ISNULL(sd.IS_DELETED, 0) = 0;
GO

/* �� 4. V_Academic_Performance �������������������������������������������� */
CREATE   VIEW MOHECORE.V_Academic_Performance AS
SELECT
    sd.STUDENT_ID,
    sd.STUDENT_NAME,
    sd.STUDY_COUNTRY_IN                  AS study_country_in_id,
    sd.STUDENT_MAJOR_ID,
    ISNULL(sm.STUDENT_MAJOR_NAME, N'') AS STUDENT_MAJOR_NAME,
    ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'') AS STUDENT_MAJOR_NAME_EN,
    sd.STUDENT_CURRENT_LEVEL_ID,
    ISNULL(scl.STUDENT_CURRENT_LEVEL_NAME, N'') AS STUDENT_CURRENT_LEVEL_NAME,
    ISNULL(COALESCE(NULLIF(scl.STUDENT_CURRENT_LEVEL_NAME_EN, N''), scl.STUDENT_CURRENT_LEVEL_NAME), N'') AS STUDENT_CURRENT_LEVEL_NAME_EN,
    sd.STUDENT_STUDY_NO_OF_YEARS,
    sd.STUDENT_STUDY_STATUS_ID,
    ISNULL(sss.STUDENT_STUDY_STATUS_NAME, N'') AS STUDENT_STUDY_STATUS_NAME,
    ISNULL(COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME), N'') AS STUDENT_STUDY_STATUS_NAME_EN,
    sd.STUDENT_DEGREE_ID,
    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'') AS STUDENT_DEGREE_NAME,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'') AS STUDENT_DEGREE_NAME_EN,
    sd.STUDENT_COUNTRY_ID,
    ISNULL(sc.STUDENT_COUNTRY_NAME, N'') AS STUDENT_COUNTRY_NAME,
    ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME), N'') AS STUDENT_COUNTRY_NAME_EN
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDENT_MAJOR         sm   ON sm.STUDENT_MAJOR_ID          = sd.STUDENT_MAJOR_ID
LEFT JOIN MOHECORE.STUDENT_CURRENT_LEVEL scl  ON scl.STUDENT_CURRENT_LEVEL_ID = sd.STUDENT_CURRENT_LEVEL_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS  sss  ON sss.STUDENT_STUDY_STATUS_ID  = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_DEGREE        sdeg ON sdeg.STUDENT_DEGREE_ID       = sd.STUDENT_DEGREE_ID
LEFT JOIN MOHECORE.STUDENT_COUNTRY       sc   ON sc.STUDENT_COUNTRY_ID        = sd.STUDENT_COUNTRY_ID
WHERE ISNULL(sd.IS_DELETED, 0) = 0;
GO

CREATE   VIEW MOHECORE.V_Annual_Report AS
SELECT
    sd.STUDY_COUNTRY_IN AS study_country_id,
    YEAR(sf.STUDY_FINANCE_MIDATE) AS report_year,
    COUNT(DISTINCT sd.STUDENT_ID) AS total_students,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'NEW'       THEN sd.STUDENT_ID END) AS new_enrollments,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'ACTIVE'    THEN sd.STUDENT_ID END) AS active_students,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'SUSPENDED' THEN sd.STUDENT_ID END) AS suspended_students,
    COUNT(*)  AS total_financial_transactions,
    CAST(SUM(sf.STUDENT_FIN_RECIEVED_AMOUNT) AS DECIMAL(18,2)) AS total_amount_disbursed,
    CAST(SUM(CASE WHEN sty.IS_SCHOLARSHIP = 1 THEN sf.STUDENT_FIN_RECIEVED_AMOUNT ELSE 0 END) AS DECIMAL(18,2)) AS scholarship_amount_disbursed,
    CAST(SUM(CASE WHEN sty.IS_SCHOLARSHIP = 0 THEN sf.STUDENT_FIN_RECIEVED_AMOUNT ELSE 0 END) AS DECIMAL(18,2)) AS regular_amount_disbursed,
    CASE WHEN COUNT(DISTINCT sd.STUDENT_ID) = 0 THEN 0
         ELSE CAST(SUM(sf.STUDENT_FIN_RECIEVED_AMOUNT) * 1.0 / COUNT(DISTINCT sd.STUDENT_ID) AS DECIMAL(18,2))
    END AS avg_amount_per_student,
    CAST(MAX(sf.STUDENT_FIN_RECIEVED_AMOUNT) AS DECIMAL(18,2)) AS max_amount_disbursed,
    CAST(MIN(sf.STUDENT_FIN_RECIEVED_AMOUNT) AS DECIMAL(18,2)) AS min_amount_disbursed,
    COUNT(DISTINCT CASE WHEN sty.IS_SCHOLARSHIP = 1 THEN sd.STUDENT_ID END) AS scholarship_students,
    COUNT(DISTINCT CASE WHEN sty.IS_SCHOLARSHIP = 0 THEN sd.STUDENT_ID END) AS regular_students,
    COUNT(DISTINCT CASE WHEN sg.CODE = 'MALE'   THEN sd.STUDENT_ID END) AS male_students,
    COUNT(DISTINCT CASE WHEN sg.CODE = 'FEMALE' THEN sd.STUDENT_ID END) AS female_students,
    COUNT(DISTINCT sd.STUDY_UNIVERSITY_IN) AS total_universities,
    COUNT(DISTINCT sd.STUDY_COUNTRY_IN) AS total_countries,
    COUNT(DISTINCT sd.STUDENT_MAJOR_ID) AS total_majors,
    COUNT(DISTINCT sd.STUDENT_DEGREE_ID) AS total_degrees
FROM MOHECORE.STUDENT_FINANCE sf
LEFT JOIN MOHECORE.STUDENT_DATA         sd  ON sd.STUDENT_ID               = sf.STUDENT_ID AND ISNULL(sd.IS_DELETED, 0) = 0
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE   sty ON sty.STUDENT_STUDY_TYPE_ID   = sd.STUDENT_STUDY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_GENDER       sg  ON sg.STUDENT_GENDER_ID        = sd.STUDENT_GENDER
WHERE sf.STUDY_FINANCE_MIDATE IS NOT NULL
GROUP BY sd.STUDY_COUNTRY_IN, YEAR(sf.STUDY_FINANCE_MIDATE);
GO

/* �� 3. V_Bank_Transaction �����������������������������������������������������
 * Aligned with com.dilaw.mohe.model.BankTransaction.
 *
 * transaction_type was 'Debit' on every row and reference_number was 'REF' glued
 * to the surrogate id - a reference number that referred to nothing outside this
 * view. Both now come from the record: the received-status, and STUDY_CHECK_ID.
 * ���������������������������������������������������������������������������� */
CREATE   VIEW MOHECORE.V_Bank_Transaction AS
SELECT
    sf.STUDENT_FIN_ID                                                    AS transaction_id,
    sf.STUDY_CHECK_DATE                                                  AS transaction_date,
    CAST(NULLIF(sfrs.STUDY_FIN_RECEIVED_STATUS_NAME, '') AS NVARCHAR(255)) AS transaction_type,
    CAST(COALESCE(
            NULLIF(CAST(sf.STUDY_CHECK_DETAILS AS NVARCHAR(MAX)), ''),
            NULLIF(srws.STUDY_RECEIVED_WHOM_STATUS_NAME, ''),
            NULLIF(sfrs.STUDY_FIN_RECEIVED_STATUS_NAME, '')
        ) AS NVARCHAR(1000))                                             AS transaction_description,
    sf.STUDENT_FIN_RECIEVED_AMOUNT                                       AS transaction_amount,
    CAST(NULLIF(cur.STUDY_CURRENCY_IN_NAME, '') AS NVARCHAR(100))        AS transaction_currency,
    CAST(NULLIF(CAST(sf.STUDY_CHECK_ID AS NVARCHAR(255)), '') AS NVARCHAR(255)) AS reference_number,
    bank.STUDY_FINANCE_BANKE_NAME                                        AS bank_name,
    branch.STUDY_FINANCE_BANK_BRANCH_NAME                                AS bank_branch,
    sd.STUDENT_NAME                                                      AS beneficiary_name,
    sd.STUDENT_PASSPORT_NUMBER                                           AS beneficiary_account
FROM MOHECORE.STUDENT_FINANCE sf
INNER JOIN MOHECORE.STUDENT_DATA sd ON sf.STUDENT_ID = sd.STUDENT_ID
LEFT JOIN MOHECORE.STUDY_FINANCE_BANK         bank   ON sf.STUDY_FINANCE_BANKE_ID        = bank.STUDY_FINANCE_BANKE_ID
LEFT JOIN MOHECORE.STUDY_FINANCE_BANK_BRANCH  branch ON sf.STUDY_FINANCE_BANK_BRANCH_ID  = branch.STUDY_FINANCE_BANK_BRANCH_ID
LEFT JOIN MOHECORE.STUDY_FIN_RECEIVED_STATUS  sfrs   ON sf.STUDY_FIN_RECIEVED_STATUS     = sfrs.STUDY_FIN_RECEIVED_STATUS_ID
LEFT JOIN MOHECORE.STUDY_RECEIVED_WHOM_STATUS srws   ON sf.STUDY_RECEIVED_WHOM_STATUS_ID = srws.STUDY_RECEIVED_WHOM_STATUS_ID
LEFT JOIN MOHECORE.STUDY_CURRENCY_IN          cur    ON sf.STUDY_CURRENCY_IN_ID          = cur.STUDY_CURRENCY_IN_ID
WHERE sf.STUDY_CHECK_DATE IS NOT NULL
  AND sf.STUDY_FINANCE_BANKE_ID IS NOT NULL;
GO

/*
    V021 - make V_Budget_Analysis return rows.

    Problem
    -------
    The view joined STUDENT_FINANCE to MOHE_QUARTER on

        INNER JOIN MOHECORE.MOHE_QUARTER mq ON sf.MOHE_QUARTER_ID = mq.QUARTER

    but STUDENT_FINANCE.MOHE_QUARTER_ID is NULL on every one of the 941 finance
    rows in this database, so the inner join eliminated everything and the view
    returned zero rows. The budget analysis page has therefore always shown an
    empty table - not because the page is wrong, but because its source view
    could never produce a row.

    Fix
    ---
    Derive the period the same way the quarterly financial report does: from
    STUDY_CHECK_DATE when present, otherwise from STUDENT_FIN_RECIEVED_YEAR /
    _MONTH, which are the populated columns. MOHE_QUARTER is then joined only to
    pick up BUDGET_AMOUNT, and as a LEFT JOIN so a period missing from the
    quarter table still reports its spending.

    This changes no data. STUDENT_FINANCE.MOHE_QUARTER_ID is left alone: back-
    filling it would be a data migration, and the derivation above is what the
    rest of the reporting layer already relies on.

    Still outstanding after this script
    -----------------------------------
    MOHE_QUARTER.BUDGET_AMOUNT is NULL on all 12 quarter rows, so allocated_amount
    is 0, remaining_amount is the negative of spending, and utilization_percentage
    is 0. The report will show what was spent but cannot show it against a budget
    until BUDGET_AMOUNT is entered. Expected output immediately after applying:

        year quarter country  allocated  spent        utilization
        2024 1       1        0          1,569,720    0
        2025 1       1        0          3,360        0
        2026 2       1        0          1,500        0

    Apply in SSMS.
*/

CREATE   VIEW MOHECORE.V_Budget_Analysis AS
WITH finance AS (
    SELECT
        sd.STUDY_COUNTRY_IN AS study_country_in_id,
        COALESCE(sf.STUDENT_FIN_RECIEVED_AMOUNT, 0) AS amount,
        COALESCE(YEAR(sf.STUDY_CHECK_DATE), sf.STUDENT_FIN_RECIEVED_YEAR) AS budget_year,
        COALESCE(
            DATEPART(QUARTER, sf.STUDY_CHECK_DATE),
            CASE
                WHEN sf.STUDENT_FIN_RECIEVED_MONTH IS NOT NULL AND sf.STUDENT_FIN_RECIEVED_MONTH > 0
                    THEN ((sf.STUDENT_FIN_RECIEVED_MONTH - 1) / 3) + 1
            END
        ) AS budget_quarter
    FROM MOHECORE.STUDENT_FINANCE sf
    INNER JOIN MOHECORE.STUDENT_DATA sd
        ON sd.STUDENT_ID = sf.STUDENT_ID
       AND (sd.IS_DELETED = 0 OR sd.IS_DELETED IS NULL)
    WHERE sd.STUDY_COUNTRY_IN IS NOT NULL
      -- A zero amount is not a disbursement, so it must not create a period row.
      AND COALESCE(sf.STUDENT_FIN_RECIEVED_AMOUNT, 0) <> 0
)
SELECT
    -- One row per (country, year, quarter), which is what makes this unique.
    CAST(f.study_country_in_id * 1000000
         + f.budget_year * 10
         + f.budget_quarter AS BIGINT) AS budget_id,
    N'quarterly' AS budget_category,
    CAST(COALESCE(MAX(mq.BUDGET_AMOUNT), 0) AS DECIMAL(18,2)) AS allocated_amount,
    CAST(SUM(f.amount) AS DECIMAL(18,2)) AS spent_amount,
    CAST(COALESCE(MAX(mq.BUDGET_AMOUNT), 0) - SUM(f.amount) AS DECIMAL(18,2)) AS remaining_amount,
    CASE
        WHEN COALESCE(MAX(mq.BUDGET_AMOUNT), 0) = 0 THEN 0
        ELSE CAST(SUM(f.amount) * 100.0 / MAX(mq.BUDGET_AMOUNT) AS INT)
    END AS utilization_percentage,
    f.budget_year,
    f.budget_quarter,
    f.study_country_in_id
FROM finance f
-- Budget only. MOHE_QUARTER.COUNTRY_ID is NULL on every current row, meaning a
-- ministry-wide figure; the predicate keeps a per-country budget working if one
-- is ever entered, without fanning the row out.
LEFT JOIN MOHECORE.MOHE_QUARTER mq
       ON mq.QUARTER_YEAR = f.budget_year
      AND mq.QUARTER_NO   = f.budget_quarter
      AND (mq.COUNTRY_ID IS NULL OR mq.COUNTRY_ID = f.study_country_in_id)
WHERE f.budget_year IS NOT NULL
  AND f.budget_quarter IS NOT NULL
GROUP BY f.study_country_in_id, f.budget_year, f.budget_quarter;
GO

/* �� V_Comparative_Statistics ��������������������������������������������
   dimension_name is a country name in one branch of the UNION and a degree name
   in the other, so the English column is added to both branches with its own
   source, to both GROUP BYs, and to the outer select that reads the CTE.       */
CREATE   VIEW MOHECORE.V_Comparative_Statistics AS
WITH cohort AS (
    SELECT
        sd.STUDY_COUNTRY_IN,
        sd.STUDENT_DEGREE_ID,
        TRY_CAST(sd.STUDENT_DELEGATION_DECISION_YEAR AS INT) AS decision_year
    FROM MOHECORE.STUDENT_DATA sd
    WHERE ISNULL(sd.IS_DELETED, 0) = 0
      AND TRY_CAST(sd.STUDENT_DELEGATION_DECISION_YEAR AS INT) IS NOT NULL
),
chosen AS (
    -- Most recent cohort year that is not in the future, against the next year
    -- down that also has students.
    SELECT
        c.current_year,
        (SELECT MAX(decision_year) FROM cohort WHERE decision_year < c.current_year) AS previous_year
    FROM (
        SELECT MAX(decision_year) AS current_year
        FROM cohort
        WHERE decision_year <= YEAR(GETDATE())
    ) c
),
base AS (
    SELECT
        'country' AS comparison_type,
        ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'-') AS dimension_name,
        ISNULL(COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME), N'-') AS dimension_name_en,
        SUM(CASE WHEN ch.decision_year = k.current_year  THEN 1 ELSE 0 END) AS current_period_value,
        SUM(CASE WHEN ch.decision_year = k.previous_year THEN 1 ELSE 0 END) AS previous_period_value,
        k.current_year,
        k.previous_year
    FROM cohort ch
    CROSS JOIN chosen k
    LEFT JOIN MOHECORE.STUDY_COUNTRY_IN sci ON sci.STUDY_COUNTRY_IN_ID = ch.STUDY_COUNTRY_IN
    GROUP BY sci.STUDY_COUNTRY_IN_NAME, sci.STUDY_COUNTRY_IN_NAME_EN, k.current_year, k.previous_year

    UNION ALL

    SELECT
        'degree',
        ISNULL(sdeg.STUDENT_DEGREE_NAME, N'-'),
        ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'-'),
        SUM(CASE WHEN ch.decision_year = k.current_year  THEN 1 ELSE 0 END),
        SUM(CASE WHEN ch.decision_year = k.previous_year THEN 1 ELSE 0 END),
        k.current_year,
        k.previous_year
    FROM cohort ch
    CROSS JOIN chosen k
    LEFT JOIN MOHECORE.STUDENT_DEGREE sdeg ON sdeg.STUDENT_DEGREE_ID = ch.STUDENT_DEGREE_ID
    GROUP BY sdeg.STUDENT_DEGREE_NAME, sdeg.STUDENT_DEGREE_NAME_EN, k.current_year, k.previous_year
)
SELECT
    comparison_type,
    dimension_name,
    dimension_name_en,
    current_period_value,
    previous_period_value,
    CASE WHEN ISNULL(previous_period_value, 0) = 0 THEN NULL
         ELSE CAST((current_period_value - previous_period_value) * 100.0
                   / previous_period_value AS DECIMAL(8,2))
    END AS change_percentage,
    CAST(current_year AS NVARCHAR(10))  AS current_period,
    CAST(previous_year AS NVARCHAR(10)) AS previous_period
FROM base
WHERE current_period_value <> 0 OR previous_period_value <> 0;
GO

/* -- 1. V_Data_Visualization -------------------------------------------------
   The inner query is unchanged apart from the English sibling of data_label
   and the bilingual fallback. How the slices are cut, and the per-country
   partitioning V030 introduced, are left exactly as they were.              */
CREATE   VIEW MOHECORE.V_Data_Visualization AS
SELECT
    ROW_NUMBER() OVER (ORDER BY v.study_country_in_id, v.category, v.data_label) AS visualization_id,
    -- The chart's name, read from the catalogue rather than asserted here.
    -- ISNULL falls back to the key so a dimension added to the view without a
    -- row in LU_REPORT_DIMENSION prints something identifiable, not NULL.
    ISNULL(dim.NAME_AR, v.category) AS chart_name,
    ISNULL(COALESCE(NULLIF(dim.NAME_EN, N''), dim.NAME_AR), v.category) AS chart_name_en,
    N'pie' AS chart_type,
    v.category,
    v.data_value,
    v.data_label,
    v.data_label_en,
    N'#4472C4' AS color_code,
    ROW_NUMBER() OVER (PARTITION BY v.study_country_in_id, v.category ORDER BY v.data_value DESC) AS sort_order,
    v.study_country_in_id
FROM (
    SELECT 'status' AS category,
           sd.STUDY_COUNTRY_IN AS study_country_in_id,
           COUNT(*) AS data_value,
           ISNULL(sss.STUDENT_STUDY_STATUS_NAME, N'??? ????') AS data_label,
           ISNULL(COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME),
                  N'Unspecified') AS data_label_en
    FROM MOHECORE.STUDENT_DATA sd
    LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
    WHERE ISNULL(sd.IS_DELETED, 0) = 0
    GROUP BY sd.STUDY_COUNTRY_IN, sss.STUDENT_STUDY_STATUS_NAME, sss.STUDENT_STUDY_STATUS_NAME_EN

    UNION ALL

    SELECT 'country' AS category,
           sd.STUDY_COUNTRY_IN AS study_country_in_id,
           COUNT(*) AS data_value,
           ISNULL(sc.STUDENT_COUNTRY_NAME, N'??? ????') AS data_label,
           ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME),
                  N'Unspecified') AS data_label_en
    FROM MOHECORE.STUDENT_DATA sd
    LEFT JOIN MOHECORE.STUDENT_COUNTRY sc ON sc.STUDENT_COUNTRY_ID = sd.STUDENT_COUNTRY_ID
    WHERE ISNULL(sd.IS_DELETED, 0) = 0
    GROUP BY sd.STUDY_COUNTRY_IN, sc.STUDENT_COUNTRY_NAME, sc.STUDENT_COUNTRY_NAME_EN
) v
LEFT JOIN MOHECORE.LU_REPORT_DIMENSION dim
       ON dim.GROUP_CODE = N'DATA_VISUALIZATION_CHART'
      AND dim.CODE       = v.category
      AND dim.IS_DELETED = 0;
GO

/* -- 2. V_Distribution_Statistics --------------------------------------------
   Four branches, four lookups, four English sources.                        */
CREATE   VIEW MOHECORE.V_Distribution_Statistics AS
SELECT distribution_type, category_name, category_name_en, student_count,
       CAST(student_count * 100.0 / SUM(student_count) OVER (PARTITION BY distribution_type) AS DECIMAL(5,2)) AS percentage_of_total,
       RANK() OVER (PARTITION BY distribution_type ORDER BY student_count DESC) AS rank_position,
       CASE WHEN student_count >= 20 THEN 'major' WHEN student_count >= 5 THEN 'minor' ELSE 'marginal' END AS category_significance
FROM (
    -- by country (nationality; the repository counts study country instead)
    SELECT 'country' AS distribution_type,
           ISNULL(sc.STUDENT_COUNTRY_NAME, N'??? ????') AS category_name,
           ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME),
                  N'Unspecified') AS category_name_en,
           COUNT(*) AS student_count
    FROM MOHECORE.STUDENT_DATA sd
    LEFT JOIN MOHECORE.STUDENT_COUNTRY sc ON sc.STUDENT_COUNTRY_ID = sd.STUDENT_COUNTRY_ID
    WHERE ISNULL(sd.IS_DELETED, 0) = 0
    GROUP BY sc.STUDENT_COUNTRY_NAME, sc.STUDENT_COUNTRY_NAME_EN

    UNION ALL

    -- by major
    SELECT 'major',
           ISNULL(sm.STUDENT_MAJOR_NAME, N'??? ????'),
           ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'Unspecified'),
           COUNT(*)
    FROM MOHECORE.STUDENT_DATA sd
    LEFT JOIN MOHECORE.STUDENT_MAJOR sm ON sm.STUDENT_MAJOR_ID = sd.STUDENT_MAJOR_ID
    WHERE ISNULL(sd.IS_DELETED, 0) = 0
    GROUP BY sm.STUDENT_MAJOR_NAME, sm.STUDENT_MAJOR_NAME_EN

    UNION ALL

    -- by degree
    SELECT 'degree',
           ISNULL(sdeg.STUDENT_DEGREE_NAME, N'??? ????'),
           ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'Unspecified'),
           COUNT(*)
    FROM MOHECORE.STUDENT_DATA sd
    LEFT JOIN MOHECORE.STUDENT_DEGREE sdeg ON sdeg.STUDENT_DEGREE_ID = sd.STUDENT_DEGREE_ID
    WHERE ISNULL(sd.IS_DELETED, 0) = 0
    GROUP BY sdeg.STUDENT_DEGREE_NAME, sdeg.STUDENT_DEGREE_NAME_EN

    UNION ALL

    -- by status
    SELECT 'status',
           ISNULL(sss.STUDENT_STUDY_STATUS_NAME, N'??? ????'),
           ISNULL(COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME), N'Unspecified'),
           COUNT(*)
    FROM MOHECORE.STUDENT_DATA sd
    LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
    WHERE ISNULL(sd.IS_DELETED, 0) = 0
    GROUP BY sss.STUDENT_STUDY_STATUS_NAME, sss.STUDENT_STUDY_STATUS_NAME_EN
) base;
GO

/* �� V_Enrollment_Statistics ������������������������������������������� */
CREATE   VIEW MOHECORE.V_Enrollment_Statistics AS

SELECT
    ISNULL(sd.STUDENT_ADDED_QUARTER, 0) AS enrollment_quarter,
    sd.STUDY_COUNTRY_IN AS study_country_in_id,                     -- tenant key
    -- These five are the entity's composite key. Hibernate returns a null entity
    -- for any row where a key component is null, and with the lookup joins now
    -- LEFT they can be: STUDENT_DEGREE_ID is unset on 937 of 941 students. 0 is
    -- the existing "unset" sentinel here, already used for enrollment_quarter.
    ISNULL(sd.STUDENT_COUNTRY_ID, 0)    AS STUDENT_COUNTRY_ID,       -- nationality
    ISNULL(sd.STUDENT_MAJOR_ID, 0)      AS STUDENT_MAJOR_ID,
    ISNULL(sd.STUDENT_DEGREE_ID, 0)     AS STUDENT_DEGREE_ID,
    ISNULL(sd.STUDENT_STUDY_TYPE_ID, 0) AS STUDENT_STUDY_TYPE_ID,
    ISNULL(sc.STUDENT_COUNTRY_NAME, N'') AS STUDENT_COUNTRY_NAME,
    ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME), N'') AS STUDENT_COUNTRY_NAME_EN,
    ISNULL(sm.STUDENT_MAJOR_NAME, N'') AS STUDENT_MAJOR_NAME,
    ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'') AS STUDENT_MAJOR_NAME_EN,
    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'') AS STUDENT_DEGREE_NAME,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'') AS STUDENT_DEGREE_NAME_EN,
    ISNULL(sst.STUDENT_STUDY_TYPE_NAME, N'') AS STUDENT_STUDY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sst.STUDENT_STUDY_TYPE_NAME_EN, N''), sst.STUDENT_STUDY_TYPE_NAME), N'') AS STUDENT_STUDY_TYPE_NAME_EN,
    COUNT(sd.STUDENT_ID) AS student_count
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDENT_COUNTRY     sc   ON sc.STUDENT_COUNTRY_ID     = sd.STUDENT_COUNTRY_ID
LEFT JOIN MOHECORE.STUDENT_MAJOR       sm   ON sm.STUDENT_MAJOR_ID       = sd.STUDENT_MAJOR_ID
LEFT JOIN MOHECORE.STUDENT_DEGREE      sdeg ON sdeg.STUDENT_DEGREE_ID    = sd.STUDENT_DEGREE_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE  sst  ON sst.STUDENT_STUDY_TYPE_ID = sd.STUDENT_STUDY_TYPE_ID
WHERE ISNULL(sd.IS_DELETED, 0) = 0
GROUP BY sd.STUDENT_ADDED_QUARTER, sd.STUDY_COUNTRY_IN, ISNULL(sd.STUDENT_COUNTRY_ID, 0),
         ISNULL(sd.STUDENT_MAJOR_ID, 0), ISNULL(sd.STUDENT_DEGREE_ID, 0), ISNULL(sd.STUDENT_STUDY_TYPE_ID, 0),
         sc.STUDENT_COUNTRY_NAME, sm.STUDENT_MAJOR_NAME, sdeg.STUDENT_DEGREE_NAME,
         sst.STUDENT_STUDY_TYPE_NAME,
         sc.STUDENT_COUNTRY_NAME_EN,
         sm.STUDENT_MAJOR_NAME_EN,
         sdeg.STUDENT_DEGREE_NAME_EN,
         sst.STUDENT_STUDY_TYPE_NAME_EN;
GO

CREATE   VIEW MOHECORE.V_Export_Manager AS
WITH access_summary AS (
    SELECT
        l.REPORT_CODE,
        l.STUDY_COUNTRY_IN_ID,
        MAX(l.ACCESSED_AT) AS last_export_date,
        MAX(CASE WHEN l.EXPORT_FORMAT IN (N'PDF', N'XLSX', N'DOC')
                 THEN l.EXPORT_FORMAT END) AS last_export_format,
        -- The most recent export's figures, not the largest: these describe
        -- "what you last got", which is what the screen's column headings claim.
        MAX(CASE WHEN l.ACCESSED_AT = m.latest THEN l.ROW_COUNT END)  AS last_row_count,
        MAX(CASE WHEN l.ACCESSED_AT = m.latest THEN l.SIZE_BYTES END) AS last_size_bytes
    FROM MOHECORE.REPORT_ACCESS_LOG l
    CROSS APPLY (
        SELECT MAX(l2.ACCESSED_AT) AS latest
        FROM MOHECORE.REPORT_ACCESS_LOG l2
        WHERE l2.REPORT_CODE = l.REPORT_CODE
          AND (l2.STUDY_COUNTRY_IN_ID = l.STUDY_COUNTRY_IN_ID
               OR (l2.STUDY_COUNTRY_IN_ID IS NULL AND l.STUDY_COUNTRY_IN_ID IS NULL))
    ) m
    GROUP BY l.REPORT_CODE, l.STUDY_COUNTRY_IN_ID
)
SELECT
    CAST(s.REPORT_TYPE_ID AS BIGINT) AS export_id,
    COALESCE(NULLIF(LTRIM(RTRIM(s.REPORT_TYPE_NAME_AR)), N''),
             CAST(s.REPORT_TYPE_NAME_EN AS NVARCHAR(510))) AS report_name,
    CAST(COALESCE(NULLIF(LTRIM(RTRIM(s.REPORT_TYPE_NAME_EN)), ''), s.REPORT_TYPE_NAME_AR) AS NVARCHAR(510)) AS report_name_en,
    CAST(COALESCE(NULLIF(LTRIM(RTRIM(s.TITLE_01_AR)), N''),
                  CAST(s.TITLE_01_EN AS NVARCHAR(1000))) AS NVARCHAR(1000)) AS report_description,
    CAST(COALESCE(NULLIF(LTRIM(RTRIM(s.TITLE_01_EN)), ''), s.TITLE_01_AR) AS NVARCHAR(1000)) AS report_description_en,
    a.last_row_count AS total_records,
    CASE WHEN s.IS_ACTIVE = 1 THEN N'available' ELSE N'unavailable' END AS export_status,
    -- Rounded up: a 400-byte export is "1 KB", not "0 KB". NULL stays NULL --
    -- a report nobody has exported has no size, which is not the same as zero.
    CAST(CASE WHEN a.last_size_bytes IS NULL THEN NULL
              ELSE (a.last_size_bytes + 1023) / 1024 END AS INT) AS estimated_size_kb,
    CAST(a.last_export_date AS DATETIME) AS last_export_date,
    COALESCE(a.last_export_format, N'PDF') AS default_format,
    CAST(s.IS_ACTIVE AS INT) AS is_available,
    -- The report catalogue itself is ministry-wide; the country comes from who
    -- has exported it. NULL = never exported, so visible to everyone.
    a.STUDY_COUNTRY_IN_ID AS study_country_in_id
FROM MOHECORE.REPORT_TYPE_SETTINGS s
LEFT JOIN access_summary a ON a.REPORT_CODE = s.REPORT_TYPE_CODE;
GO

/* �� V_Fee_Structure ������������������������������������������� */
CREATE   VIEW MOHECORE.V_Fee_Structure AS


SELECT

    CAST(sui.STUDY_UNIVERSITY_IN_ID AS BIGINT) AS university_id,

    sdeg.STUDENT_DEGREE_ID                     AS degree_level_id,

    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'')  AS university_name,
    ISNULL(COALESCE(NULLIF(sui.STUDY_UNIVERSITY_IN_NAME_EN, N''), sui.STUDY_UNIVERSITY_IN_NAME), N'') AS university_name_en,

    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'')  AS university_name_ar,

    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'')     AS country_name,
    ISNULL(COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME), N'') AS country_name_en,

    sui.STUDY_COUNTRY_IN_ID AS country_id,

    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'')      AS degree_level_name,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'') AS degree_level_name_en,

    COUNT(DISTINCT sd.STUDENT_ID) AS total_students,

    CAST(AVG(CAST(suf.STUDY_UNIVERSITY_FEE_AMOUNT AS DECIMAL(18,2))) AS DECIMAL(18,2)) AS avg_fee_amount,

    CAST(MIN(CAST(suf.STUDY_UNIVERSITY_FEE_AMOUNT AS DECIMAL(18,2))) AS DECIMAL(18,2)) AS min_fee_amount,

    CAST(MAX(CAST(suf.STUDY_UNIVERSITY_FEE_AMOUNT AS DECIMAL(18,2))) AS DECIMAL(18,2)) AS max_fee_amount,

    CAST(SUM(CAST(suf.STUDY_UNIVERSITY_FEE_AMOUNT AS DECIMAL(18,2))) AS DECIMAL(18,2)) AS total_fees_paid,

    COUNT(suf.STUDY_UNIVERSITY_FEE_ID) AS total_transactions,

    CASE WHEN COUNT(suf.STUDY_UNIVERSITY_FEE_ID) = 0 THEN CAST(0 AS DECIMAL(18,2))

         ELSE CAST(SUM(CAST(suf.STUDY_UNIVERSITY_FEE_AMOUNT AS DECIMAL(18,2))) / COUNT(suf.STUDY_UNIVERSITY_FEE_ID) AS DECIMAL(18,2))

    END AS avg_per_transaction

FROM MOHECORE.STUDY_UNIVERSITY_IN sui

CROSS JOIN MOHECORE.STUDENT_DEGREE sdeg

LEFT JOIN MOHECORE.STUDY_COUNTRY_IN sci ON sci.STUDY_COUNTRY_IN_ID = sui.STUDY_COUNTRY_IN_ID

LEFT JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDY_UNIVERSITY_IN = sui.STUDY_UNIVERSITY_IN_ID

                                   AND sd.STUDENT_DEGREE_ID = sdeg.STUDENT_DEGREE_ID

                                   AND ISNULL(sd.IS_DELETED, 0) = 0

LEFT JOIN MOHECORE.STUDY_UNIVERSITY_FEE suf ON suf.STUDENT_ID = sd.STUDENT_ID

GROUP BY sui.STUDY_UNIVERSITY_IN_ID, sui.STUDY_UNIVERSITY_IN_NAME, sui.STUDY_COUNTRY_IN_ID, sci.STUDY_COUNTRY_IN_NAME,

         sdeg.STUDENT_DEGREE_ID, sdeg.STUDENT_DEGREE_NAME,
         sui.STUDY_UNIVERSITY_IN_NAME_EN,
         sci.STUDY_COUNTRY_IN_NAME_EN,
         sdeg.STUDENT_DEGREE_NAME_EN

HAVING COUNT(DISTINCT sd.STUDENT_ID) > 0;
GO

CREATE   VIEW MOHECORE.V_Financial_Audit AS
SELECT
    'AUDIT' + CAST(sf.STUDENT_FIN_ID AS VARCHAR(10))                     AS audit_id,
    sf.STUDY_CHECK_DATE                                                  AS audit_date,
    CAST(NULLIF(srws.STUDY_RECEIVED_WHOM_STATUS_NAME, '') AS NVARCHAR(255)) AS audit_category,
    sf.STUDENT_FIN_RECIEVED_AMOUNT                                       AS audit_amount,
    CAST(NULLIF(cur.STUDY_CURRENCY_IN_NAME, '') AS NVARCHAR(100))        AS audit_currency,
    CAST(NULLIF(sfrs.STUDY_FIN_RECEIVED_STATUS_NAME, '') AS NVARCHAR(255)) AS audit_status,
    CAST(NULLIF(dof.STUDY_FINANCE_DOF_NAME, '') AS NVARCHAR(255))        AS auditor_name,
    CAST(COALESCE(
            NULLIF(CAST(sf.STUDY_CHECK_DETAILS AS NVARCHAR(MAX)), ''),
            NULLIF(CAST(sf.STUDY_NOTE_1 AS NVARCHAR(MAX)), '')
        ) AS NVARCHAR(1000))                                             AS audit_notes,
    sd.STUDENT_NAME                                                      AS student_name,
    sd.STUDENT_PASSPORT_NUMBER                                           AS student_passport,
    bank.STUDY_FINANCE_BANKE_NAME                                        AS bank_name,
    sf.STUDENT_FIN_RECIEVED_YEAR                                         AS fiscal_year,
    CASE
        WHEN sf.STUDENT_FIN_RECIEVED_MONTH IS NULL OR sf.STUDENT_FIN_RECIEVED_MONTH <= 0 THEN NULL
        ELSE ((sf.STUDENT_FIN_RECIEVED_MONTH - 1) / 3) + 1
    END                                                                  AS fiscal_quarter
FROM MOHECORE.STUDENT_FINANCE sf
INNER JOIN MOHECORE.STUDENT_DATA sd ON sf.STUDENT_ID = sd.STUDENT_ID
LEFT JOIN MOHECORE.STUDY_FIN_RECEIVED_STATUS  sfrs ON sf.STUDY_FIN_RECIEVED_STATUS    = sfrs.STUDY_FIN_RECEIVED_STATUS_ID
LEFT JOIN MOHECORE.STUDY_RECEIVED_WHOM_STATUS srws ON sf.STUDY_RECEIVED_WHOM_STATUS_ID = srws.STUDY_RECEIVED_WHOM_STATUS_ID
LEFT JOIN MOHECORE.STUDY_FINANCE_BANK         bank ON sf.STUDY_FINANCE_BANKE_ID        = bank.STUDY_FINANCE_BANKE_ID
LEFT JOIN MOHECORE.STUDY_FINANCE_DOF          dof  ON sf.STUDY_FINANCE_DOF_ID          = dof.STUDY_FINANCE_DOF_ID
LEFT JOIN MOHECORE.STUDY_CURRENCY_IN          cur  ON sf.STUDY_CURRENCY_IN_ID          = cur.STUDY_CURRENCY_IN_ID
WHERE sf.STUDENT_FIN_RECIEVED_AMOUNT IS NOT NULL;
GO

/* �� 21/34. V_Growth_Analysis ����������������������������������������������� */
-- ============================================================

-- 9. V_Growth_Analysis

--    Year-over-year growth by category

-- ============================================================

CREATE   VIEW MOHECORE.V_Growth_Analysis AS

WITH yearly AS (

    SELECT

        YEAR(GETDATE()) - n AS analysis_year,

        'total_students' AS growth_category,

        COUNT(sd.STUDENT_ID) AS cnt

    FROM MOHECORE.STUDENT_DATA sd

    CROSS JOIN (VALUES (0),(1),(2),(3),(4)) AS y(n)

    WHERE ISNULL(sd.IS_DELETED, 0) = 0

      AND TRY_CAST(sd.STUDENT_DELEGATION_DECISION_YEAR AS INT) <= YEAR(GETDATE()) - n

    GROUP BY n

)

SELECT

    growth_category,

    analysis_year,

    cnt AS current_value,

    LAG(cnt) OVER (PARTITION BY growth_category ORDER BY analysis_year) AS previous_value,

    CASE

        WHEN LAG(cnt) OVER (PARTITION BY growth_category ORDER BY analysis_year) = 0 THEN NULL

        ELSE CAST((cnt - LAG(cnt) OVER (PARTITION BY growth_category ORDER BY analysis_year)) * 100.0

                  / LAG(cnt) OVER (PARTITION BY growth_category ORDER BY analysis_year) AS DECIMAL(8,2))

    END AS growth_rate,

    cnt - LAG(cnt) OVER (PARTITION BY growth_category ORDER BY analysis_year) AS absolute_growth,

    CASE

        WHEN cnt > LAG(cnt) OVER (PARTITION BY growth_category ORDER BY analysis_year) THEN 'growing'

        WHEN cnt < LAG(cnt) OVER (PARTITION BY growth_category ORDER BY analysis_year) THEN 'declining'

        ELSE 'stable'

    END AS growth_status

FROM yearly;
GO

/* �� V_Major_Distribution ������������������������������������������� */
CREATE   VIEW MOHECORE.V_Major_Distribution AS

SELECT
    sd.STUDY_COUNTRY_IN AS study_country_in_id,                     -- tenant key
    -- Composite key components, coalesced for the same reason as above.
    ISNULL(sd.STUDENT_MAJOR_ID, 0)      AS STUDENT_MAJOR_ID,
    ISNULL(sd.STUDENT_DEGREE_ID, 0)     AS STUDENT_DEGREE_ID,
    ISNULL(sd.STUDENT_COUNTRY_ID, 0)    AS STUDENT_COUNTRY_ID,       -- nationality
    ISNULL(sd.STUDENT_STUDY_TYPE_ID, 0) AS STUDENT_STUDY_TYPE_ID,
    ISNULL(sm.STUDENT_MAJOR_NAME, N'') AS STUDENT_MAJOR_NAME,
    ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'') AS STUDENT_MAJOR_NAME_EN,
    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'') AS STUDENT_DEGREE_NAME,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'') AS STUDENT_DEGREE_NAME_EN,
    ISNULL(sc.STUDENT_COUNTRY_NAME, N'') AS STUDENT_COUNTRY_NAME,
    ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME), N'') AS STUDENT_COUNTRY_NAME_EN,
    ISNULL(sst.STUDENT_STUDY_TYPE_NAME, N'') AS STUDENT_STUDY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sst.STUDENT_STUDY_TYPE_NAME_EN, N''), sst.STUDENT_STUDY_TYPE_NAME), N'') AS STUDENT_STUDY_TYPE_NAME_EN,
    COUNT(sd.STUDENT_ID) AS student_count,
    SUM(CASE WHEN sg.STUDENT_GENDER_NAME_EN LIKE N'Male%'   THEN 1 ELSE 0 END) AS male_count,
    SUM(CASE WHEN sg.STUDENT_GENDER_NAME_EN LIKE N'Female%' THEN 1 ELSE 0 END) AS female_count
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDENT_MAJOR       sm   ON sm.STUDENT_MAJOR_ID       = sd.STUDENT_MAJOR_ID
LEFT JOIN MOHECORE.STUDENT_DEGREE      sdeg ON sdeg.STUDENT_DEGREE_ID    = sd.STUDENT_DEGREE_ID
LEFT JOIN MOHECORE.STUDENT_COUNTRY     sc   ON sc.STUDENT_COUNTRY_ID     = sd.STUDENT_COUNTRY_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE  sst  ON sst.STUDENT_STUDY_TYPE_ID = sd.STUDENT_STUDY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_GENDER      sg   ON sg.STUDENT_GENDER_ID      = sd.STUDENT_GENDER
WHERE ISNULL(sd.IS_DELETED, 0) = 0
GROUP BY sd.STUDY_COUNTRY_IN, ISNULL(sd.STUDENT_MAJOR_ID, 0), ISNULL(sd.STUDENT_DEGREE_ID, 0),
         ISNULL(sd.STUDENT_COUNTRY_ID, 0), ISNULL(sd.STUDENT_STUDY_TYPE_ID, 0),
         sm.STUDENT_MAJOR_NAME, sdeg.STUDENT_DEGREE_NAME, sc.STUDENT_COUNTRY_NAME,
         sst.STUDENT_STUDY_TYPE_NAME,
         sm.STUDENT_MAJOR_NAME_EN,
         sdeg.STUDENT_DEGREE_NAME_EN,
         sc.STUDENT_COUNTRY_NAME_EN,
         sst.STUDENT_STUDY_TYPE_NAME_EN;
GO

CREATE   VIEW MOHECORE.V_Monthly_Report AS
SELECT
    sd.STUDY_COUNTRY_IN AS study_country_id,
    YEAR(sf.STUDY_FINANCE_MIDATE)  AS report_year,
    MONTH(sf.STUDY_FINANCE_MIDATE) AS report_month,
    CAST(YEAR(sf.STUDY_FINANCE_MIDATE) AS NVARCHAR(4)) + '-' +
        RIGHT('0' + CAST(MONTH(sf.STUDY_FINANCE_MIDATE) AS NVARCHAR(2)), 2) AS report_period,
    COUNT(DISTINCT sd.STUDENT_ID)   AS total_students,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'NEW'    THEN sd.STUDENT_ID END) AS new_enrollments,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'ACTIVE' THEN sd.STUDENT_ID END) AS active_students,
    COUNT(*)                        AS total_financial_transactions,
    CAST(SUM(sf.STUDENT_FIN_RECIEVED_AMOUNT) AS DECIMAL(18,2)) AS total_amount_disbursed,
    CASE WHEN COUNT(DISTINCT sd.STUDENT_ID) = 0 THEN 0
         ELSE CAST(SUM(sf.STUDENT_FIN_RECIEVED_AMOUNT) * 1.0 / COUNT(DISTINCT sd.STUDENT_ID) AS DECIMAL(18,2))
    END AS avg_amount_per_student,
    COUNT(DISTINCT CASE WHEN sty.IS_SCHOLARSHIP = 1 THEN sd.STUDENT_ID END) AS scholarship_students,
    COUNT(DISTINCT sd.STUDY_UNIVERSITY_IN) AS total_universities,
    COUNT(DISTINCT sd.STUDY_COUNTRY_IN) AS total_countries
FROM MOHECORE.STUDENT_FINANCE sf
LEFT JOIN MOHECORE.STUDENT_DATA         sd  ON sd.STUDENT_ID               = sf.STUDENT_ID AND ISNULL(sd.IS_DELETED, 0) = 0
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE   sty ON sty.STUDENT_STUDY_TYPE_ID   = sd.STUDENT_STUDY_TYPE_ID
WHERE sf.STUDY_FINANCE_MIDATE IS NOT NULL
GROUP BY sd.STUDY_COUNTRY_IN, YEAR(sf.STUDY_FINANCE_MIDATE), MONTH(sf.STUDY_FINANCE_MIDATE);
GO

/* �� V_Payment_Summary ������������������������������������������� */
CREATE   VIEW MOHECORE.V_Payment_Summary AS

SELECT
    sf.STUDENT_FIN_ID                                                    AS payment_id,
    sd.STUDENT_ID                                                        AS student_id,
    sd.STUDENT_NAME                                                      AS student_name,
    sd.STUDENT_PASSPORT_NUMBER                                           AS student_passport_number,
    CAST(sf.STUDY_CHECK_DATE AS DATE)                                    AS payment_date,
    sf.NET_AMOUNT                                                        AS payment_amount,
    cur.STUDY_CURRENCY_IN_NAME                                           AS payment_currency,
    COALESCE(NULLIF(cur.STUDY_CURRENCY_IN_NAME_EN, N''), cur.STUDY_CURRENCY_IN_NAME) AS payment_currency_en,
    sfrs.STUDY_FIN_RECEIVED_STATUS_NAME                                  AS payment_status,
    COALESCE(NULLIF(sfrs.STUDY_FIN_RECEIVED_STATUS_NAME_EN, N''), sfrs.STUDY_FIN_RECEIVED_STATUS_NAME) AS payment_status_en,
    sfrs.CODE                                                            AS payment_status_code,
    srws.STUDY_RECEIVED_WHOM_STATUS_NAME                                 AS payment_type,
    COALESCE(NULLIF(srws.STUDY_RECEIVED_WHOM_STATUS_NAME_EN, N''), srws.STUDY_RECEIVED_WHOM_STATUS_NAME) AS payment_type_en,
    -- How the money went out, from what the row references (LU_PAYMENT_METHOD codes).
    CASE WHEN sf.STUDY_FINANCE_BANKE_ID IS NOT NULL THEN 'BANK_TRANSFER'
         WHEN sf.STUDY_CHECK_ID IS NOT NULL AND LTRIM(RTRIM(sf.STUDY_CHECK_ID)) <> '' THEN 'CHECK'
         ELSE 'CASH' END                                                 AS payment_method,
    mq.QUARTER_NAME                                                      AS quarter_name,
    COALESCE(NULLIF(mq.QUARTER_NAME_EN, N''), mq.QUARTER_NAME) AS quarter_name_en,
    sf.STUDENT_FIN_RECIEVED_YEAR                                         AS year_name,
    sui.STUDY_UNIVERSITY_IN_NAME                                         AS university_name,
    COALESCE(NULLIF(sui.STUDY_UNIVERSITY_IN_NAME_EN, N''), sui.STUDY_UNIVERSITY_IN_NAME) AS university_name_en,
    smi.STUDY_MAJOR_NAME                                                 AS major_name,
    COALESCE(NULLIF(smi.STUDY_MAJOR_NAME_EN, N''), smi.STUDY_MAJOR_NAME) AS major_name_en,
    sf.STUDENT_FIN_RECIEVED_YEAR                                         AS payment_year,
    sf.STUDENT_FIN_RECIEVED_MONTH                                        AS payment_month
FROM MOHECORE.STUDENT_FINANCE sf
LEFT JOIN MOHECORE.STUDENT_DATA               sd   ON sf.STUDENT_ID                    = sd.STUDENT_ID
LEFT JOIN MOHECORE.STUDY_CURRENCY_IN          cur  ON cur.STUDY_CURRENCY_IN_ID         = sf.STUDY_CURRENCY_IN_ID
LEFT JOIN MOHECORE.STUDY_FIN_RECEIVED_STATUS  sfrs ON sf.STUDY_FIN_RECIEVED_STATUS     = sfrs.STUDY_FIN_RECEIVED_STATUS_ID
LEFT JOIN MOHECORE.STUDY_RECEIVED_WHOM_STATUS srws ON sf.STUDY_RECEIVED_WHOM_STATUS_ID = srws.STUDY_RECEIVED_WHOM_STATUS_ID
LEFT JOIN MOHECORE.MOHE_QUARTER               mq   ON mq.QUARTER = CASE WHEN sf.STUDENT_FIN_RECIEVED_MONTH IS NULL THEN NULL
                                                                        ELSE ((sf.STUDENT_FIN_RECIEVED_MONTH - 1) / 3) + 1 END
LEFT JOIN MOHECORE.STUDY_UNIVERSITY_IN        sui  ON sd.STUDY_UNIVERSITY_IN           = sui.STUDY_UNIVERSITY_IN_ID
LEFT JOIN MOHECORE.STUDY_MAJOR_IN             smi  ON sd.STUDY_MAJOR_IN                = smi.STUDY_MAJOR_ID;
GO

/* �� 5. V_Performance_Metrics ��������������������������������������������������
 * Two changes.
 *
 * The disbursement total carried metric_unit 'LYD'. STUDENT_FINANCE records its
 * currency in STUDY_CURRENCY_IN_ID and that column is NULL on all 941 rows, so
 * the unit is not known - and summing amounts whose currencies are unrecorded is
 * only sound while they are all the same. The unit is NULL and the caveat is
 * here rather than implied by a label.
 *
 * The graduation metric measured itself against a literal 70 and then reported
 * 'on_target' or 'below_target' from it. REPORT_METRIC_TARGET (V028) is where a
 * target belongs; it is empty, so both columns are NULL and the status says
 * 'no_target' rather than passing judgement. Entering one row makes this correct
 * with no further change here.
 * ���������������������������������������������������������������������������� */
CREATE   VIEW MOHECORE.V_Performance_Metrics AS
SELECT metric_category, metric_name, metric_value, metric_unit,
       target_value, achievement_percentage, performance_status, measurement_period
FROM (
    SELECT
        'enrollment'                                    AS metric_category,
        'total_students'                                AS metric_name,
        CAST(COUNT(*) AS DECIMAL(18,2))                 AS metric_value,
        'count'                                         AS metric_unit,
        CAST(NULL AS DECIMAL(18,2))                     AS target_value,
        CAST(NULL AS DECIMAL(18,2))                     AS achievement_percentage,
        'informational'                                 AS performance_status,
        CAST(YEAR(GETDATE()) AS NVARCHAR(10))           AS measurement_period
    FROM MOHECORE.STUDENT_DATA WHERE ISNULL(IS_DELETED, 0) = 0

    UNION ALL

    SELECT
        'finance', 'total_disbursed',
        CAST(ISNULL(SUM(sf.STUDENT_FIN_RECIEVED_AMOUNT), 0) AS DECIMAL(18,2)),
        -- Was 'LYD'. The currency is recorded per row and is not set on any of them.
        CAST(NULL AS NVARCHAR(10)),
        CAST(NULL AS DECIMAL(18,2)), CAST(NULL AS DECIMAL(18,2)), 'informational',
        CAST(YEAR(GETDATE()) AS NVARCHAR(10))
    FROM MOHECORE.STUDENT_FINANCE sf

    UNION ALL

    SELECT
        'graduation', 'graduation_rate',
        CAST(COUNT(CASE WHEN sss.CODE = 'GRADUATED' THEN 1 END) * 100.0
             / NULLIF(COUNT(*), 0) AS DECIMAL(18,2)),
        '%',
        CAST(tgt.TARGET_VALUE AS DECIMAL(18,2)),
        CASE WHEN tgt.TARGET_VALUE IS NULL OR tgt.TARGET_VALUE = 0 THEN NULL
             ELSE CAST(COUNT(CASE WHEN sss.CODE = 'GRADUATED' THEN 1 END) * 100.0
                       / NULLIF(COUNT(*), 0) / tgt.TARGET_VALUE * 100 AS DECIMAL(18,2))
        END,
        CASE
            WHEN tgt.TARGET_VALUE IS NULL THEN 'no_target'
            WHEN COUNT(CASE WHEN sss.CODE = 'GRADUATED' THEN 1 END) * 100.0
                 / NULLIF(COUNT(*), 0) >= tgt.TARGET_VALUE THEN 'on_target'
            ELSE 'below_target'
        END,
        CAST(YEAR(GETDATE()) AS NVARCHAR(10))
    FROM MOHECORE.STUDENT_DATA sd
    LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
    -- Matched on category and name; no country filter, because this view reports
    -- a ministry-wide figure and a per-country target would not apply to it.
    LEFT JOIN MOHECORE.REPORT_METRIC_TARGET tgt
           ON tgt.METRIC_CATEGORY = 'graduation'
          AND tgt.METRIC_NAME     = 'graduation_rate'
          AND tgt.COUNTRY_ID IS NULL
    WHERE ISNULL(sd.IS_DELETED, 0) = 0
    GROUP BY tgt.TARGET_VALUE
) m;
GO

/* �� V_Program_Catalog ������������������������������������������� */
CREATE   VIEW MOHECORE.V_Program_Catalog AS

SELECT
    CAST(sui.STUDY_UNIVERSITY_IN_ID AS BIGINT) AS university_id,
    CAST(sm.STUDENT_MAJOR_ID AS BIGINT) AS major_id,
    sdeg.STUDENT_DEGREE_ID AS degree_level_id,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name,
    ISNULL(COALESCE(NULLIF(sui.STUDY_UNIVERSITY_IN_NAME_EN, N''), sui.STUDY_UNIVERSITY_IN_NAME), N'') AS university_name_en,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name_ar,
    ISNULL(sm.STUDENT_MAJOR_NAME, N'') AS major_name,
    ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'') AS major_name_en,
    ISNULL(sm.STUDENT_MAJOR_NAME, N'') AS major_name_ar,
    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'') AS degree_level_name,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'') AS degree_level_name_en,
    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'') AS country_name,
    ISNULL(COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME), N'') AS country_name_en,
    sui.STUDY_COUNTRY_IN_ID AS country_id,
    COUNT(DISTINCT sd.STUDENT_ID) AS total_students_enrolled,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'ACTIVE' THEN sd.STUDENT_ID END) AS current_students
FROM MOHECORE.STUDY_UNIVERSITY_IN sui
CROSS JOIN MOHECORE.STUDENT_MAJOR sm
CROSS JOIN MOHECORE.STUDENT_DEGREE sdeg
LEFT JOIN MOHECORE.STUDY_COUNTRY_IN sci ON sci.STUDY_COUNTRY_IN_ID = sui.STUDY_COUNTRY_IN_ID
LEFT JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDY_UNIVERSITY_IN = sui.STUDY_UNIVERSITY_IN_ID
                                   AND sd.STUDENT_MAJOR_ID = sm.STUDENT_MAJOR_ID
                                   AND sd.STUDENT_DEGREE_ID = sdeg.STUDENT_DEGREE_ID
                                   AND ISNULL(sd.IS_DELETED, 0) = 0
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
GROUP BY sui.STUDY_UNIVERSITY_IN_ID, sui.STUDY_UNIVERSITY_IN_NAME, sui.STUDY_COUNTRY_IN_ID, sci.STUDY_COUNTRY_IN_NAME,
         sm.STUDENT_MAJOR_ID, sm.STUDENT_MAJOR_NAME, sdeg.STUDENT_DEGREE_ID, sdeg.STUDENT_DEGREE_NAME,
         sui.STUDY_UNIVERSITY_IN_NAME_EN,
         sm.STUDENT_MAJOR_NAME_EN,
         sdeg.STUDENT_DEGREE_NAME_EN,
         sci.STUDY_COUNTRY_IN_NAME_EN
HAVING COUNT(DISTINCT sd.STUDENT_ID) > 0;
GO

CREATE   VIEW MOHECORE.V_Quarterly_Report AS
SELECT
    sd.STUDY_COUNTRY_IN AS study_country_id,
    YEAR(sf.STUDY_FINANCE_MIDATE)              AS report_year,
    DATEPART(QUARTER, sf.STUDY_FINANCE_MIDATE) AS report_quarter,
    CAST(YEAR(sf.STUDY_FINANCE_MIDATE) AS NVARCHAR(4)) + '-Q' +
        CAST(DATEPART(QUARTER, sf.STUDY_FINANCE_MIDATE) AS NVARCHAR(1)) AS report_period,
    COUNT(DISTINCT sd.STUDENT_ID) AS total_students,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'NEW'    THEN sd.STUDENT_ID END) AS new_enrollments,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'ACTIVE' THEN sd.STUDENT_ID END) AS active_students,
    COUNT(*) AS total_financial_transactions,
    CAST(ISNULL(SUM(sf.STUDENT_FIN_RECIEVED_AMOUNT), 0) AS DECIMAL(18,2)) AS total_amount_disbursed,
    CAST(ISNULL(SUM(CASE WHEN sty.IS_SCHOLARSHIP = 1
                         THEN sf.STUDENT_FIN_RECIEVED_AMOUNT ELSE 0 END), 0)
         AS DECIMAL(18,2)) AS scholarship_amount_disbursed,
    CASE WHEN COUNT(DISTINCT sd.STUDENT_ID) = 0 THEN 0
         ELSE CAST(ISNULL(SUM(sf.STUDENT_FIN_RECIEVED_AMOUNT), 0) * 1.0
                   / COUNT(DISTINCT sd.STUDENT_ID) AS DECIMAL(18,2))
    END AS avg_amount_per_student,
    COUNT(DISTINCT CASE WHEN sty.IS_SCHOLARSHIP = 1 THEN sd.STUDENT_ID END) AS scholarship_students,
    COUNT(DISTINCT CASE WHEN sty.IS_SCHOLARSHIP = 0 THEN sd.STUDENT_ID END) AS regular_students,
    COUNT(DISTINCT sd.STUDY_UNIVERSITY_IN) AS total_universities,
    COUNT(DISTINCT sd.STUDY_COUNTRY_IN)    AS total_countries,
    COUNT(DISTINCT sd.STUDENT_MAJOR_ID)    AS total_majors
FROM MOHECORE.STUDENT_FINANCE sf
LEFT JOIN MOHECORE.STUDENT_DATA         sd  ON sd.STUDENT_ID               = sf.STUDENT_ID
                                           AND ISNULL(sd.IS_DELETED, 0)    = 0
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE   sty ON sty.STUDENT_STUDY_TYPE_ID   = sd.STUDENT_STUDY_TYPE_ID
WHERE sf.STUDY_FINANCE_MIDATE IS NOT NULL
GROUP BY sd.STUDY_COUNTRY_IN,
         YEAR(sf.STUDY_FINANCE_MIDATE),
         DATEPART(QUARTER, sf.STUDY_FINANCE_MIDATE);
GO

/*
    V024 - make V_Query_Builder describe the schema it claims to describe.

    Problem
    -------
    Three of the view's six columns were literals:

        N''            AS column_description,
        CAST(1 AS INT) AS is_filterable,
        CAST(1 AS INT) AS is_sortable

    - column_description was empty on all 1,351 rows, even though 318 columns in
      MOHECORE carry an MS_Description extended property. The documentation was
      in the database and the view discarded it.
    - is_filterable and is_sortable were the constant 1, so "filterable columns"
      returned every column in the schema. The 24 ntext columns cannot appear in
      a WHERE or ORDER BY without an explicit cast, so the flags were not merely
      uninformative, they were wrong.

    It also filtered

        AND c.TABLE_NAME NOT LIKE 'V_%'

    which hid all 39 reporting views - the objects most worth querying - while
    including credential columns (StudentPortalAccount.PasswordHash,
    StudentPortalSession.Token, NOTIFICATION_SETTINGS.SMTP_PASSWORD,
    Users___old.Password) and superseded copies (STUDENT_DATA_BKUP, Users___old).

    Fix
    ---
    Read from sys.objects / sys.columns so views are included alongside tables,
    pick up MS_Description where it exists, derive the two flags from the column
    type, and drop credential columns and superseded objects.

    Credentials are excluded by column name rather than by table: this catalogue
    is what will decide which columns a composed query may select, so a column
    that must never be returned should not be listed as available.

    Passport numbers are deliberately kept. They are part of the model and the
    student documents already print them; restricting who may read them belongs
    with the query engine's permission rules, not with the data dictionary.

    Expected shape after applying:

        columns   objects   views included   non-filterable   described
        2,055     180       39               24 (ntext)       318

    (previously: 1,351 columns, 134 objects, 0 views, 0 non-filterable, 0 described)

    Scope
    -----
    The query builder page no longer reads this view - QueryBuilderRepository
    builds the same catalogue directly, so the page did not have to wait for this
    script. Applying it brings the view into line for any other consumer and
    stops the two definitions drifting apart.

    Apply in SSMS.
*/

CREATE   VIEW MOHECORE.V_Query_Builder AS
SELECT
    o.name AS table_name,
    c.name AS column_name,
    TYPE_NAME(c.user_type_id) AS data_type,
    CAST(ISNULL(CAST(ep.value AS NVARCHAR(400)), N'') AS NVARCHAR(400)) AS column_description,
    CASE WHEN TYPE_NAME(c.user_type_id) IN
              ('text','ntext','image','xml','varbinary','binary','geography','geometry','hierarchyid','sql_variant')
         THEN 0 ELSE 1 END AS is_filterable,
    CASE WHEN TYPE_NAME(c.user_type_id) IN
              ('text','ntext','image','xml','varbinary','binary','geography','geometry','hierarchyid','sql_variant')
         THEN 0 ELSE 1 END AS is_sortable
FROM sys.objects o
INNER JOIN sys.columns c
        ON c.object_id = o.object_id
LEFT JOIN sys.extended_properties ep
       ON ep.major_id = c.object_id
      AND ep.minor_id = c.column_id
      AND ep.class = 1
      AND ep.name = 'MS_Description'
WHERE o.schema_id = SCHEMA_ID('MOHECORE')
  AND o.type IN ('U', 'V')
  AND o.is_ms_shipped = 0
  AND o.name NOT LIKE '%[_][_][_]old'
  AND o.name NOT LIKE '%[_]BKUP'
  AND o.name NOT LIKE '%[_]BAK'
  AND o.name <> 'sysdiagrams'
  AND c.name NOT LIKE '%PASSWORD%'
  AND c.name NOT LIKE '%TOKEN%'
  AND c.name NOT LIKE '%SECRET%'
  AND c.name NOT LIKE '%[_]SALT%'
  AND c.name NOT LIKE '%APIKEY%'
  AND c.name NOT LIKE '%API[_]KEY%';
GO

/* �� 3. V_Report_Template: real usage, and no invented status ������������� */
CREATE   VIEW MOHECORE.V_Report_Template AS
SELECT
    q.SAVED_QUERY_ID AS template_id,
    q.QUERY_NAME AS template_name,
    q.DESCRIPTION AS template_description,
    q.SOURCE_NAME AS report_type,
    q.SPEC_JSON AS filter_configuration,
    CAST(JSON_QUERY(q.SPEC_JSON, '$.columns') AS NVARCHAR(MAX)) AS selected_columns,
    q.LAST_ROW_COUNT AS estimated_records,
    CAST(q.CREATED_AT AS DATETIME) AS created_date,
    -- Last *used*, not last edited. UPDATED_AT is the fallback for queries saved
    -- before V106, which have no run recorded.
    CAST(COALESCE(q.LAST_RUN_AT, q.UPDATED_AT) AS DATETIME) AS last_used_date,
    q.USAGE_COUNT AS usage_count,
    CAST(q.IS_SHARED AS INT) AS is_public,
    q.STUDY_COUNTRY_IN_ID AS study_country_in_id
FROM MOHECORE.SAVED_QUERY q;
GO

CREATE   VIEW MOHECORE.V_Scheduled_Report AS
SELECT
    CAST(r.SCHEDULE_ID AS BIGINT) AS schedule_id,
    r.SCHEDULE_NAME AS schedule_name,
    r.SCHEDULE_DESCRIPTION AS schedule_description,
    r.FREQUENCY AS frequency,
    CAST(r.NEXT_RUN_DATE AS DATETIME) AS next_run_date,
    CAST(r.LAST_RUN_DATE AS DATETIME) AS last_run_date,
    r.SCHEDULE_STATUS AS schedule_status,
    r.RECORDS_IN_LAST_RUN AS records_in_last_run,
    r.RECIPIENT_EMAIL AS recipient_email,
    CAST(r.IS_ENABLED AS INT) AS is_enabled,
    r.STUDY_COUNTRY_IN_ID AS study_country_in_id
FROM MOHECORE.SCHEDULED_REPORT r;
GO

/* �� V_Scholarship_Tracking ������������������������������������������� */
CREATE   VIEW MOHECORE.V_Scholarship_Tracking AS

SELECT
    CAST(ROW_NUMBER() OVER (ORDER BY sd.STUDENT_ID) AS BIGINT)          AS scholarship_id,
    sd.STUDENT_ID                                                        AS student_id,
    sd.STUDENT_NAME                                                      AS student_name,
    sd.STUDENT_PASSPORT_NUMBER                                           AS student_passport_number,
    sst.STUDENT_STUDY_TYPE_NAME                                          AS scholarship_type,
    COALESCE(NULLIF(sst.STUDENT_STUDY_TYPE_NAME_EN, N''), sst.STUDENT_STUDY_TYPE_NAME) AS scholarship_type_en,
    sat.STUDENT_AGENCY_TYPE_NAME                                         AS scholarship_provider,
    COALESCE(NULLIF(sat.STUDENT_AGENCY_TYPE_NAME_EN, N''), sat.STUDENT_AGENCY_TYPE_NAME) AS scholarship_provider_en,
    -- The recorded allowance (STUDENT_AMOUNT) in the currency on the record.
    CAST(sd.STUDENT_AMOUNT AS DECIMAL(18, 2))                            AS scholarship_amount,
    CAST(NULLIF(cur.STUDY_CURRENCY_IN_NAME, '') AS NVARCHAR(100))        AS scholarship_currency,
    CAST(sd.STUDENT_MIDATE AS DATE)                                      AS allocated_date,
    CAST(sd.STUDENT_MIDATE AS DATE)                                      AS start_date,
    -- Start plus the recorded study length; nothing is assumed when it is not recorded.
    CAST(CASE WHEN sd.STUDENT_STUDY_NO_OF_YEARS IS NULL THEN NULL
              ELSE DATEADD(YEAR, sd.STUDENT_STUDY_NO_OF_YEARS, sd.STUDENT_MIDATE) END AS DATE) AS end_date,
    -- Sum of the finance rows whose status is RECEIVED (an empty set sums to 0).
    COALESCE(sf_totals.total_paid, 0)                                    AS amount_paid,
    sss.STUDENT_STUDY_STATUS_NAME                                        AS scholarship_status,
    COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME) AS scholarship_status_en,
    sss.CODE                                                             AS scholarship_status_code,
    sui.STUDY_UNIVERSITY_IN_NAME                                         AS university_name,
    COALESCE(NULLIF(sui.STUDY_UNIVERSITY_IN_NAME_EN, N''), sui.STUDY_UNIVERSITY_IN_NAME) AS university_name_en,
    smi.STUDY_MAJOR_NAME                                                 AS major_name,
    COALESCE(NULLIF(smi.STUDY_MAJOR_NAME_EN, N''), smi.STUDY_MAJOR_NAME) AS major_name_en
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE   sst ON sd.STUDENT_STUDY_TYPE_ID   = sst.STUDENT_STUDY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_AGENCY_TYPE  sat ON sd.STUDENT_AGENCY_TYPE_ID  = sat.STUDENT_AGENCY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sd.STUDENT_STUDY_STATUS_ID = sss.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDY_UNIVERSITY_IN  sui ON sd.STUDY_UNIVERSITY_IN     = sui.STUDY_UNIVERSITY_IN_ID
LEFT JOIN MOHECORE.STUDY_MAJOR_IN       smi ON sd.STUDY_MAJOR_IN          = smi.STUDY_MAJOR_ID
LEFT JOIN MOHECORE.STUDY_CURRENCY_IN    cur ON sd.amount_currency         = cur.STUDY_CURRENCY_IN_ID
LEFT JOIN (
    SELECT sf.STUDENT_ID, SUM(sf.STUDENT_FIN_RECIEVED_AMOUNT) AS total_paid
    FROM MOHECORE.STUDENT_FINANCE sf
    JOIN MOHECORE.STUDY_FIN_RECEIVED_STATUS s ON s.STUDY_FIN_RECEIVED_STATUS_ID = sf.STUDY_FIN_RECIEVED_STATUS
    WHERE s.CODE = 'RECEIVED'
    GROUP BY sf.STUDENT_ID
) sf_totals ON sf_totals.STUDENT_ID = sd.STUDENT_ID
WHERE sd.STUDENT_ID IS NOT NULL;
GO

/* -- V_STUD_DATA_CALC_ALL_1 -------------------------------------- */
CREATE   VIEW MOHECORE.V_STUD_DATA_CALC_ALL_1 AS

SELECT 

    SD.STUDENT_ID,

    SD.STUDENT_NAME,

    SD.STUDENT_COUNTRY_ID,

    SD.STUDENT_DELEGATION_DECISION_YEAR,

    SD.STUDENT_DEGREE_ID,

    SD.STUDENT_MAJOR_ID,

   -- SD.STUDENT_MAJOR_NAME,

    SD.STUDENT_DELEGATE_DECISION_NO,

    SD.STUDENT_STUDY_NO_OF_YEARS,

    SD.STUDENT_CURRENT_LEVEL_ID,

    SD.STUDENT_FIRST_RECEIPT_OF_DUE,

    SD.STUDENT_AMOUNT,

    SD.STUDENT_NOTE_1,

    SD.STUDENT_NOTE_2,

    SD.STUDENT_STUDY_STATUS_ID,

    SD.STUDENT_AGENCY_TYPE_ID,

    SD.STUDENT_MINISTRY_TYPE_ID,

    SD.STUDENT_STUDY_TYPE_ID,

    SD.STUDENT_UNIVERSITY_TYPE_ID,

    -- Lookup Names from Other Tables

    SSS.STUDENT_STUDY_STATUS_NAME,
    COALESCE(NULLIF(SSS.STUDENT_STUDY_STATUS_NAME_EN, N''), SSS.STUDENT_STUDY_STATUS_NAME) AS STUDENT_STUDY_STATUS_NAME_EN,

    SAT.STUDENT_AGENCY_TYPE_NAME,
    COALESCE(NULLIF(SAT.STUDENT_AGENCY_TYPE_NAME_EN, N''), SAT.STUDENT_AGENCY_TYPE_NAME) AS STUDENT_AGENCY_TYPE_NAME_EN,

    SC.STUDENT_COUNTRY_NAME,
    COALESCE(NULLIF(SC.STUDENT_COUNTRY_NAME_EN, N''), SC.STUDENT_COUNTRY_NAME) AS STUDENT_COUNTRY_NAME_EN,

    SDG.STUDENT_DEGREE_NAME,
    COALESCE(NULLIF(SDG.STUDENT_DEGREE_NAME_EN, N''), SDG.STUDENT_DEGREE_NAME) AS STUDENT_DEGREE_NAME_EN,

    SMJ.STUDENT_MAJOR_NAME,
    COALESCE(NULLIF(SMJ.STUDENT_MAJOR_NAME_EN, N''), SMJ.STUDENT_MAJOR_NAME) AS STUDENT_MAJOR_NAME_EN,

    SMT.STUDENT_MINISTRY_TYPE_NAME,
    COALESCE(NULLIF(SMT.STUDENT_MINISTRY_TYPE_NAME_EN, N''), SMT.STUDENT_MINISTRY_TYPE_NAME) AS STUDENT_MINISTRY_TYPE_NAME_EN,

    SUT.STUDENT_UNIVERSITY_TYPE_NAME,
    COALESCE(NULLIF(SUT.STUDENT_UNIVERSITY_TYPE_NAME_EN, N''), SUT.STUDENT_UNIVERSITY_TYPE_NAME) AS STUDENT_UNIVERSITY_TYPE_NAME_EN,

    -- Derived / Calculated Columns (Safe Conversion)

    (TRY_CAST(LEFT(SD.STUDENT_DELEGATION_DECISION_YEAR, 4) AS INT) + SD.STUDENT_STUDY_NO_OF_YEARS) AS END_STUDY_YEAR,

    (TRY_CAST(LEFT(SD.STUDENT_DELEGATION_DECISION_YEAR, 4) AS INT) + SD.STUDENT_CURRENT_LEVEL_ID) AS CURRENT_STUDY_YEAR,

    (4 * SD.STUDENT_STUDY_NO_OF_YEARS) AS NO_OF_QUARTER_ALL,

    (4 * SD.STUDENT_STUDY_NO_OF_YEARS) * SD.STUDENT_AMOUNT AS AMOUNT_OF_QUARTER_MONEY_ALL,

    LEFT(SD.STUDENT_FIRST_RECEIPT_OF_DUE, 4) AS STUDENT_FIRST_RECEIPT_OF_DUE_YEAR,

    RIGHT(SD.STUDENT_FIRST_RECEIPT_OF_DUE, 1) AS STUDENT_FIRST_RECEIPT_OF_DUE_QUARTER,

    (TRY_CAST(LEFT(SD.STUDENT_FIRST_RECEIPT_OF_DUE, 4) AS INT) + SD.STUDENT_STUDY_NO_OF_YEARS) AS END_STUDY_YEAR_WITHOUT_ADDTIONAL,

    RIGHT(SD.STUDENT_FIRST_RECEIPT_OF_DUE, 1) AS STUDENT_FINAL_RECEIPT_OF_DUE_QUARTER_NO_ADDITIONAL,

    (ROUND((SD.STUDENT_STUDY_NO_OF_YEARS * 4.0) / 3.0, 0) - 1) AS STUDENT_ADDITIONAL_QUARTER_ALL,

    ((ROUND((SD.STUDENT_STUDY_NO_OF_YEARS * 4.0) / 3.0, 0) - 1) * SD.STUDENT_AMOUNT) AS STUDENT_ADDITIONAL_QUARTER_MONEY_ALL

FROM 

    MOHECORE.STUDENT_DATA SD

    INNER JOIN MOHECORE.STUDENT_STUDY_STATUS SSS 

        ON SD.STUDENT_STUDY_STATUS_ID = SSS.STUDENT_STUDY_STATUS_ID

    INNER JOIN MOHECORE.STUDENT_CURRENT_LEVEL SCL

        ON SD.STUDENT_CURRENT_LEVEL_ID = SCL.STUDENT_CURRENT_LEVEL_ID

    INNER JOIN MOHECORE.STUDENT_AGENCY_TYPE SAT

        ON SD.STUDENT_AGENCY_TYPE_ID = SAT.STUDENT_AGENCY_TYPE_ID

    INNER JOIN MOHECORE.STUDENT_COUNTRY SC

        ON SD.STUDENT_COUNTRY_ID = SC.STUDENT_COUNTRY_ID

    INNER JOIN MOHECORE.STUDENT_DEGREE SDG

        ON SD.STUDENT_DEGREE_ID = SDG.STUDENT_DEGREE_ID

    INNER JOIN MOHECORE.STUDENT_MAJOR SMJ

        ON SD.STUDENT_MAJOR_ID = SMJ.STUDENT_MAJOR_ID

    INNER JOIN MOHECORE.STUDENT_MINISTRY_TYPE SMT

        ON SD.STUDENT_MINISTRY_TYPE_ID = SMT.STUDENT_MINISTRY_TYPE_ID

    INNER JOIN MOHECORE.STUDENT_UNIVERSITY_TYPE SUT

        ON SD.STUDENT_UNIVERSITY_TYPE_ID = SUT.STUDENT_UNIVERSITY_TYPE_ID;
GO

/* �� 3. V_Student_Demographics �������������������������������������������� */
CREATE   VIEW MOHECORE.V_Student_Demographics AS
SELECT
    sd.STUDENT_ID,
    sd.STUDENT_NAME,
    -- Tenant key. STUDENT_COUNTRY_ID below is the student's nationality and is
    -- deliberately NOT the column scope filters on.
    sd.STUDY_COUNTRY_IN                  AS study_country_in_id,
    sd.STUDENT_COUNTRY_ID,
    ISNULL(sc.STUDENT_COUNTRY_NAME, N'') AS STUDENT_COUNTRY_NAME,
    ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME), N'') AS STUDENT_COUNTRY_NAME_EN,
    ISNULL(sg.STUDENT_GENDER_NAME, N'')  AS STUDENT_GENDER,
    ISNULL(COALESCE(NULLIF(sg.STUDENT_GENDER_NAME_EN, N''), sg.STUDENT_GENDER_NAME), N'') AS STUDENT_GENDER_EN,
    TRY_CAST(sd.STUDENT_AGE AS INT)      AS student_age,
    sd.STUDENT_CURRENT_LEVEL_ID,
    ISNULL(scl.STUDENT_CURRENT_LEVEL_NAME, N'') AS STUDENT_CURRENT_LEVEL_NAME,
    ISNULL(COALESCE(NULLIF(scl.STUDENT_CURRENT_LEVEL_NAME_EN, N''), scl.STUDENT_CURRENT_LEVEL_NAME), N'') AS STUDENT_CURRENT_LEVEL_NAME_EN,
    sd.STUDENT_STUDY_TYPE_ID,
    ISNULL(sst.STUDENT_STUDY_TYPE_NAME, N'') AS STUDENT_STUDY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sst.STUDENT_STUDY_TYPE_NAME_EN, N''), sst.STUDENT_STUDY_TYPE_NAME), N'') AS STUDENT_STUDY_TYPE_NAME_EN,
    sd.STUDENT_DEGREE_ID,
    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'') AS STUDENT_DEGREE_NAME,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'') AS STUDENT_DEGREE_NAME_EN,
    sd.STUDENT_MAJOR_ID,
    ISNULL(sm.STUDENT_MAJOR_NAME, N'') AS STUDENT_MAJOR_NAME,
    ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'') AS STUDENT_MAJOR_NAME_EN,
    sd.STUDENT_STUDY_STATUS_ID,
    ISNULL(sss.STUDENT_STUDY_STATUS_NAME, N'') AS STUDENT_STUDY_STATUS_NAME,
    ISNULL(COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME), N'') AS STUDENT_STUDY_STATUS_NAME_EN
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDENT_COUNTRY       sc   ON sc.STUDENT_COUNTRY_ID         = sd.STUDENT_COUNTRY_ID
LEFT JOIN MOHECORE.STUDENT_GENDER        sg   ON sg.STUDENT_GENDER_ID          = sd.STUDENT_GENDER
LEFT JOIN MOHECORE.STUDENT_CURRENT_LEVEL scl  ON scl.STUDENT_CURRENT_LEVEL_ID  = sd.STUDENT_CURRENT_LEVEL_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE    sst  ON sst.STUDENT_STUDY_TYPE_ID     = sd.STUDENT_STUDY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_DEGREE        sdeg ON sdeg.STUDENT_DEGREE_ID        = sd.STUDENT_DEGREE_ID
LEFT JOIN MOHECORE.STUDENT_MAJOR         sm   ON sm.STUDENT_MAJOR_ID           = sd.STUDENT_MAJOR_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS  sss  ON sss.STUDENT_STUDY_STATUS_ID   = sd.STUDENT_STUDY_STATUS_ID
WHERE ISNULL(sd.IS_DELETED, 0) = 0;
GO

/* �� V_Student_Distribution_University ������������������������������������������� */
CREATE   VIEW MOHECORE.V_Student_Distribution_University AS

SELECT
    CAST(sui.STUDY_UNIVERSITY_IN_ID AS BIGINT) AS university_id,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name,
    ISNULL(COALESCE(NULLIF(sui.STUDY_UNIVERSITY_IN_NAME_EN, N''), sui.STUDY_UNIVERSITY_IN_NAME), N'') AS university_name_en,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name_ar,
    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'') AS country_name,
    ISNULL(COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME), N'') AS country_name_en,
    sui.STUDY_COUNTRY_IN_ID AS country_id,
    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'') AS country_name_ar,
    COUNT(sd.STUDENT_ID) AS total_students,
    COUNT(CASE WHEN sss.CODE = 'ACTIVE'    THEN 1 END) AS active_students,
    COUNT(CASE WHEN sss.CODE = 'SUSPENDED' THEN 1 END) AS suspended_students,
    COUNT(CASE WHEN sg.CODE = 'MALE'   THEN 1 END) AS male_students,
    COUNT(CASE WHEN sg.CODE = 'FEMALE' THEN 1 END) AS female_students,
    COUNT(CASE WHEN sty.IS_SCHOLARSHIP = 1 THEN 1 END) AS scholarship_students,
    COUNT(CASE WHEN sty.IS_SCHOLARSHIP = 0 THEN 1 END) AS regular_students,
    COUNT(CASE WHEN sdeg.LEVEL_CODE = 'BACHELOR' THEN 1 END) AS bachelors_students,
    COUNT(CASE WHEN sdeg.LEVEL_CODE = 'MASTER'   THEN 1 END) AS masters_students,
    COUNT(CASE WHEN sdeg.LEVEL_CODE = 'PHD'      THEN 1 END) AS phd_students,
    COUNT(DISTINCT sd.STUDENT_MAJOR_ID) AS programs_count,
    CAST(COUNT(sd.STUDENT_ID) * 100.0 / NULLIF(SUM(COUNT(sd.STUDENT_ID)) OVER (), 0) AS DECIMAL(5,2)) AS percentage_of_total_students
FROM MOHECORE.STUDY_UNIVERSITY_IN sui
LEFT JOIN MOHECORE.STUDY_COUNTRY_IN     sci  ON sci.STUDY_COUNTRY_IN_ID     = sui.STUDY_COUNTRY_IN_ID
LEFT JOIN MOHECORE.STUDENT_DATA         sd   ON sd.STUDY_UNIVERSITY_IN      = sui.STUDY_UNIVERSITY_IN_ID
                                            AND ISNULL(sd.IS_DELETED, 0) = 0
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss  ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_GENDER       sg   ON sg.STUDENT_GENDER_ID        = sd.STUDENT_GENDER
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE   sty  ON sty.STUDENT_STUDY_TYPE_ID   = sd.STUDENT_STUDY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_DEGREE       sdeg ON sdeg.STUDENT_DEGREE_ID      = sd.STUDENT_DEGREE_ID
GROUP BY sui.STUDY_UNIVERSITY_IN_ID, sui.STUDY_UNIVERSITY_IN_NAME, sui.STUDY_COUNTRY_IN_ID, sci.STUDY_COUNTRY_IN_NAME,
         sui.STUDY_UNIVERSITY_IN_NAME_EN,
         sci.STUDY_COUNTRY_IN_NAME_EN;
GO

CREATE   VIEW MOHECORE.V_STUDENT_FINANCIAL_STATEMENT
AS
WITH FIN_ROWS AS (
    -- Closed quarters: the archive keeps the amount/wafar/net as they were
    -- at quarter close, so these rows are read verbatim.
    SELECT
        CONCAT('A-', fa.FIN_ARCH_ENTRY_ID)         AS ROW_KEY,
        'ARCHIVE'                                  AS SOURCE_TYPE,
        fa.STUDENT_ID,
        fa.MOHE_QUARTER_ID,
        fa.STUDENT_FIN_RECIEVED_YEAR               AS RECEIVED_YEAR,
        fa.STUDENT_FIN_RECIEVED_MONTH              AS RECEIVED_MONTH,
        fa.STUDENT_FIN_RECIEVED_AMOUNT             AS RECEIVED_AMOUNT,
        fa.WAFAR_AMOUNT,
        fa.WAFAR_TYPE_ID,
        COALESCE(fa.NET_AMOUNT,
                 ISNULL(fa.STUDENT_FIN_RECIEVED_AMOUNT, 0) - ISNULL(fa.WAFAR_AMOUNT, 0)) AS NET_AMOUNT,
        CAST(NULL AS INT)                          AS CURRENCY_ID,
        fa.STUDY_FINANCE_BANKE_ID                  AS BANK_ID,
        fa.STUDY_FINANCE_BANK_BRANCH_ID            AS BANK_BRANCH_ID,
        fa.STUDY_FIN_RECIEVED_STATUS               AS RECEIVED_STATUS_ID,
        fa.STUDY_RECEIVED_WHOM_STATUS_ID           AS RECEIVED_WHOM_STATUS_ID,
        fa.STUDY_CHECK_ID,
        fa.STUDY_CHECK_DATE,
        fa.STUDY_CHECK_FORM_NUMBER
    FROM MOHECORE.STUDENT_FINANCE_ARCH fa

    UNION ALL

    -- Live (current-quarter) row - suppressed once the same quarter has been
    -- archived for the student, so statements never double-count a quarter.
    SELECT
        CONCAT('C-', sf.STUDENT_ID),
        'CURRENT',
        sf.STUDENT_ID,
        sf.MOHE_QUARTER_ID,
        sf.STUDENT_FIN_RECIEVED_YEAR,
        sf.STUDENT_FIN_RECIEVED_MONTH,
        sf.STUDENT_FIN_RECIEVED_AMOUNT,
        sf.WAFAR_AMOUNT,
        sf.WAFAR_TYPE_ID,
        COALESCE(sf.NET_AMOUNT,
                 ISNULL(sf.STUDENT_FIN_RECIEVED_AMOUNT, 0) - ISNULL(sf.WAFAR_AMOUNT, 0)),
        sf.STUDY_CURRENCY_IN_ID,
        sf.STUDY_FINANCE_BANKE_ID,
        sf.STUDY_FINANCE_BANK_BRANCH_ID,
        sf.STUDY_FIN_RECIEVED_STATUS,
        sf.STUDY_RECEIVED_WHOM_STATUS_ID,
        sf.STUDY_CHECK_ID,
        sf.STUDY_CHECK_DATE,
        sf.STUDY_CHECK_FORM_NUMBER
    FROM MOHECORE.STUDENT_FINANCE sf
    WHERE NOT EXISTS (
        SELECT 1 FROM MOHECORE.STUDENT_FINANCE_ARCH fa2
        WHERE fa2.STUDENT_ID = sf.STUDENT_ID
          AND fa2.MOHE_QUARTER_ID = sf.MOHE_QUARTER_ID
    )
)
SELECT
    fr.ROW_KEY,
    fr.SOURCE_TYPE,
    fr.STUDENT_ID,
    fr.MOHE_QUARTER_ID,
    q.QUARTER_YEAR,
    q.QUARTER_NO,
    q.QUARTER_NAME                                 AS QUARTER_NAME_AR,
    COALESCE(NULLIF(q.QUARTER_NAME_EN, ''), q.QUARTER_NAME) AS QUARTER_NAME_EN,
    fr.RECEIVED_YEAR,
    fr.RECEIVED_MONTH,
    fr.RECEIVED_AMOUNT,
    fr.WAFAR_AMOUNT,
    fr.WAFAR_TYPE_ID,
    wt.WAFAR_NAME                                  AS WAFAR_TYPE_NAME_AR,
    COALESCE(NULLIF(wt.WAFAR_NAME_EN, ''), wt.WAFAR_NAME) AS WAFAR_TYPE_NAME_EN,
    fr.NET_AMOUNT,
    fr.CURRENCY_ID,
    cur.STUDY_CURRENCY_IN_NAME                     AS CURRENCY_NAME_AR,
    COALESCE(NULLIF(cur.STUDY_CURRENCY_IN_NAME_EN, ''), cur.STUDY_CURRENCY_IN_NAME) AS CURRENCY_NAME_EN,
    fr.BANK_ID,
    bk.STUDY_FINANCE_BANKE_NAME                    AS BANK_NAME_AR,
    COALESCE(NULLIF(bk.STUDY_FINANCE_BANKE_NAME_EN, ''), bk.STUDY_FINANCE_BANKE_NAME) AS BANK_NAME_EN,
    fr.BANK_BRANCH_ID,
    bb.STUDY_FINANCE_BANK_BRANCH_NAME              AS BANK_BRANCH_NAME_AR,
    COALESCE(NULLIF(bb.STUDY_FINANCE_BANK_BRANCH_NAME_EN, ''), bb.STUDY_FINANCE_BANK_BRANCH_NAME) AS BANK_BRANCH_NAME_EN,
    fr.RECEIVED_STATUS_ID,
    rs.STUDY_FIN_RECEIVED_STATUS_NAME              AS RECEIVED_STATUS_NAME_AR,
    COALESCE(NULLIF(rs.STUDY_FIN_RECEIVED_STATUS_NAME_EN, ''), rs.STUDY_FIN_RECEIVED_STATUS_NAME) AS RECEIVED_STATUS_NAME_EN,
    fr.RECEIVED_WHOM_STATUS_ID,
    rws.STUDY_RECEIVED_WHOM_STATUS_NAME            AS RECEIVED_WHOM_STATUS_NAME_AR,
    COALESCE(NULLIF(rws.STUDY_RECEIVED_WHOM_STATUS_NAME_EN, ''), rws.STUDY_RECEIVED_WHOM_STATUS_NAME) AS RECEIVED_WHOM_STATUS_NAME_EN,
    fr.STUDY_CHECK_ID,
    fr.STUDY_CHECK_DATE,
    fr.STUDY_CHECK_FORM_NUMBER
FROM FIN_ROWS fr
LEFT JOIN MOHECORE.MOHE_QUARTER               q   ON q.QUARTER = fr.MOHE_QUARTER_ID
LEFT JOIN MOHECORE.STUDY_WAFAR_TYPE           wt  ON wt.WAFAR_TYPE_ID = fr.WAFAR_TYPE_ID
LEFT JOIN MOHECORE.STUDY_CURRENCY_IN          cur ON cur.STUDY_CURRENCY_IN_ID = fr.CURRENCY_ID
LEFT JOIN MOHECORE.STUDY_FINANCE_BANK         bk  ON bk.STUDY_FINANCE_BANKE_ID = fr.BANK_ID
LEFT JOIN MOHECORE.STUDY_FINANCE_BANK_BRANCH  bb  ON bb.STUDY_FINANCE_BANK_BRANCH_ID = fr.BANK_BRANCH_ID
LEFT JOIN MOHECORE.STUDY_FIN_RECEIVED_STATUS  rs  ON rs.STUDY_FIN_RECEIVED_STATUS_ID = fr.RECEIVED_STATUS_ID
LEFT JOIN MOHECORE.STUDY_RECEIVED_WHOM_STATUS rws ON rws.STUDY_RECEIVED_WHOM_STATUS_ID = fr.RECEIVED_WHOM_STATUS_ID;
GO

/* �� 1. V_Student_List_Detailed ������������������������������������������� */
CREATE   VIEW MOHECORE.V_Student_List_Detailed AS
SELECT
    sd.STUDENT_ID,
    sd.STUDENT_NAME,
    sd.STUDENT_PASSPORT_NUMBER,
    CAST(sd.STUDENT_BIRTHDATE AS DATE)   AS STUDENT_BIRTHDATE,
    TRY_CAST(sd.STUDENT_AGE AS INT)      AS student_age,
    sd.STUDY_COUNTRY_IN                  AS study_country_in_id,
    sd.STUDENT_COUNTRY_ID,
    ISNULL(sc.STUDENT_COUNTRY_NAME, N'') AS STUDENT_COUNTRY_NAME,
    ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME), N'') AS STUDENT_COUNTRY_NAME_EN,
    ISNULL(sg.STUDENT_GENDER_NAME, N'')  AS STUDENT_GENDER,
    ISNULL(COALESCE(NULLIF(sg.STUDENT_GENDER_NAME_EN, N''), sg.STUDENT_GENDER_NAME), N'') AS STUDENT_GENDER_EN,
    sd.STUDENT_MAJOR_ID,
    ISNULL(sm.STUDENT_MAJOR_NAME, N'') AS STUDENT_MAJOR_NAME,
    ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'') AS STUDENT_MAJOR_NAME_EN,
    sd.STUDENT_DEGREE_ID,
    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'') AS STUDENT_DEGREE_NAME,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'') AS STUDENT_DEGREE_NAME_EN,
    sd.STUDENT_CURRENT_LEVEL_ID,
    ISNULL(scl.STUDENT_CURRENT_LEVEL_NAME, N'') AS STUDENT_CURRENT_LEVEL_NAME,
    ISNULL(COALESCE(NULLIF(scl.STUDENT_CURRENT_LEVEL_NAME_EN, N''), scl.STUDENT_CURRENT_LEVEL_NAME), N'') AS STUDENT_CURRENT_LEVEL_NAME_EN,
    sd.STUDENT_STUDY_TYPE_ID,
    ISNULL(sst.STUDENT_STUDY_TYPE_NAME, N'') AS STUDENT_STUDY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sst.STUDENT_STUDY_TYPE_NAME_EN, N''), sst.STUDENT_STUDY_TYPE_NAME), N'') AS STUDENT_STUDY_TYPE_NAME_EN,
    sd.STUDENT_STUDY_STATUS_ID,
    ISNULL(sss.STUDENT_STUDY_STATUS_NAME, N'') AS STUDENT_STUDY_STATUS_NAME,
    ISNULL(COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME), N'') AS STUDENT_STUDY_STATUS_NAME_EN,
    sd.STUDENT_UNIVERSITY_TYPE_ID,
    ISNULL(sut.STUDENT_UNIVERSITY_TYPE_NAME, N'') AS STUDENT_UNIVERSITY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sut.STUDENT_UNIVERSITY_TYPE_NAME_EN, N''), sut.STUDENT_UNIVERSITY_TYPE_NAME), N'') AS STUDENT_UNIVERSITY_TYPE_NAME_EN,
    sd.STUDENT_AGENCY_TYPE_ID,
    ISNULL(sat.STUDENT_AGENCY_TYPE_NAME, N'') AS STUDENT_AGENCY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(sat.STUDENT_AGENCY_TYPE_NAME_EN, N''), sat.STUDENT_AGENCY_TYPE_NAME), N'') AS STUDENT_AGENCY_TYPE_NAME_EN,
    sd.STUDENT_MINISTRY_TYPE_ID,
    ISNULL(smt.STUDENT_MINISTRY_TYPE_NAME, N'') AS STUDENT_MINISTRY_TYPE_NAME,
    ISNULL(COALESCE(NULLIF(smt.STUDENT_MINISTRY_TYPE_NAME_EN, N''), smt.STUDENT_MINISTRY_TYPE_NAME), N'') AS STUDENT_MINISTRY_TYPE_NAME_EN,
    sd.STUDENT_STUDY_NO_OF_YEARS,
    sd.STUDENT_DELEGATION_DECISION_YEAR,
    sd.STUDENT_ADDED_QUARTER,
    CAST(sd.STUDENT_PASSPORT_ISSUE_DATE AS DATE)  AS STUDENT_PASSPORT_ISSUE_DATE,
    CAST(sd.STUDENT_PASSPORT_EXPIRE_DATE AS DATE) AS STUDENT_PASSPORT_EXPIRE_DATE
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDENT_COUNTRY          sc   ON sc.STUDENT_COUNTRY_ID          = sd.STUDENT_COUNTRY_ID
LEFT JOIN MOHECORE.STUDENT_GENDER           sg   ON sg.STUDENT_GENDER_ID           = sd.STUDENT_GENDER
LEFT JOIN MOHECORE.STUDENT_MAJOR            sm   ON sm.STUDENT_MAJOR_ID            = sd.STUDENT_MAJOR_ID
LEFT JOIN MOHECORE.STUDENT_DEGREE           sdeg ON sdeg.STUDENT_DEGREE_ID         = sd.STUDENT_DEGREE_ID
LEFT JOIN MOHECORE.STUDENT_CURRENT_LEVEL    scl  ON scl.STUDENT_CURRENT_LEVEL_ID   = sd.STUDENT_CURRENT_LEVEL_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE       sst  ON sst.STUDENT_STUDY_TYPE_ID      = sd.STUDENT_STUDY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS     sss  ON sss.STUDENT_STUDY_STATUS_ID    = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_UNIVERSITY_TYPE  sut  ON sut.STUDENT_UNIVERSITY_TYPE_ID = sd.STUDENT_UNIVERSITY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_AGENCY_TYPE      sat  ON sat.STUDENT_AGENCY_TYPE_ID     = sd.STUDENT_AGENCY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_MINISTRY_TYPE    smt  ON smt.STUDENT_MINISTRY_TYPE_ID   = sd.STUDENT_MINISTRY_TYPE_ID
WHERE ISNULL(sd.IS_DELETED, 0) = 0;
GO

/*
 * Views backing the four official single-student documents
 * (ID Card, Registration Form, Enrollment Certificate, Financial Statement).
 *
 * V_STUDENT_PROFILE_DOC
 *   One row per (non-deleted) student with EVERY lookup FK resolved to a
 *   paired *_NAME_AR / *_NAME_EN column. All lookup joins are LEFT JOINs on
 *   purpose: a missing or inactive lookup row must never make a student
 *   disappear from their own document - it just prints an empty value.
 *   The EN column falls back to the Arabic name (NULLIF + COALESCE) because
 *   the legacy lookups are only partially translated.
 *
 * V_STUDENT_FINANCIAL_STATEMENT
 *   One row per finance record for a student: the archived quarter rows
 *   (STUDENT_FINANCE_ARCH - these carry the wafar and net the student had
 *   when the quarter closed) plus the live STUDENT_FINANCE row for the
 *   current quarter. The live row is suppressed when an archive row already
 *   exists for the same student + quarter so totals never double-count.
 *   ROW_KEY is a synthetic unique key for the JPA @Immutable mapping.
 *   Currency is only known on the live row (V014 added it to STUDENT_FINANCE
 *   only), so archive rows report NULL currency.
 *
 * Idempotent - safe to re-run (CREATE OR ALTER).
 */

CREATE   VIEW MOHECORE.V_STUDENT_PROFILE_DOC
AS
SELECT
    sd.STUDENT_ID,
    sd.STUDENT_NAME,
    sd.PICTURE_PATH,
    sd.STUDENT_MIDATE,

    -- Personal
    sd.STUDENT_GENDER                              AS STUDENT_GENDER_ID,
    g.STUDENT_GENDER_NAME                          AS GENDER_NAME_AR,
    COALESCE(NULLIF(g.STUDENT_GENDER_NAME_EN, ''), g.STUDENT_GENDER_NAME) AS GENDER_NAME_EN,
    sd.STUDENT_BIRTHDATE,
    sd.STUDENT_BIRTHDATE_PLACE,
    sd.STUDENT_AGE,

    -- Home country / governorate / municipality
    sd.STUDENT_COUNTRY_ID,
    hc.STUDENT_COUNTRY_NAME                        AS HOME_COUNTRY_NAME_AR,
    COALESCE(NULLIF(hc.STUDENT_COUNTRY_NAME_EN, ''), hc.STUDENT_COUNTRY_NAME) AS HOME_COUNTRY_NAME_EN,
    sd.STUDENT_GOV_ID,
    hg.STUDENT_GOV_NAME                            AS HOME_GOV_NAME_AR,
    COALESCE(NULLIF(hg.STUDENT_GOV_NAME_EN, ''), hg.STUDENT_GOV_NAME)     AS HOME_GOV_NAME_EN,
    sd.STUDENT_MUD_ID,
    hm.STUDENT_MUD_NAME                            AS HOME_MUD_NAME_AR,
    COALESCE(NULLIF(hm.STUDENT_MUD_NAME_EN, ''), hm.STUDENT_MUD_NAME)     AS HOME_MUD_NAME_EN,

    -- Passport
    sd.STUDENT_PASSPORT_NUMBER,
    sd.STUDENT_PASSPORT_ISSUE_DATE,
    sd.STUDENT_PASSPORT_EXPIRE_DATE,
    sd.STUDENT_PASSPORT_ISSUE_COUNTRY_ID,
    pc.STUDENT_COUNTRY_NAME                        AS PASSPORT_COUNTRY_NAME_AR,
    COALESCE(NULLIF(pc.STUDENT_COUNTRY_NAME_EN, ''), pc.STUDENT_COUNTRY_NAME) AS PASSPORT_COUNTRY_NAME_EN,

    -- Academic
    sd.STUDENT_DEGREE_ID,
    deg.STUDENT_DEGREE_NAME                        AS DEGREE_NAME_AR,
    COALESCE(NULLIF(deg.STUDENT_DEGREE_NAME_EN, ''), deg.STUDENT_DEGREE_NAME) AS DEGREE_NAME_EN,
    sd.STUDENT_MAJOR_ID,
    COALESCE(NULLIF(maj.STUDENT_MAJOR_NAME, ''), sd.STUDENT_MAJOR_NAME)   AS MAJOR_NAME_AR,
    COALESCE(NULLIF(maj.STUDENT_MAJOR_NAME_EN, ''), NULLIF(maj.STUDENT_MAJOR_NAME, ''), sd.STUDENT_MAJOR_NAME) AS MAJOR_NAME_EN,
    sd.STUDENT_CURRENT_LEVEL_ID,
    lvl.STUDENT_CURRENT_LEVEL_NAME                 AS LEVEL_NAME_AR,
    COALESCE(NULLIF(lvl.STUDENT_CURRENT_LEVEL_NAME_EN, ''), lvl.STUDENT_CURRENT_LEVEL_NAME) AS LEVEL_NAME_EN,
    sd.STUDENT_STUDY_TYPE_ID,
    styp.STUDENT_STUDY_TYPE_NAME                   AS STUDY_TYPE_NAME_AR,
    COALESCE(NULLIF(styp.STUDENT_STUDY_TYPE_NAME_EN, ''), styp.STUDENT_STUDY_TYPE_NAME) AS STUDY_TYPE_NAME_EN,
    sd.STUDENT_STUDY_STATUS_ID,
    sst.STUDENT_STUDY_STATUS_NAME                  AS STUDY_STATUS_NAME_AR,
    COALESCE(NULLIF(sst.STUDENT_STUDY_STATUS_NAME_EN, ''), sst.STUDENT_STUDY_STATUS_NAME) AS STUDY_STATUS_NAME_EN,
    sd.STUDENT_UNIVERSITY_TYPE_ID,
    ut.STUDENT_UNIVERSITY_TYPE_NAME                AS UNIVERSITY_TYPE_NAME_AR,
    COALESCE(NULLIF(ut.STUDENT_UNIVERSITY_TYPE_NAME_EN, ''), ut.STUDENT_UNIVERSITY_TYPE_NAME) AS UNIVERSITY_TYPE_NAME_EN,
    sd.STUDENT_AGENCY_TYPE_ID,
    agt.STUDENT_AGENCY_TYPE_NAME                   AS AGENCY_TYPE_NAME_AR,
    COALESCE(NULLIF(agt.STUDENT_AGENCY_TYPE_NAME_EN, ''), agt.STUDENT_AGENCY_TYPE_NAME) AS AGENCY_TYPE_NAME_EN,
    sd.STUDENT_MINISTRY_TYPE_ID,
    mt.STUDENT_MINISTRY_TYPE_NAME                  AS MINISTRY_TYPE_NAME_AR,
    COALESCE(NULLIF(mt.STUDENT_MINISTRY_TYPE_NAME_EN, ''), mt.STUDENT_MINISTRY_TYPE_NAME) AS MINISTRY_TYPE_NAME_EN,
    sd.STUDENT_STUDY_NO_OF_YEARS,

    -- Delegation decision
    sd.STUDENT_DELEGATE_DECISION_NO,
    sd.STUDENT_DELEGATION_DECISION_YEAR,

    -- Study destination chain (note: STUDENT_DATA's gov-in FK column is the
    -- historical typo SYUDY_GOV_IN - keep it aliased, never renamed here)
    sd.STUDY_COUNTRY_IN                            AS STUDY_COUNTRY_IN_ID,
    ci.STUDY_COUNTRY_IN_NAME                       AS STUDY_COUNTRY_NAME_AR,
    COALESCE(NULLIF(ci.STUDY_COUNTRY_IN_NAME_EN, ''), ci.STUDY_COUNTRY_IN_NAME) AS STUDY_COUNTRY_NAME_EN,
    sd.SYUDY_GOV_IN                                AS STUDY_GOV_IN_ID,
    gi.STUDY_GOV_IN_NAME                           AS STUDY_GOV_NAME_AR,
    COALESCE(NULLIF(gi.STUDY_GOV_IN_NAME_EN, ''), gi.STUDY_GOV_IN_NAME)   AS STUDY_GOV_NAME_EN,
    sd.STUDY_UNIVERSITY_IN                         AS STUDY_UNIVERSITY_IN_ID,
    ui.STUDY_UNIVERSITY_IN_NAME                    AS STUDY_UNIVERSITY_NAME_AR,
    COALESCE(NULLIF(ui.STUDY_UNIVERSITY_IN_NAME_EN, ''), ui.STUDY_UNIVERSITY_IN_NAME) AS STUDY_UNIVERSITY_NAME_EN,
    sd.STUDY_COLLEGE_IN                            AS STUDY_COLLEGE_IN_ID,
    coli.STUDY_COLLEGE_IN_NAME                     AS STUDY_COLLEGE_NAME_AR,
    COALESCE(NULLIF(coli.STUDY_COLLEGE_IN_NAME_EN, ''), coli.STUDY_COLLEGE_IN_NAME) AS STUDY_COLLEGE_NAME_EN,
    sd.STUDY_EDUCATION_IN                          AS STUDY_EDUCATION_IN_ID,
    edi.STUDY_EDUCTION_NAME                        AS STUDY_EDUCATION_NAME_AR,
    COALESCE(NULLIF(edi.STUDY_EDUCTION_NAME_EN, ''), edi.STUDY_EDUCTION_NAME) AS STUDY_EDUCATION_NAME_EN,
    sd.STUDY_MAJOR_IN                              AS STUDY_MAJOR_IN_ID,
    smi.STUDY_MAJOR_NAME                           AS STUDY_MAJOR_IN_NAME_AR,
    COALESCE(NULLIF(smi.STUDY_MAJOR_NAME_EN, ''), smi.STUDY_MAJOR_NAME)   AS STUDY_MAJOR_IN_NAME_EN,

    -- Scholarship finance summary
    sd.STUDENT_AMOUNT,
    sd.AMOUNT_CURRENCY                             AS AMOUNT_CURRENCY_ID,
    cur.STUDY_CURRENCY_IN_NAME                     AS CURRENCY_NAME_AR,
    COALESCE(NULLIF(cur.STUDY_CURRENCY_IN_NAME_EN, ''), cur.STUDY_CURRENCY_IN_NAME) AS CURRENCY_NAME_EN,

    -- Contacts
    sd.STUDENT_EMAIL,
    sd.STUDENT_CELLPHONE,
    sd.STUDENT_HOME_NUMBER,
    sd.STUDENT_EMERGENCY_CONTACT,

    -- Quarters
    sd.STUDENT_ADDED_QUARTER,
    sd.STUDENT_LAST_QUARTER,
    sd.CURRENT_QUARTER
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDENT_GENDER          g    ON g.STUDENT_GENDER_ID = sd.STUDENT_GENDER
LEFT JOIN MOHECORE.STUDENT_COUNTRY         hc   ON hc.STUDENT_COUNTRY_ID = sd.STUDENT_COUNTRY_ID
LEFT JOIN MOHECORE.STUDENT_GOV             hg   ON hg.STUDENT_GOV_ID = sd.STUDENT_GOV_ID
LEFT JOIN MOHECORE.STUDENT_GOV_MUD         hm   ON hm.STUDENT_MUD_ID = sd.STUDENT_MUD_ID
LEFT JOIN MOHECORE.STUDENT_COUNTRY         pc   ON pc.STUDENT_COUNTRY_ID = sd.STUDENT_PASSPORT_ISSUE_COUNTRY_ID
LEFT JOIN MOHECORE.STUDENT_DEGREE          deg  ON deg.STUDENT_DEGREE_ID = sd.STUDENT_DEGREE_ID
LEFT JOIN MOHECORE.STUDENT_MAJOR           maj  ON maj.STUDENT_MAJOR_ID = sd.STUDENT_MAJOR_ID
LEFT JOIN MOHECORE.STUDENT_CURRENT_LEVEL   lvl  ON lvl.STUDENT_CURRENT_LEVEL_ID = sd.STUDENT_CURRENT_LEVEL_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE      styp ON styp.STUDENT_STUDY_TYPE_ID = sd.STUDENT_STUDY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS    sst  ON sst.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_UNIVERSITY_TYPE ut   ON ut.STUDENT_UNIVERSITY_TYPE_ID = sd.STUDENT_UNIVERSITY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_AGENCY_TYPE     agt  ON agt.STUDENT_AGENCY_TYPE_ID = sd.STUDENT_AGENCY_TYPE_ID
LEFT JOIN MOHECORE.STUDENT_MINISTRY_TYPE   mt   ON mt.STUDENT_MINISTRY_TYPE_ID = sd.STUDENT_MINISTRY_TYPE_ID
LEFT JOIN MOHECORE.STUDY_COUNTRY_IN        ci   ON ci.STUDY_COUNTRY_IN_ID = sd.STUDY_COUNTRY_IN
LEFT JOIN MOHECORE.STUDY_GOV_IN            gi   ON gi.STUDY_GOV_IN_ID = sd.SYUDY_GOV_IN
LEFT JOIN MOHECORE.STUDY_UNIVERSITY_IN     ui   ON ui.STUDY_UNIVERSITY_IN_ID = sd.STUDY_UNIVERSITY_IN
LEFT JOIN MOHECORE.STUDY_COLLEGE_IN        coli ON coli.STUDY_COLLEGE_IN_ID = sd.STUDY_COLLEGE_IN
LEFT JOIN MOHECORE.STUDY_EDUCTION_IN       edi  ON edi.STUDY_EDUCTION_ID = sd.STUDY_EDUCATION_IN
LEFT JOIN MOHECORE.STUDY_MAJOR_IN          smi  ON smi.STUDY_MAJOR_ID = sd.STUDY_MAJOR_IN
LEFT JOIN MOHECORE.STUDY_CURRENCY_IN       cur  ON cur.STUDY_CURRENCY_IN_ID = sd.AMOUNT_CURRENCY
WHERE (sd.IS_DELETED = 0 OR sd.IS_DELETED IS NULL);
GO

/* �� 2. V_Student_Status_Report ���������������������������������������������
   The English names join the GROUP BY beside their Arabic counterparts. They are
   functionally dependent on the same lookup id, so this adds no rows.          */
CREATE   VIEW MOHECORE.V_Student_Status_Report AS
SELECT
    sd.STUDY_COUNTRY_IN AS study_country_in_id,                     -- tenant key
    ISNULL(sd.STUDENT_STUDY_STATUS_ID, 0) AS STUDENT_STUDY_STATUS_ID,
    ISNULL(sd.STUDENT_COUNTRY_ID, 0)      AS STUDENT_COUNTRY_ID,     -- nationality
    ISNULL(sd.STUDENT_MAJOR_ID, 0)        AS STUDENT_MAJOR_ID,
    ISNULL(sss.STUDENT_STUDY_STATUS_NAME, N'') AS STUDENT_STUDY_STATUS_NAME,
    ISNULL(COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME), N'') AS STUDENT_STUDY_STATUS_NAME_EN,
    ISNULL(sc.STUDENT_COUNTRY_NAME, N'') AS STUDENT_COUNTRY_NAME,
    ISNULL(COALESCE(NULLIF(sc.STUDENT_COUNTRY_NAME_EN, N''), sc.STUDENT_COUNTRY_NAME), N'') AS STUDENT_COUNTRY_NAME_EN,
    ISNULL(sm.STUDENT_MAJOR_NAME, N'') AS STUDENT_MAJOR_NAME,
    ISNULL(COALESCE(NULLIF(sm.STUDENT_MAJOR_NAME_EN, N''), sm.STUDENT_MAJOR_NAME), N'') AS STUDENT_MAJOR_NAME_EN,
    COUNT(sd.STUDENT_ID) AS student_count,
    -- Keyed on CODE (V028) rather than the display name, which is user-editable
    -- and language-specific. There is no GRADUATED code in this database.
    CASE
        WHEN sss.CODE = 'ACTIVE'      THEN 'active'
        WHEN sss.CODE = 'NEW'         THEN 'new'
        WHEN sss.CODE = 'SUSPENDED'   THEN 'suspended'
        WHEN sss.CODE = 'WITHDRAWN'   THEN 'withdrawn'
        WHEN sss.CODE = 'TRANSFERRED' THEN 'transferred'
        ELSE 'other'
    END AS status_category
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_COUNTRY      sc  ON sc.STUDENT_COUNTRY_ID       = sd.STUDENT_COUNTRY_ID
LEFT JOIN MOHECORE.STUDENT_MAJOR        sm  ON sm.STUDENT_MAJOR_ID         = sd.STUDENT_MAJOR_ID
WHERE ISNULL(sd.IS_DELETED, 0) = 0
GROUP BY sd.STUDY_COUNTRY_IN, ISNULL(sd.STUDENT_STUDY_STATUS_ID, 0), ISNULL(sd.STUDENT_COUNTRY_ID, 0), ISNULL(sd.STUDENT_MAJOR_ID, 0),
         sss.STUDENT_STUDY_STATUS_NAME, sss.STUDENT_STUDY_STATUS_NAME_EN,
         sc.STUDENT_COUNTRY_NAME,       sc.STUDENT_COUNTRY_NAME_EN,
         sm.STUDENT_MAJOR_NAME,         sm.STUDENT_MAJOR_NAME_EN,
         sss.CODE;
GO

/* -- V_STUDENT_SUMMARY ------------------------------------------- */
CREATE   VIEW MOHECORE.V_STUDENT_SUMMARY AS

SELECT
    -- Core identity
    sd.STUDENT_ID,
    sd.STUDENT_NAME,
    sd.NATIONAL_ID,
    sd.STUDENT_PASSPORT_NUMBER,
    sd.STUDENT_BIRTHDATE,
    sd.STUDENT_AGE,
    sd.STUDENT_GENDER,
    sd.PICTURE_PATH,

    -- Origin location
    sd.STUDENT_COUNTRY_ID,
    sc.STUDENT_COUNTRY_NAME                     AS COUNTRY_NAME,
    sc.STUDENT_COUNTRY_NAME_EN                  AS COUNTRY_NAME_EN,
    sd.STUDENT_GOV_ID,
    sg.STUDENT_GOV_NAME                         AS GOV_NAME,
    sg.STUDENT_GOV_NAME_EN                      AS GOV_NAME_EN,
    sd.STUDENT_MUD_ID,
    mud.STUDENT_MUD_NAME                        AS MUD_NAME,
    mud.STUDENT_MUD_NAME_EN                     AS MUD_NAME_EN,

    -- Academic
    sd.STUDENT_DEGREE_ID,
    sdeg.STUDENT_DEGREE_NAME                    AS DEGREE_NAME,
    sdeg.STUDENT_DEGREE_NAME_EN                 AS DEGREE_NAME_EN,
    sd.STUDENT_MAJOR_ID,
    smaj.STUDENT_MAJOR_NAME                     AS MAJOR_NAME,
    smaj.STUDENT_MAJOR_NAME_EN                  AS MAJOR_NAME_EN,
    sd.STUDENT_MAJOR_NAME                       AS STUDENT_MAJOR_NAME_FREE,
    sd.STUDENT_DELEGATION_DECISION_YEAR,
    sd.STUDENT_DELEGATE_DECISION_NO,
    sd.STUDENT_STUDY_NO_OF_YEARS,
    sd.STUDENT_CURRENT_LEVEL_ID,
    scl.STUDENT_CURRENT_LEVEL_NAME              AS CURRENT_LEVEL_NAME,
    scl.STUDENT_CURRENT_LEVEL_NAME_EN           AS CURRENT_LEVEL_NAME_EN,

    -- Study destination
    sd.STUDY_COUNTRY_IN                         AS STUDY_COUNTRY_IN_ID,
    sci.STUDY_COUNTRY_IN_NAME                   AS STUDY_COUNTRY_NAME,
    sci.STUDY_COUNTRY_IN_NAME_EN                AS STUDY_COUNTRY_NAME_EN,
    sd.STUDY_UNIVERSITY_IN                      AS STUDY_UNIVERSITY_IN_ID,
    sui.STUDY_UNIVERSITY_IN_NAME                AS STUDY_UNIVERSITY_NAME,
    sui.STUDY_UNIVERSITY_IN_NAME_EN             AS STUDY_UNIVERSITY_NAME_EN,

    -- Classification
    sd.STUDENT_STUDY_TYPE_ID,
    sst.STUDENT_STUDY_TYPE_NAME                 AS STUDY_TYPE_NAME,
    sst.STUDENT_STUDY_TYPE_NAME_EN              AS STUDY_TYPE_NAME_EN,
    sd.STUDENT_UNIVERSITY_TYPE_ID,
    sut.STUDENT_UNIVERSITY_TYPE_NAME            AS UNIVERSITY_TYPE_NAME,
    sut.STUDENT_UNIVERSITY_TYPE_NAME_EN         AS UNIVERSITY_TYPE_NAME_EN,
    sd.STUDENT_AGENCY_TYPE_ID,
    sat.STUDENT_AGENCY_TYPE_NAME                AS AGENCY_TYPE_NAME,
    sat.STUDENT_AGENCY_TYPE_NAME_EN             AS AGENCY_TYPE_NAME_EN,
    sd.STUDENT_MINISTRY_TYPE_ID,
    smt.STUDENT_MINISTRY_TYPE_NAME              AS MINISTRY_TYPE_NAME,
    smt.STUDENT_MINISTRY_TYPE_NAME_EN           AS MINISTRY_TYPE_NAME_EN,

    -- Status
    sd.STUDENT_STUDY_STATUS_ID,
    sss.STUDENT_STUDY_STATUS_NAME               AS STUDY_STATUS_NAME,
    sss.STUDENT_STUDY_STATUS_NAME_EN            AS STUDY_STATUS_NAME_EN,

    -- Quarter / financial
    sd.STUDENT_ADDED_QUARTER,
    sd.STUDENT_LAST_QUARTER,
    sd.STUDENT_AMOUNT,
    sd.AMOUNT_CURRENCY,
    sd.STUDENT_FIRST_RECEIPT_OF_DUE,

    -- Soft delete
    ISNULL(sd.IS_DELETED, 0)                    AS IS_DELETED,

    -- Timestamps
    sd.STUDENT_MIDATE                           AS CREATED_DATE

FROM MOHECORE.STUDENT_DATA sd

-- Country of origin
LEFT JOIN MOHECORE.STUDENT_COUNTRY sc
    ON sc.STUDENT_COUNTRY_ID = sd.STUDENT_COUNTRY_ID

-- Governorate
LEFT JOIN MOHECORE.STUDENT_GOV sg
    ON sg.STUDENT_GOV_ID = sd.STUDENT_GOV_ID

-- Municipality
LEFT JOIN MOHECORE.STUDENT_GOV_MUD mud
    ON mud.STUDENT_MUD_ID = sd.STUDENT_MUD_ID

-- Degree
LEFT JOIN MOHECORE.STUDENT_DEGREE sdeg
    ON sdeg.STUDENT_DEGREE_ID = sd.STUDENT_DEGREE_ID

-- Major
LEFT JOIN MOHECORE.STUDENT_MAJOR smaj
    ON smaj.STUDENT_MAJOR_ID = sd.STUDENT_MAJOR_ID

-- Current level
LEFT JOIN MOHECORE.STUDENT_CURRENT_LEVEL scl
    ON scl.STUDENT_CURRENT_LEVEL_ID = sd.STUDENT_CURRENT_LEVEL_ID

-- Study destination country
LEFT JOIN MOHECORE.STUDY_COUNTRY_IN sci
    ON sci.STUDY_COUNTRY_IN_ID = sd.STUDY_COUNTRY_IN

-- Study university
LEFT JOIN MOHECORE.STUDY_UNIVERSITY_IN sui
    ON sui.STUDY_UNIVERSITY_IN_ID = sd.STUDY_UNIVERSITY_IN

-- Study type
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE sst
    ON sst.STUDENT_STUDY_TYPE_ID = sd.STUDENT_STUDY_TYPE_ID

-- University type
LEFT JOIN MOHECORE.STUDENT_UNIVERSITY_TYPE sut
    ON sut.STUDENT_UNIVERSITY_TYPE_ID = sd.STUDENT_UNIVERSITY_TYPE_ID

-- Agency type
LEFT JOIN MOHECORE.STUDENT_AGENCY_TYPE sat
    ON sat.STUDENT_AGENCY_TYPE_ID = sd.STUDENT_AGENCY_TYPE_ID

-- Ministry type
LEFT JOIN MOHECORE.STUDENT_MINISTRY_TYPE smt
    ON smt.STUDENT_MINISTRY_TYPE_ID = sd.STUDENT_MINISTRY_TYPE_ID

-- Study status
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss
    ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID

WHERE ISNULL(sd.IS_DELETED, 0) = 0;
GO

/*
    V022 - period V_Trend_Analysis by the month the money belongs to.

    Problem
    -------
    The view grouped by STUDY_FINANCE_MIDATE, the row's last-modified timestamp:

        WHERE sf.STUDY_FINANCE_MIDATE IS NOT NULL
        GROUP BY YEAR(sf.STUDY_FINANCE_MIDATE), MONTH(sf.STUDY_FINANCE_MIDATE)

    939 of the 941 finance rows were written in one go, so the view returned two
    points - 2025-11 and 2026-05 - and reported a 99.79% collapse between them.
    Neither month contains a scholarship payment. The money sits in 2024-02.

    Fix
    ---
    Derive the period from STUDY_CHECK_DATE where present and from
    STUDENT_FIN_RECIEVED_YEAR / _MONTH otherwise, which are the populated
    columns, and sum NET_AMOUNT so the figures agree with the quarterly financial
    report rather than the gross amount before wafar.

    Expected output after applying:

        period    metric          value        previous     growth   direction
        2024-02   finance_amount  1,533,060                           flat
        2025-01   finance_amount  3,360        1,533,060    -99.78    down
        2026-05   finance_amount  1,000        3,360        -70.24    down

    Scope
    -----
    The trend analysis page no longer reads this view: its rows and its filter
    options are both built in TrendAnalysisRepository, which already applies the
    same derivation together with the country filter the view cannot express.
    This script brings the view into line for any other consumer, and so the two
    definitions do not drift further apart.

    Note that base.total_records is computed and never selected, so the view can
    only ever offer the single metric 'finance_amount'. A second metric would be
    a change in what the page shows, so it is left alone here.

    Apply in SSMS.
*/

CREATE   VIEW MOHECORE.V_Trend_Analysis AS
WITH base AS (
    SELECT
        COALESCE(YEAR(sf.STUDY_CHECK_DATE), sf.STUDENT_FIN_RECIEVED_YEAR)   AS yr,
        COALESCE(MONTH(sf.STUDY_CHECK_DATE), sf.STUDENT_FIN_RECIEVED_MONTH) AS mo,
        SUM(CAST(COALESCE(sf.NET_AMOUNT, 0) AS BIGINT)) AS total_amount,
        COUNT(*) AS total_records
    FROM MOHECORE.STUDENT_FINANCE sf
    WHERE COALESCE(YEAR(sf.STUDY_CHECK_DATE), sf.STUDENT_FIN_RECIEVED_YEAR) IS NOT NULL
      AND COALESCE(MONTH(sf.STUDY_CHECK_DATE), sf.STUDENT_FIN_RECIEVED_MONTH) BETWEEN 1 AND 12
    GROUP BY COALESCE(YEAR(sf.STUDY_CHECK_DATE), sf.STUDENT_FIN_RECIEVED_YEAR),
             COALESCE(MONTH(sf.STUDY_CHECK_DATE), sf.STUDENT_FIN_RECIEVED_MONTH)
)
SELECT
    CAST(yr AS NVARCHAR(4)) + '-' + RIGHT('0' + CAST(mo AS NVARCHAR(2)), 2) AS trend_period,
    'finance_amount' AS metric_type,
    yr AS trend_year,
    mo AS trend_month,
    CAST(total_amount AS DECIMAL(18,2)) AS metric_value,
    LAG(CAST(total_amount AS DECIMAL(18,2))) OVER (ORDER BY yr, mo) AS previous_value,
    CASE
        WHEN LAG(total_amount) OVER (ORDER BY yr, mo) = 0 THEN NULL
        ELSE CAST((total_amount - LAG(total_amount) OVER (ORDER BY yr, mo)) * 100.0
                  / LAG(total_amount) OVER (ORDER BY yr, mo) AS DECIMAL(8,2))
    END AS growth_percentage,
    CASE
        WHEN total_amount > LAG(total_amount) OVER (ORDER BY yr, mo) THEN 'up'
        WHEN total_amount < LAG(total_amount) OVER (ORDER BY yr, mo) THEN 'down'
        ELSE 'flat'
    END AS trend_direction
FROM base;
GO

/* �� V_University_Agreement ������������������������������������������� */
CREATE   VIEW MOHECORE.V_University_Agreement AS

SELECT
    CAST(sui.STUDY_UNIVERSITY_IN_ID AS BIGINT) AS university_id,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name,
    ISNULL(COALESCE(NULLIF(sui.STUDY_UNIVERSITY_IN_NAME_EN, N''), sui.STUDY_UNIVERSITY_IN_NAME), N'') AS university_name_en,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name_ar,
    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'') AS country_name,
    ISNULL(COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME), N'') AS country_name_en,
    sui.STUDY_COUNTRY_IN_ID AS country_id,
    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'') AS country_name_ar,
    COUNT(DISTINCT sd.STUDENT_ID) AS total_students_under_agreement,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'ACTIVE' THEN sd.STUDENT_ID END) AS active_students,
    COUNT(DISTINCT sd.STUDENT_MAJOR_ID) AS programs_covered,
    COUNT(DISTINCT sd.STUDENT_DEGREE_ID) AS degree_levels_covered
FROM MOHECORE.STUDY_UNIVERSITY_IN sui
LEFT JOIN MOHECORE.STUDY_COUNTRY_IN sci ON sci.STUDY_COUNTRY_IN_ID = sui.STUDY_COUNTRY_IN_ID
LEFT JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDY_UNIVERSITY_IN = sui.STUDY_UNIVERSITY_IN_ID
                                   AND ISNULL(sd.IS_DELETED, 0) = 0
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
GROUP BY sui.STUDY_UNIVERSITY_IN_ID, sui.STUDY_UNIVERSITY_IN_NAME, sui.STUDY_COUNTRY_IN_ID, sci.STUDY_COUNTRY_IN_NAME,
         sui.STUDY_UNIVERSITY_IN_NAME_EN,
         sci.STUDY_COUNTRY_IN_NAME_EN;
GO

/* �� V_University_Partnership ������������������������������������������� */
CREATE   VIEW MOHECORE.V_University_Partnership AS

SELECT
    CAST(sui.STUDY_UNIVERSITY_IN_ID AS BIGINT) AS university_id,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name,
    ISNULL(COALESCE(NULLIF(sui.STUDY_UNIVERSITY_IN_NAME_EN, N''), sui.STUDY_UNIVERSITY_IN_NAME), N'') AS university_name_en,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name_ar,
    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'') AS country_name,
    ISNULL(COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME), N'') AS country_name_en,
    sui.STUDY_COUNTRY_IN_ID AS country_id,
    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'') AS country_name_ar,
    COUNT(DISTINCT sd.STUDENT_ID) AS total_students,
    COUNT(DISTINCT sd.STUDENT_MAJOR_ID) AS total_programs,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'ACTIVE' THEN sd.STUDENT_ID END) AS active_students,
    COUNT(DISTINCT sd.STUDENT_DEGREE_ID) AS degree_levels_offered,
    COUNT(DISTINCT CASE WHEN sty.IS_SCHOLARSHIP = 1 THEN sd.STUDENT_ID END) AS scholarship_students,
    COUNT(DISTINCT CASE WHEN sty.IS_SCHOLARSHIP = 0 THEN sd.STUDENT_ID END) AS regular_students
FROM MOHECORE.STUDY_UNIVERSITY_IN sui
LEFT JOIN MOHECORE.STUDY_COUNTRY_IN sci ON sci.STUDY_COUNTRY_IN_ID = sui.STUDY_COUNTRY_IN_ID
LEFT JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDY_UNIVERSITY_IN = sui.STUDY_UNIVERSITY_IN_ID
                                   AND ISNULL(sd.IS_DELETED, 0) = 0
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_STUDY_TYPE   sty ON sty.STUDENT_STUDY_TYPE_ID   = sd.STUDENT_STUDY_TYPE_ID
GROUP BY sui.STUDY_UNIVERSITY_IN_ID, sui.STUDY_UNIVERSITY_IN_NAME, sui.STUDY_COUNTRY_IN_ID, sci.STUDY_COUNTRY_IN_NAME,
         sui.STUDY_UNIVERSITY_IN_NAME_EN,
         sci.STUDY_COUNTRY_IN_NAME_EN;
GO

/* �� V_University_Performance ������������������������������������������� */
CREATE   VIEW MOHECORE.V_University_Performance AS

SELECT
    CAST(sui.STUDY_UNIVERSITY_IN_ID AS BIGINT) AS university_id,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name,
    ISNULL(COALESCE(NULLIF(sui.STUDY_UNIVERSITY_IN_NAME_EN, N''), sui.STUDY_UNIVERSITY_IN_NAME), N'') AS university_name_en,
    ISNULL(sui.STUDY_UNIVERSITY_IN_NAME, N'') AS university_name_ar,
    ISNULL(sci.STUDY_COUNTRY_IN_NAME, N'') AS country_name,
    ISNULL(COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME), N'') AS country_name_en,
    sui.STUDY_COUNTRY_IN_ID AS country_id,
    COUNT(DISTINCT sd.STUDENT_ID) AS total_enrolled,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'ACTIVE'    THEN sd.STUDENT_ID END) AS currently_active,
    COUNT(DISTINCT CASE WHEN sss.CODE = 'SUSPENDED' THEN sd.STUDENT_ID END) AS total_suspended,
    CASE WHEN COUNT(DISTINCT sd.STUDENT_ID) = 0 THEN CAST(0 AS DECIMAL(5,2))
         ELSE CAST(COUNT(DISTINCT CASE WHEN sss.CODE = 'ACTIVE' THEN sd.STUDENT_ID END) * 100.0
                   / COUNT(DISTINCT sd.STUDENT_ID) AS DECIMAL(5,2)) END AS retention_rate,
    CAST(AVG(CAST(NULLIF(sd.STUDENT_STUDY_NO_OF_YEARS, 0) AS DECIMAL(9,4))) AS DECIMAL(5,2)) AS avg_study_duration,
    COUNT(DISTINCT sd.STUDENT_MAJOR_ID) AS programs_offered,
    COUNT(DISTINCT sd.STUDENT_DEGREE_ID) AS degree_levels,
    MIN(TRY_CAST(sd.STUDENT_DELEGATION_DECISION_YEAR AS INT)) AS first_enrollment_year,
    MAX(TRY_CAST(sd.STUDENT_DELEGATION_DECISION_YEAR AS INT)) AS last_enrollment_year
FROM MOHECORE.STUDY_UNIVERSITY_IN sui
LEFT JOIN MOHECORE.STUDY_COUNTRY_IN sci ON sci.STUDY_COUNTRY_IN_ID = sui.STUDY_COUNTRY_IN_ID
LEFT JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDY_UNIVERSITY_IN = sui.STUDY_UNIVERSITY_IN_ID
                                   AND ISNULL(sd.IS_DELETED, 0) = 0
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
GROUP BY sui.STUDY_UNIVERSITY_IN_ID, sui.STUDY_UNIVERSITY_IN_NAME, sui.STUDY_COUNTRY_IN_ID, sci.STUDY_COUNTRY_IN_NAME,
         sui.STUDY_UNIVERSITY_IN_NAME_EN,
         sci.STUDY_COUNTRY_IN_NAME_EN;
GO

/* -- VW_FINANCIAL_BY_QUARTER -------------------------------------------------
   Period from the payment date, budget from the quarter that was budgeted.   */
CREATE   VIEW MOHECORE.VW_FINANCIAL_BY_QUARTER AS
SELECT
    sf.STUDY_COUNTRY_IN_ID AS StudyCountryInId,
    CAST(YEAR(sf.STUDY_FINANCE_MIDATE) AS NVARCHAR(4)) + '-Q'
        + CAST(DATEPART(QUARTER, sf.STUDY_FINANCE_MIDATE) AS NVARCHAR(1)) AS QuarterName,
    SUM(CAST(ISNULL(sf.STUDENT_FIN_RECIEVED_AMOUNT, 0) AS DECIMAL(18,2))) AS TotalReceived,
    -- One MOHE_QUARTER row per (year, quarter), so MAX picks that row's budget
    -- without the join multiplying it across the payments. NULL where the
    -- quarter carries no budget, which is every quarter that has payments.
    CAST(MAX(mq.BUDGET_AMOUNT) AS DECIMAL(18,2)) AS TotalBudget,
    COUNT(DISTINCT sf.STUDENT_ID) AS StudentCount
FROM MOHECORE.STUDENT_FINANCE sf
LEFT JOIN MOHECORE.MOHE_QUARTER mq
       ON mq.QUARTER_YEAR = YEAR(sf.STUDY_FINANCE_MIDATE)
      AND mq.QUARTER_NO   = DATEPART(QUARTER, sf.STUDY_FINANCE_MIDATE)
WHERE sf.STUDY_FINANCE_MIDATE IS NOT NULL
GROUP BY sf.STUDY_COUNTRY_IN_ID,
         YEAR(sf.STUDY_FINANCE_MIDATE),
         DATEPART(QUARTER, sf.STUDY_FINANCE_MIDATE);
GO

/* ��  5/34. VW_FINANCIAL_DATA_BY_YEAR ����������������������������������������������� */
CREATE   VIEW MOHECORE.VW_FINANCIAL_DATA_BY_YEAR AS

SELECT

    sf.STUDY_COUNTRY_IN_ID AS StudyCountryInId,

    sf.STUDENT_FIN_RECIEVED_YEAR AS [Year],

    SUM(CAST(sf.STUDENT_FIN_RECIEVED_AMOUNT AS DECIMAL(18,2))) AS TotalAmount,

    AVG(CAST(sf.STUDENT_FIN_RECIEVED_AMOUNT AS DECIMAL(18,2))) AS AvgAmount,

    COUNT(DISTINCT sf.STUDENT_ID) AS StudentCount

FROM MOHECORE.STUDENT_FINANCE sf

WHERE sf.STUDENT_FIN_RECIEVED_YEAR IS NOT NULL

GROUP BY sf.STUDY_COUNTRY_IN_ID, sf.STUDENT_FIN_RECIEVED_YEAR;
GO

/* -- VW_STUDENT_BY_DEGREE ---------------------------------------- */
CREATE   VIEW MOHECORE.VW_STUDENT_BY_DEGREE AS

SELECT

    sd.STUDY_COUNTRY_IN AS StudyCountryInId,

    ISNULL(sdeg.STUDENT_DEGREE_NAME, N'??? ????') AS DegreeName,
    ISNULL(COALESCE(NULLIF(sdeg.STUDENT_DEGREE_NAME_EN, N''), sdeg.STUDENT_DEGREE_NAME), N'Unspecified') AS DegreeNameEn,

    COUNT(*) AS StudentCount,

    CAST(SUM(ISNULL(sf.STUDENT_FIN_RECIEVED_AMOUNT, 0)) AS DECIMAL(18,2)) AS TotalAmount,

    CAST(AVG(CAST(ISNULL(sf.STUDENT_FIN_RECIEVED_AMOUNT, 0) AS DECIMAL(18,2))) AS DECIMAL(18,2)) AS AvgAmount

FROM MOHECORE.STUDENT_DATA sd

LEFT JOIN MOHECORE.STUDENT_DEGREE sdeg ON sdeg.STUDENT_DEGREE_ID = sd.STUDENT_DEGREE_ID

LEFT JOIN MOHECORE.STUDENT_FINANCE sf ON sf.STUDENT_ID = sd.STUDENT_ID

WHERE ISNULL(sd.IS_DELETED, 0) = 0

GROUP BY sd.STUDY_COUNTRY_IN, sdeg.STUDENT_DEGREE_NAME, sdeg.STUDENT_DEGREE_NAME_EN;
GO

/* -- VW_STUDENT_ENROLLMENT_BY_COUNTRY ---------------------------- */
CREATE   VIEW MOHECORE.VW_STUDENT_ENROLLMENT_BY_COUNTRY AS

SELECT
    sd.STUDY_COUNTRY_IN AS StudyCountryInId,
    sci.STUDY_COUNTRY_IN_NAME AS CountryName,
    COALESCE(NULLIF(sci.STUDY_COUNTRY_IN_NAME_EN, N''), sci.STUDY_COUNTRY_IN_NAME) AS CountryNameEn,
    COUNT(*) AS StudentCount,
    SUM(CASE WHEN sss.CODE = 'ACTIVE' THEN 1 ELSE 0 END) AS ActiveStudents,
    CAST(AVG(CAST(ISNULL(sf.STUDENT_FIN_RECIEVED_AMOUNT, 0) AS DECIMAL(18,2))) AS DECIMAL(18,2)) AS AvgAmount
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDY_COUNTRY_IN     sci ON sci.STUDY_COUNTRY_IN_ID     = sd.STUDY_COUNTRY_IN
LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID
LEFT JOIN MOHECORE.STUDENT_FINANCE      sf  ON sf.STUDENT_ID = sd.STUDENT_ID
WHERE ISNULL(sd.IS_DELETED, 0) = 0
GROUP BY sd.STUDY_COUNTRY_IN, sci.STUDY_COUNTRY_IN_NAME, sci.STUDY_COUNTRY_IN_NAME_EN;
GO

/* ��  8/34. VW_STUDENT_EXTENSIONS ����������������������������������������������� */
-- Create a view for easy querying of student extensions

CREATE   VIEW [MOHECORE].[VW_STUDENT_EXTENSIONS] AS

SELECT 

	sd.STUDENT_ID,

	sd.STUDENT_NAME,

	sd.STUDENT_MAJOR_NAME,

	se.EXTENSION_ID,

	se.EXTENSION_TYPE,

	se.EXTENSION_QUARTERS,

	se.EXTENSION_START_DATE,

	se.EXTENSION_END_DATE,

	DATEDIFF(DAY, se.EXTENSION_START_DATE, se.EXTENSION_END_DATE) AS EXTENSION_DAYS,

	se.EXTENSION_REASON,

	se.EXTENSION_REASON_DETAILS,

	se.EXTENSION_DECISION_NO,

	se.EXTENSION_DECISION_DATE,

	se.APPROVED_BY,

	se.EXTENSION_STATUS,

	se.CREATED_DATE,

	-- Calculate total quarters extended per student

	(SELECT SUM(EXTENSION_QUARTERS) 

	 FROM [MOHECORE].[STUDENT_EXTENSION] 

	 WHERE STUDENT_ID = sd.STUDENT_ID 

	 AND EXTENSION_STATUS = 'ACTIVE') AS TOTAL_QUARTERS_EXTENDED

FROM [MOHECORE].[STUDENT_DATA] sd

INNER JOIN [MOHECORE].[STUDENT_EXTENSION] se ON sd.STUDENT_ID = se.STUDENT_ID;
GO

/* -- VW_STUDENT_FINANCE_PAYMENT_ALL ------------------------------ */
CREATE   VIEW MOHECORE.VW_STUDENT_FINANCE_PAYMENT_ALL AS

SELECT 

    SF.STUDENT_ID,

    SFBB.STUDY_FINANCE_BANK_BRANCH_ID,

    SFBB.STUDY_FINANCE_BANK_BRANCH_NAME,
    COALESCE(NULLIF(SFBB.STUDY_FINANCE_BANK_BRANCH_NAME_EN, N''), SFBB.STUDY_FINANCE_BANK_BRANCH_NAME) AS STUDY_FINANCE_BANK_BRANCH_NAME_EN,

    SD.STUDENT_AGENCY_TYPE_ID,

    SAT.STUDENT_AGENCY_TYPE_NAME,
    COALESCE(NULLIF(SAT.STUDENT_AGENCY_TYPE_NAME_EN, N''), SAT.STUDENT_AGENCY_TYPE_NAME) AS STUDENT_AGENCY_TYPE_NAME_EN,

    SMT.STUDENT_MINISTRY_TYPE_ID,

    SMT.STUDENT_MINISTRY_TYPE_NAME,
    COALESCE(NULLIF(SMT.STUDENT_MINISTRY_TYPE_NAME_EN, N''), SMT.STUDENT_MINISTRY_TYPE_NAME) AS STUDENT_MINISTRY_TYPE_NAME_EN,

    SUT.STUDENT_UNIVERSITY_TYPE_ID,

    SUT.STUDENT_UNIVERSITY_TYPE_NAME,
    COALESCE(NULLIF(SUT.STUDENT_UNIVERSITY_TYPE_NAME_EN, N''), SUT.STUDENT_UNIVERSITY_TYPE_NAME) AS STUDENT_UNIVERSITY_TYPE_NAME_EN,

    CASE 

        WHEN SUT.STUDENT_UNIVERSITY_TYPE_ID = 99 THEN

            CASE 

                WHEN SMT.STUDENT_MINISTRY_TYPE_ID = 99 THEN SAT.STUDENT_AGENCY_TYPE_NAME

                ELSE SMT.STUDENT_MINISTRY_TYPE_NAME

            END

        ELSE SUT.STUDENT_UNIVERSITY_TYPE_NAME

    END AS TYPE_ALL_IS,
    CASE
        WHEN SUT.STUDENT_UNIVERSITY_TYPE_ID = 99 THEN
            CASE
                WHEN SMT.STUDENT_MINISTRY_TYPE_ID = 99 THEN COALESCE(NULLIF(SAT.STUDENT_AGENCY_TYPE_NAME_EN, N''), SAT.STUDENT_AGENCY_TYPE_NAME)
                ELSE COALESCE(NULLIF(SMT.STUDENT_MINISTRY_TYPE_NAME_EN, N''), SMT.STUDENT_MINISTRY_TYPE_NAME)
            END
        ELSE COALESCE(NULLIF(SUT.STUDENT_UNIVERSITY_TYPE_NAME_EN, N''), SUT.STUDENT_UNIVERSITY_TYPE_NAME)
    END AS TYPE_ALL_IS_EN,

    SAT.STUDENT_AGENCY_TYPE_ORDER,

    STATUS_01.STUDENT_ID AS STUDENT_ID_STATUS_01,

    STATUS_01.STUDENT_FIN_RECIEVED_AMOUNT AS STUDENT_FIN_RECIEVED_AMOUNT_STATUS_01,

    STATUS_02.STUDENT_ID AS STUDENT_ID_STATUS_02,

    STATUS_02.STUDENT_FIN_RECIEVED_AMOUNT AS STUDENT_FIN_RECIEVED_AMOUNT_STATUS_02

FROM 

    MOHECORE.STUDENT_FINANCE SF

    INNER JOIN MOHECORE.STUDY_FINANCE_BANK_BRANCH SFBB 

        ON SF.STUDY_FINANCE_BANK_BRANCH_ID = SFBB.STUDY_FINANCE_BANK_BRANCH_ID

    INNER JOIN MOHECORE.STUDENT_DATA SD 

        ON SF.STUDENT_ID = SD.STUDENT_ID

    INNER JOIN MOHECORE.STUDENT_AGENCY_TYPE SAT 

        ON SD.STUDENT_AGENCY_TYPE_ID = SAT.STUDENT_AGENCY_TYPE_ID

    LEFT JOIN MOHECORE.STUDENT_MINISTRY_TYPE SMT 

        ON SD.STUDENT_MINISTRY_TYPE_ID = SMT.STUDENT_MINISTRY_TYPE_ID

    LEFT JOIN MOHECORE.STUDENT_UNIVERSITY_TYPE SUT 

        ON SD.STUDENT_UNIVERSITY_TYPE_ID = SUT.STUDENT_UNIVERSITY_TYPE_ID

    LEFT JOIN (

        SELECT 

            STUDENT_ID,

            STUDY_FIN_RECIEVED_STATUS,

            STUDENT_FIN_RECIEVED_AMOUNT

        FROM MOHECORE.STUDENT_FINANCE

        WHERE STUDY_FIN_RECIEVED_STATUS = 1

    ) STATUS_01 

        ON SF.STUDENT_ID = STATUS_01.STUDENT_ID

    LEFT JOIN (

        SELECT 

            STUDENT_ID,

            STUDY_FIN_RECIEVED_STATUS,

            STUDENT_FIN_RECIEVED_AMOUNT

        FROM MOHECORE.STUDENT_FINANCE

        WHERE STUDY_FIN_RECIEVED_STATUS <> 1

    ) STATUS_02 

        ON SF.STUDENT_ID = STATUS_02.STUDENT_ID;
GO

/* �� 10/34. VW_STUDENT_FINANCIAL_SUMMARY ����������������������������������������������� */
CREATE   VIEW MOHECORE.VW_STUDENT_FINANCIAL_SUMMARY AS
SELECT 
    sc.STUDENT_COUNTRY_NAME as Category,
    'Country' as CategoryType,
    COUNT(DISTINCT sd.STUDENT_ID) as TotalStudents,
    SUM(CAST(sd.STUDENT_AMOUNT as FLOAT)) as BudgetedAmount,
    SUM(CAST(sf.STUDENT_FIN_RECIEVED_AMOUNT as FLOAT)) as ReceivedAmount,
    AVG(CAST(sd.STUDENT_CURRENT_LEVEL_ID as FLOAT)) as AvgLevel
FROM MOHECORE.STUDENT_DATA sd
LEFT JOIN MOHECORE.STUDENT_FINANCE sf ON sd.STUDENT_ID = sf.STUDENT_ID
LEFT JOIN MOHECORE.STUDENT_COUNTRY sc ON sd.STUDENT_COUNTRY_ID = sc.STUDENT_COUNTRY_ID
GROUP BY sc.STUDENT_COUNTRY_NAME;
GO

/* -- VW_STUDENT_STATUS_DISTRIBUTION ------------------------------ */
CREATE   VIEW MOHECORE.VW_STUDENT_STATUS_DISTRIBUTION AS

SELECT

    sd.STUDY_COUNTRY_IN AS StudyCountryInId,

    ISNULL(sss.STUDENT_STUDY_STATUS_NAME, N'??? ????') AS StatusName,
    ISNULL(COALESCE(NULLIF(sss.STUDENT_STUDY_STATUS_NAME_EN, N''), sss.STUDENT_STUDY_STATUS_NAME), N'Unspecified') AS StatusNameEn,

    COUNT(*) AS StudentCount,

    CAST(SUM(ISNULL(sf.STUDENT_FIN_RECIEVED_AMOUNT, 0)) AS DECIMAL(18,2)) AS TotalAmount

FROM MOHECORE.STUDENT_DATA sd

LEFT JOIN MOHECORE.STUDENT_STUDY_STATUS sss ON sss.STUDENT_STUDY_STATUS_ID = sd.STUDENT_STUDY_STATUS_ID

LEFT JOIN MOHECORE.STUDENT_FINANCE sf ON sf.STUDENT_ID = sd.STUDENT_ID

WHERE ISNULL(sd.IS_DELETED, 0) = 0

GROUP BY sd.STUDY_COUNTRY_IN, sss.STUDENT_STUDY_STATUS_NAME, sss.STUDENT_STUDY_STATUS_NAME_EN;
GO

CREATE VIEW MOHENTracer.VW_NETWORK_STATISTICS AS
SELECT
    (SELECT COUNT(*) FROM MOHENTracer.STUDENT_NODE WHERE IS_ACTIVE = 1) AS TOTAL_STUDENTS,
    (SELECT COUNT(*) FROM MOHENTracer.CONNECTION WHERE IS_ACTIVE = 1) AS TOTAL_CONNECTIONS,
    (SELECT COUNT(DISTINCT NODE_ID) FROM MOHENTracer.EMPLOYMENT_HISTORY WHERE IS_CURRENT = 1) AS EMPLOYED_COUNT,
    (SELECT AVG(CAST(CONNECTION_STRENGTH AS FLOAT)) FROM MOHENTracer.CONNECTION WHERE IS_ACTIVE = 1) AS AVG_CONNECTION_STRENGTH,
    (SELECT COUNT(DISTINCT COUNTRY) FROM MOHENTracer.STUDENT_NODE WHERE IS_ACTIVE = 1) AS UNIQUE_COUNTRIES,
    (SELECT COUNT(DISTINCT UNIVERSITY) FROM MOHENTracer.STUDENT_NODE WHERE IS_ACTIVE = 1) AS UNIQUE_UNIVERSITIES,
    GETDATE() AS LAST_UPDATED;
GO

-- Procedure to Create Audit Trigger for a Table
CREATE   PROCEDURE [AUDITLOG].[sp_CreateAuditTrigger]
    @TableName NVARCHAR(100),
    @SchemaName NVARCHAR(100) = 'UMSCORE',
    @PrimaryKeyColumn NVARCHAR(100) = 'Id'
AS
BEGIN
    DECLARE @TriggerName NVARCHAR(200) = 'TR_Audit_' + @TableName;
    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @ColumnList NVARCHAR(MAX);

    -- Build column list with casts for legacy types (text, ntext, image)
    SELECT @ColumnList = STUFF((
        SELECT ', ' + 
        CASE 
            WHEN DATA_TYPE IN ('text', 'ntext', 'image') THEN 'CAST([' + COLUMN_NAME + '] AS NVARCHAR(MAX)) AS [' + COLUMN_NAME + ']'
            ELSE '[' + COLUMN_NAME + ']'
        END
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = @SchemaName AND TABLE_NAME = @TableName
        FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 2, '');

    SET @SQL = '
    CREATE OR ALTER TRIGGER [' + @SchemaName + '].[' + @TriggerName + ']
    ON [' + @SchemaName + '].[' + @TableName + ']
    AFTER INSERT, UPDATE, DELETE
    AS
    BEGIN
        SET NOCOUNT ON;

        DECLARE @Action NVARCHAR(50);
        DECLARE @UserId NVARCHAR(100);
        
        -- Get User from Session Context (set by application)
        SET @UserId = CAST(SESSION_CONTEXT(N''UserId'') AS NVARCHAR(100));
        IF @UserId IS NULL SET @UserId = ''System''; -- Default if not set

        IF EXISTS (SELECT * FROM inserted)
        BEGIN
            IF EXISTS (SELECT * FROM deleted)
                SET @Action = ''UPDATE'';
            ELSE
                SET @Action = ''INSERT'';
        END
        ELSE
        BEGIN
            SET @Action = ''DELETE'';
        END

        -- Insert into Audit Log
        INSERT INTO [AUDITLOG].[AuditLogs] (TableName, RecordId, Action, OldValue, NewValue, ChangedBy, ChangedAt)
        SELECT 
            ''' + @TableName + ''',
            COALESCE(i.' + @PrimaryKeyColumn + ', d.' + @PrimaryKeyColumn + '),
            @Action,
            (SELECT ' + @ColumnList + ' FROM deleted d WHERE d.' + @PrimaryKeyColumn + ' = COALESCE(i.' + @PrimaryKeyColumn + ', d.' + @PrimaryKeyColumn + ') FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
            (SELECT ' + @ColumnList + ' FROM inserted i WHERE i.' + @PrimaryKeyColumn + ' = COALESCE(i.' + @PrimaryKeyColumn + ', d.' + @PrimaryKeyColumn + ') FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
            @UserId,
            GETDATE()
        FROM inserted i
        FULL OUTER JOIN deleted d ON i.' + @PrimaryKeyColumn + ' = d.' + @PrimaryKeyColumn + ';
    END';

    EXEC sp_executesql @SQL;
    PRINT 'Created trigger for ' + @TableName;
END
GO

/* ═══ procedures ═══ */
-- Procedure: keep parsing CONTEXT_INFO, then apply server-side fallbacks (like old trigger).
CREATE   PROCEDURE AUDITLOG.usp_ParseAuditContext
    @ChangedBy NVARCHAR(100) OUTPUT,
    @IpAddress NVARCHAR(50) OUTPUT,
    @SessionId NVARCHAR(255) OUTPUT
AS
SET NOCOUNT ON;
SET @ChangedBy = NULL;
SET @IpAddress = NULL;
SET @SessionId = NULL;
DECLARE @ctx NVARCHAR(128) = RTRIM(LTRIM(REPLACE(CAST(CONTEXT_INFO() AS NVARCHAR(128)), NCHAR(0), N' ')));
IF @ctx IS NOT NULL AND @ctx <> N''
BEGIN
    DECLARE @p1 INT = CHARINDEX(N'|', @ctx);
    DECLARE @p2 INT = CASE WHEN @p1 > 0 THEN CHARINDEX(N'|', @ctx, @p1 + 1) ELSE 0 END;
    IF @p1 > 0 AND @p2 > @p1
    BEGIN
        SET @ChangedBy = NULLIF(RTRIM(LTRIM(SUBSTRING(@ctx, 1, @p1 - 1))), N'');
        SET @IpAddress = NULLIF(RTRIM(LTRIM(SUBSTRING(@ctx, @p1 + 1, @p2 - @p1 - 1))), N'');
        SET @SessionId = NULLIF(RTRIM(LTRIM(SUBSTRING(@ctx, @p2 + 1, 128))), N'');
    END
    ELSE IF @p1 > 0
    BEGIN
        SET @ChangedBy = NULLIF(RTRIM(LTRIM(SUBSTRING(@ctx, 1, @p1 - 1))), N'');
        SET @IpAddress = NULLIF(RTRIM(LTRIM(SUBSTRING(@ctx, @p1 + 1, 128))), N'');
    END
    ELSE
        SET @ChangedBy = NULLIF(RTRIM(LTRIM(@ctx)), N'');
END
-- Fallbacks (like old trigger: SUSER_SNAME(), fn_GetClientIP(), @@SPID)
SET @ChangedBy = COALESCE(NULLIF(RTRIM(LTRIM(@ChangedBy)), N''), SUSER_SNAME());
SET @IpAddress = COALESCE(NULLIF(RTRIM(LTRIM(@IpAddress)), N''), AUDITLOG.fn_GetClientIP());
SET @SessionId = COALESCE(NULLIF(RTRIM(LTRIM(@SessionId)), N''), CAST(@@SPID AS NVARCHAR(255)));
GO

CREATE   PROCEDURE AUDITLOG.usp_WriteAuditTrail
    @SchemaName NVARCHAR(100),
    @TableName NVARCHAR(255),
    @RecordId NVARCHAR(255),
    @Operation NVARCHAR(50),
    @OldValues NVARCHAR(MAX) = NULL,
    @NewValues NVARCHAR(MAX) = NULL,
    @ChangedColumns NVARCHAR(MAX) = NULL
AS
SET NOCOUNT ON;
DECLARE @ChangedBy NVARCHAR(100) = NULL;
IF DATALENGTH(CONTEXT_INFO()) > 0
    SET @ChangedBy = NULLIF(RTRIM(LTRIM(REPLACE(CAST(CONTEXT_INFO() AS NVARCHAR(128)), NCHAR(0), N' '))), N'');
INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES, CHANGED_COLUMNS, CHANGED_BY, CHANGED_AT, APPLICATION_NAME)
VALUES (@SchemaName, @TableName, @RecordId, @Operation, @OldValues, @NewValues, @ChangedColumns, NULLIF(@ChangedBy, N''), GETUTCDATE(), N'MOHE_SYSTEM');
GO

CREATE PROCEDURE SP_CREATE_AUDIT_TRIGGERS_FOR_TABLE
    @SchemaName NVARCHAR(100),
    @TableName NVARCHAR(255)
AS
BEGIN
    SET NOCOUNT ON;
    
    DECLARE @TriggerNameUpdate NVARCHAR(255) = 'tr_TRG_AUDIT_' + @SchemaName + '_' + @TableName + '_UPDATE';
    DECLARE @TriggerNameDelete NVARCHAR(255) = 'tr_TRG_AUDIT_' + @SchemaName + '_' + @TableName + '_DELETE';
    DECLARE @FullTableName NVARCHAR(255) = '[' + @SchemaName + '].[' + @TableName + ']';
    DECLARE @SQL NVARCHAR(MAX);
    DECLARE @PrimaryKeyCol NVARCHAR(255);
    DECLARE @ErrorMsg NVARCHAR(MAX);
    
    -- Get first primary key column or first column using sys tables (avoids sql_variant issues)
    DECLARE @SchemaId INT = SCHEMA_ID(@SchemaName);
    DECLARE @TableId INT = OBJECT_ID(@FullTableName);
    DECLARE @TempColName NVARCHAR(255);
    
    -- Try to get primary key column first
    SELECT TOP 1 @TempColName = CAST(c.name AS NVARCHAR(255))
    FROM sys.indexes i
    INNER JOIN sys.index_columns ic ON i.object_id = ic.object_id AND i.index_id = ic.index_id
    INNER JOIN sys.columns c ON ic.object_id = c.object_id AND ic.column_id = c.column_id
    WHERE i.object_id = @TableId
        AND i.is_primary_key = 1
        AND i.type_desc <> 'HEAP'
    ORDER BY ic.key_ordinal;
    
    SET @PrimaryKeyCol = @TempColName;
    
    -- If no primary key, get first column
    IF @PrimaryKeyCol IS NULL
    BEGIN
        SELECT TOP 1 @TempColName = CAST(c.name AS NVARCHAR(255))
        FROM sys.columns c
        INNER JOIN sys.tables t ON c.object_id = t.object_id
        INNER JOIN sys.schemas s ON t.schema_id = s.schema_id
        WHERE t.object_id = @TableId
            AND s.schema_id = @SchemaId
        ORDER BY c.column_id;
        
        SET @PrimaryKeyCol = @TempColName;
    END
    
    IF @PrimaryKeyCol IS NULL
    BEGIN
        PRINT '   ? Skipping ' + @FullTableName + ' - no columns found';
        RETURN;
    END
    
    -- Drop existing triggers
    IF EXISTS (SELECT * FROM sys.triggers WHERE name = @TriggerNameUpdate)
    BEGIN
        SET @SQL = 'DROP TRIGGER [' + @SchemaName + '].[' + @TriggerNameUpdate + '];';
        EXEC sp_executesql @SQL;
    END
    
    IF EXISTS (SELECT * FROM sys.triggers WHERE name = @TriggerNameDelete)
    BEGIN
        SET @SQL = 'DROP TRIGGER [' + @SchemaName + '].[' + @TriggerNameDelete + '];';
        EXEC sp_executesql @SQL;
    END
    
    -- Create UPDATE trigger
    SET @SQL = N'
    CREATE TRIGGER [' + @SchemaName + '].[' + @TriggerNameUpdate + ']
    ON ' + @FullTableName + '
    AFTER UPDATE
    AS
    BEGIN
        SET NOCOUNT ON;
        DECLARE @UserId NVARCHAR(100) = COALESCE(SESSION_CONTEXT(N''UserId''), SYSTEM_USER);
        DECLARE @IPAddress NVARCHAR(50) = COALESCE(CONNECTIONPROPERTY(''client_net_address''), '''');
        DECLARE @SessionId NVARCHAR(255) = CAST(@@SPID AS NVARCHAR(255));
        DECLARE @RecordId NVARCHAR(255);
        DECLARE @OldValues NVARCHAR(MAX);
        DECLARE @NewValues NVARCHAR(MAX);
        DECLARE update_cursor CURSOR FOR
        SELECT 
            CAST(i.' + QUOTENAME(@PrimaryKeyCol) + ' AS NVARCHAR(255)) AS RecordId,
            (SELECT d.* FROM deleted d WHERE d.' + QUOTENAME(@PrimaryKeyCol) + ' = i.' + QUOTENAME(@PrimaryKeyCol) + ' FOR JSON PATH, WITHOUT_ARRAY_WRAPPER) AS OldValues,
            (SELECT i.* FOR JSON PATH, WITHOUT_ARRAY_WRAPPER) AS NewValues
        FROM inserted i;
        OPEN update_cursor;
        FETCH NEXT FROM update_cursor INTO @RecordId, @OldValues, @NewValues;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                EXEC [MOHE_LOG].[MOHELOGCORE].[SP_INSERT_AUDIT_LOG]
                    @TableName = N''' + REPLACE(@TableName, '''', '''''') + ''',
                    @SchemaName = N''' + REPLACE(@SchemaName, '''', '''''') + ''',
                    @RecordId = @RecordId,
                    @Operation = N''UPDATE'',
                    @OldValues = @OldValues,
                    @NewValues = @NewValues,
                    @ChangedBy = @UserId,
                    @IPAddress = @IPAddress,
                    @SessionId = @SessionId;
            END TRY
            BEGIN CATCH
                PRINT N''Error in audit trigger: '' + ERROR_MESSAGE();
            END CATCH
            FETCH NEXT FROM update_cursor INTO @RecordId, @OldValues, @NewValues;
        END
        CLOSE update_cursor;
        DEALLOCATE update_cursor;
    END;';
    
    BEGIN TRY
        EXEC sp_executesql @SQL;
        PRINT '   � UPDATE trigger created for ' + @FullTableName;
    END TRY
    BEGIN CATCH
        SET @ErrorMsg = ERROR_MESSAGE();
        PRINT '   ? Error creating UPDATE trigger for ' + @FullTableName + ': ' + @ErrorMsg;
        RETURN;
    END CATCH
    
    -- Create DELETE trigger
    SET @SQL = N'
    CREATE TRIGGER [' + @SchemaName + '].[' + @TriggerNameDelete + ']
    ON ' + @FullTableName + '
    AFTER DELETE
    AS
    BEGIN
        SET NOCOUNT ON;
        DECLARE @UserId NVARCHAR(100) = COALESCE(SESSION_CONTEXT(N''UserId''), SYSTEM_USER);
        DECLARE @IPAddress NVARCHAR(50) = COALESCE(CONNECTIONPROPERTY(''client_net_address''), '''');
        DECLARE @SessionId NVARCHAR(255) = CAST(@@SPID AS NVARCHAR(255));
        DECLARE @RecordId NVARCHAR(255);
        DECLARE @OldValues NVARCHAR(MAX);
        DECLARE delete_cursor CURSOR FOR
        SELECT 
            CAST(d.' + QUOTENAME(@PrimaryKeyCol) + ' AS NVARCHAR(255)) AS RecordId,
            (SELECT d.* FOR JSON PATH, WITHOUT_ARRAY_WRAPPER) AS OldValues
        FROM deleted d;
        OPEN delete_cursor;
        FETCH NEXT FROM delete_cursor INTO @RecordId, @OldValues;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                EXEC [MOHE_LOG].[MOHELOGCORE].[SP_INSERT_AUDIT_LOG]
                    @TableName = N''' + REPLACE(@TableName, '''', '''''') + ''',
                    @SchemaName = N''' + REPLACE(@SchemaName, '''', '''''') + ''',
                    @RecordId = @RecordId,
                    @Operation = N''DELETE'',
                    @OldValues = @OldValues,
                    @NewValues = NULL,
                    @ChangedBy = @UserId,
                    @IPAddress = @IPAddress,
                    @SessionId = @SessionId;
            END TRY
            BEGIN CATCH
                PRINT N''Error in audit trigger: '' + ERROR_MESSAGE();
            END CATCH
            FETCH NEXT FROM delete_cursor INTO @RecordId, @OldValues;
        END
        CLOSE delete_cursor;
        DEALLOCATE delete_cursor;
    END;';
    
    BEGIN TRY
        EXEC sp_executesql @SQL;
        PRINT '   � DELETE trigger created for ' + @FullTableName;
    END TRY
    BEGIN CATCH
        SET @ErrorMsg = ERROR_MESSAGE();
        PRINT '   ? Error creating DELETE trigger for ' + @FullTableName + ': ' + @ErrorMsg;
    END CATCH
END
GO

/* ═══ triggers ═══ */
CREATE   TRIGGER ALERTCORE.TR_ApprovalRequests_Audit_Delete
ON ALERTCORE.ApprovalRequests AFTER DELETE AS
SET NOCOUNT ON;
DECLARE @cb NVARCHAR(100), @ip NVARCHAR(50), @sid NVARCHAR(255);
EXEC AUDITLOG.usp_ParseAuditContext @ChangedBy=@cb OUTPUT, @IpAddress=@ip OUTPUT, @SessionId=@sid OUTPUT;
INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES, CHANGED_BY, IP_ADDRESS, SESSION_ID, CHANGED_AT, APPLICATION_NAME, COUNTRY_ID)
SELECT N'ALERTCORE', N'ApprovalRequests', CAST(d.Id AS NVARCHAR(255)), N'DELETE',
       (SELECT d2.* FROM deleted d2 WHERE d2.Id = d.Id FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
       NULL, @cb, @ip, @sid, GETUTCDATE(), N'MOHE_SYSTEM', d.CountryId FROM deleted d;
GO

CREATE   TRIGGER ALERTCORE.TR_ApprovalRequests_Audit_Insert
ON ALERTCORE.ApprovalRequests AFTER INSERT AS
SET NOCOUNT ON;
DECLARE @cb NVARCHAR(100), @ip NVARCHAR(50), @sid NVARCHAR(255);
EXEC AUDITLOG.usp_ParseAuditContext @ChangedBy=@cb OUTPUT, @IpAddress=@ip OUTPUT, @SessionId=@sid OUTPUT;
INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES, CHANGED_BY, IP_ADDRESS, SESSION_ID, CHANGED_AT, APPLICATION_NAME, COUNTRY_ID)
SELECT N'ALERTCORE', N'ApprovalRequests', CAST(i.Id AS NVARCHAR(255)), N'INSERT', NULL,
       (SELECT i2.* FROM inserted i2 WHERE i2.Id = i.Id FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
       @cb, @ip, @sid, GETUTCDATE(), N'MOHE_SYSTEM', i.CountryId FROM inserted i;
GO

CREATE TRIGGER ALERTCORE.TR_ApprovalRequests_Audit_Update ON ALERTCORE.ApprovalRequests AFTER UPDATE AS
SET NOCOUNT ON;
DECLARE @cb NVARCHAR(100), @ip NVARCHAR(50), @sid NVARCHAR(255);
EXEC AUDITLOG.usp_ParseAuditContext @ChangedBy=@cb OUTPUT, @IpAddress=@ip OUTPUT, @SessionId=@sid OUTPUT;
INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES, CHANGED_COLUMNS, CHANGED_BY, IP_ADDRESS, SESSION_ID, CHANGED_AT, APPLICATION_NAME)
SELECT N'ALERTCORE', N'ApprovalRequests', CAST(d.Id AS NVARCHAR(255)), N'UPDATE',
  (SELECT d2.* FROM deleted d2 WHERE d2.Id = d.Id FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
  (SELECT i2.* FROM inserted i2 WHERE i2.Id = d.Id FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
  NULLIF(STUFF(
    (CASE WHEN ISNULL(d.ConfigId, -1) <> ISNULL(i.ConfigId, -1) THEN N', ConfigId' ELSE N'' END) +
    (CASE WHEN ISNULL(d.RequestType, N'') <> ISNULL(i.RequestType, N'') THEN N', RequestType' ELSE N'' END) +
    (CASE WHEN ISNULL(d.EntityType, N'') <> ISNULL(i.EntityType, N'') THEN N', EntityType' ELSE N'' END) +
    (CASE WHEN ISNULL(d.EntityId, N'') <> ISNULL(i.EntityId, N'') THEN N', EntityId' ELSE N'' END) +
    (CASE WHEN ISNULL(d.CountryId, -1) <> ISNULL(i.CountryId, -1) THEN N', CountryId' ELSE N'' END) +
    (CASE WHEN ISNULL(d.RequestData, N'') <> ISNULL(i.RequestData, N'') THEN N', RequestData' ELSE N'' END) +
    (CASE WHEN ISNULL(d.OriginalData, N'') <> ISNULL(i.OriginalData, N'') THEN N', OriginalData' ELSE N'' END) +
    (CASE WHEN ISNULL(d.CurrentLevel, -1) <> ISNULL(i.CurrentLevel, -1) THEN N', CurrentLevel' ELSE N'' END) +
    (CASE WHEN ISNULL(d.Status, N'') <> ISNULL(i.Status, N'') THEN N', Status' ELSE N'' END) +
    (CASE WHEN ISNULL(d.RequestedBy, -1) <> ISNULL(i.RequestedBy, -1) THEN N', RequestedBy' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.RequestedAt AS NVARCHAR(50)), N'') <> ISNULL(CAST(i.RequestedAt AS NVARCHAR(50)), N'') THEN N', RequestedAt' ELSE N'' END) +
    (CASE WHEN ISNULL(d.RejectionReason, N'') <> ISNULL(i.RejectionReason, N'') THEN N', RejectionReason' ELSE N'' END) +
    (CASE WHEN ISNULL(d.RejectedBy, -1) <> ISNULL(i.RejectedBy, -1) THEN N', RejectedBy' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.RejectedAt AS NVARCHAR(50)), N'') <> ISNULL(CAST(i.RejectedAt AS NVARCHAR(50)), N'') THEN N', RejectedAt' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.ExecutedAt AS NVARCHAR(50)), N'') <> ISNULL(CAST(i.ExecutedAt AS NVARCHAR(50)), N'') THEN N', ExecutedAt' ELSE N'' END) +
    (CASE WHEN ISNULL(d.ExecutedBy, -1) <> ISNULL(i.ExecutedBy, -1) THEN N', ExecutedBy' ELSE N'' END),
  1, 2, N''), N''),
  @cb, @ip, @sid, GETUTCDATE(), N'MOHE_SYSTEM'
FROM deleted d INNER JOIN inserted i ON i.Id = d.Id;
GO

CREATE   TRIGGER AUDITLOG.TR_AuditTrail_ResolveCountry
ON AUDITLOG.AuditTrail
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM inserted WHERE COUNTRY_ID IS NULL AND OPERATION <> N'DELETE')
        RETURN;

    UPDATE at
       SET at.COUNTRY_ID = COALESCE(sd.STUDY_COUNTRY_IN, sf.STUDY_COUNTRY_IN_ID, ar.CountryId,
                                    pb.STUDY_COUNTRY_IN_ID, pbl.STUDY_COUNTRY_IN_ID, pblb.STUDY_COUNTRY_IN_ID,
                                    aa.STUDY_COUNTRY_IN_ID, ba.STUDY_COUNTRY_IN_ID, ab.STUDY_COUNTRY_IN_ID, we.STUDY_COUNTRY_IN_ID)
      FROM AUDITLOG.AuditTrail at
      JOIN inserted i ON i.LOG_ID = at.LOG_ID
      LEFT JOIN MOHECORE.STUDENT_DATA sd
             ON at.[SCHEMA_NAME] = N'MOHECORE' AND at.TABLE_NAME = N'STUDENT_DATA'
            AND sd.STUDENT_ID = TRY_CAST(at.RECORD_ID AS int)
      LEFT JOIN MOHECORE.STUDENT_FINANCE sf
             ON at.[SCHEMA_NAME] = N'MOHECORE' AND at.TABLE_NAME = N'STUDENT_FINANCE'
            AND sf.STUDENT_ID = TRY_CAST(at.RECORD_ID AS int)
      LEFT JOIN ALERTCORE.ApprovalRequests ar
             ON at.[SCHEMA_NAME] = N'ALERTCORE' AND at.TABLE_NAME = N'ApprovalRequests'
            AND ar.Id = TRY_CAST(at.RECORD_ID AS bigint)
      -- V067: the FINCORE money tables, all on STUDY_COUNTRY_IN_ID
      LEFT JOIN FINCORE.PAYMENT_BATCH pb
             ON at.[SCHEMA_NAME] = N'FINCORE' AND at.TABLE_NAME = N'PAYMENT_BATCH'
            AND pb.BATCH_ID = TRY_CAST(at.RECORD_ID AS int)
      LEFT JOIN FINCORE.PAYMENT_BATCH_LINE pbl
             ON at.[SCHEMA_NAME] = N'FINCORE' AND at.TABLE_NAME = N'PAYMENT_BATCH_LINE'
            AND pbl.BATCH_LINE_ID = TRY_CAST(at.RECORD_ID AS int)
      LEFT JOIN FINCORE.PAYMENT_BATCH pblb ON pblb.BATCH_ID = pbl.BATCH_ID
      LEFT JOIN FINCORE.ATTACHE_ALLOCATION aa
             ON at.[SCHEMA_NAME] = N'FINCORE' AND at.TABLE_NAME = N'ATTACHE_ALLOCATION'
            AND aa.ALLOCATION_ID = TRY_CAST(at.RECORD_ID AS int)
      LEFT JOIN FINCORE.BUDGET_APPROPRIATION ba
             ON at.[SCHEMA_NAME] = N'FINCORE' AND at.TABLE_NAME = N'BUDGET_APPROPRIATION'
            AND ba.APPROPRIATION_ID = TRY_CAST(at.RECORD_ID AS int)
      LEFT JOIN FINCORE.ATTACHE_ADVANCE_BALANCE ab
             ON at.[SCHEMA_NAME] = N'FINCORE' AND at.TABLE_NAME = N'ATTACHE_ADVANCE_BALANCE'
            AND ab.BALANCE_ID = TRY_CAST(at.RECORD_ID AS int)
      LEFT JOIN FINCORE.WAFAR_EARMARK we
             ON at.[SCHEMA_NAME] = N'FINCORE' AND at.TABLE_NAME = N'WAFAR_EARMARK'
            AND we.EARMARK_ID = TRY_CAST(at.RECORD_ID AS int)
     WHERE at.COUNTRY_ID IS NULL
       AND at.OPERATION <> N'DELETE';
END
GO

CREATE   TRIGGER FINCORE.[TR_ATTACHE_ADVANCE_BALANCE_Audit]
ON FINCORE.[ATTACHE_ADVANCE_BALANCE] AFTER INSERT, UPDATE, DELETE AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM inserted) AND NOT EXISTS (SELECT 1 FROM deleted) RETURN;
    DECLARE @cb NVARCHAR(100), @ip NVARCHAR(50), @sid NVARCHAR(255);
    EXEC AUDITLOG.usp_ParseAuditContext @ChangedBy = @cb OUTPUT, @IpAddress = @ip OUTPUT, @SessionId = @sid OUTPUT;
    DECLARE @op NVARCHAR(50) = CASE WHEN EXISTS (SELECT 1 FROM inserted) AND EXISTS (SELECT 1 FROM deleted) THEN N'UPDATE'
