    INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES,
                                     CHANGED_BY, IP_ADDRESS, SESSION_ID, CHANGED_AT, APPLICATION_NAME, COUNTRY_ID)
    SELECT N'FINCORE', N'ATTACHE_ADVANCE_BALANCE', CAST(COALESCE(i.[BALANCE_ID], d.[BALANCE_ID]) AS NVARCHAR(255)), @op,
           (SELECT d2.* FROM deleted  d2 WHERE d2.[BALANCE_ID] = d.[BALANCE_ID] FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
           (SELECT i2.* FROM inserted i2 WHERE i2.[BALANCE_ID] = i.[BALANCE_ID] FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
           @cb, @ip, @sid, GETUTCDATE(), N'MOHE_SYSTEM', COALESCE(i.STUDY_COUNTRY_IN_ID, d.STUDY_COUNTRY_IN_ID)
