CREATE TRIGGER FINCORE.TR_WAFAR_USE_SAME_ATTACHE
ON FINCORE.WAFAR_USE
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    /* The beneficiary must study in the country whose Wafar is being spent. */
    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDENT_ID = i.BENEFICIARY_STUDENT_ID
        WHERE sd.STUDY_COUNTRY_IN IS NOT NULL
          AND sd.STUDY_COUNTRY_IN <> i.STUDY_COUNTRY_IN_ID
    )
        THROW 50060, 'Wafar may only be spent at the attache that holds it: the beneficiary studies in a different country.', 1;

    /* There must be a pool, and it must hold enough. */
    IF EXISTS (
        SELECT 1
        FROM inserted i
        LEFT JOIN FINCORE.ATTACHE_ADVANCE_BALANCE b
               ON b.FISCAL_YEAR_ID      = i.FISCAL_YEAR_ID
              AND b.STUDY_COUNTRY_IN_ID = i.STUDY_COUNTRY_IN_ID
              AND b.CURRENCY_ID         = i.CURRENCY_ID
        WHERE b.BALANCE_ID IS NULL
    )
        THROW 50061, 'No Wafar pool exists for that attache, fiscal year and currency.', 1;

    IF EXISTS (
        SELECT i.FISCAL_YEAR_ID, i.STUDY_COUNTRY_IN_ID, i.CURRENCY_ID
        FROM inserted i
        JOIN FINCORE.ATTACHE_ADVANCE_BALANCE b
               ON b.FISCAL_YEAR_ID      = i.FISCAL_YEAR_ID
              AND b.STUDY_COUNTRY_IN_ID = i.STUDY_COUNTRY_IN_ID
              AND b.CURRENCY_ID         = i.CURRENCY_ID
        GROUP BY i.FISCAL_YEAR_ID, i.STUDY_COUNTRY_IN_ID, i.CURRENCY_ID, b.WAFAR_BALANCE
        HAVING SUM(i.AMOUNT) > b.WAFAR_BALANCE
    )
        THROW 50062, 'Wafar use exceeds the savings held at that attache.', 1;
END
GO

/*
    The child-side stamp. The trailing WHERE is load-bearing, as V029 explains:
    without it the trigger's own UPDATE fires the trigger again.
*/
CREATE   TRIGGER MOHECORE.TR_FIN_RECEIVED_WHOM_DOCUMENTS_TENANT
ON MOHECORE.FIN_RECEIVED_WHOM_DOCUMENTS AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM inserted) RETURN;

    UPDATE d
       SET d.STUDY_COUNTRY_IN_ID = NULLIF(w.FINANCE_COUNTRY_ID, 0)
      FROM MOHECORE.FIN_RECEIVED_WHOM_DOCUMENTS d
      JOIN inserted i ON i.DOCUMENT_ID = d.DOCUMENT_ID
      JOIN MOHECORE.STUDY_FIN_RECEIVED_WHOM w ON w.STUDY_RECEIVED_WHOM_ID = d.WHOM_ID
     WHERE ISNULL(d.STUDY_COUNTRY_IN_ID, -1) <> ISNULL(NULLIF(w.FINANCE_COUNTRY_ID, 0), -1);
END;
GO

CREATE   TRIGGER MOHECORE.[TR_PAYMENT_AUTH_TENANT]
ON MOHECORE.[PAYMENT_AUTH] AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM inserted) RETURN;
    UPDATE t SET t.STUDY_COUNTRY_IN_ID = sd.STUDY_COUNTRY_IN
    FROM MOHECORE.[PAYMENT_AUTH] t
    JOIN inserted i ON i.[STUDENT_ID] = t.[STUDENT_ID]
    JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDENT_ID = t.[STUDENT_ID]
    WHERE ISNULL(t.STUDY_COUNTRY_IN_ID, -1) <> ISNULL(sd.STUDY_COUNTRY_IN, -1);
END;
GO

