ON MOHECORE.STUDENT_DATA AFTER INSERT AS
SET NOCOUNT ON;
DECLARE @cb NVARCHAR(100), @ip NVARCHAR(50), @sid NVARCHAR(255);
EXEC AUDITLOG.usp_ParseAuditContext @ChangedBy=@cb OUTPUT, @IpAddress=@ip OUTPUT, @SessionId=@sid OUTPUT;
INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES, CHANGED_BY, IP_ADDRESS, SESSION_ID, CHANGED_AT, APPLICATION_NAME, COUNTRY_ID)
SELECT N'MOHECORE', N'STUDENT_DATA', CAST(i.STUDENT_ID AS NVARCHAR(255)), N'INSERT', NULL, NULL, @cb, @ip, @sid, GETUTCDATE(), N'MOHE_SYSTEM', i.STUDY_COUNTRY_IN FROM inserted i;
GO

CREATE TRIGGER MOHECORE.TR_STUDENT_DATA_Audit_Update ON MOHECORE.STUDENT_DATA AFTER UPDATE AS
SET NOCOUNT ON;
DECLARE @cb NVARCHAR(100), @ip NVARCHAR(50), @sid NVARCHAR(255);
EXEC AUDITLOG.usp_ParseAuditContext @ChangedBy=@cb OUTPUT, @IpAddress=@ip OUTPUT, @SessionId=@sid OUTPUT;
INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES, CHANGED_COLUMNS, CHANGED_BY, IP_ADDRESS, SESSION_ID, CHANGED_AT, APPLICATION_NAME)
SELECT N'MOHECORE', N'STUDENT_DATA', CAST(d.STUDENT_ID AS NVARCHAR(255)), N'UPDATE', NULL, NULL,
  NULLIF(STUFF(
    (CASE WHEN ISNULL(CAST(d.STUDENT_NAME AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_NAME AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDENT_NAME' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDENT_DELEGATION_DECISION_YEAR AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_DELEGATION_DECISION_YEAR AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDENT_DELEGATION_DECISION_YEAR' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDENT_MAJOR_NAME AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_MAJOR_NAME AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDENT_MAJOR_NAME' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_GOV_ID, -1) <> ISNULL(i.STUDENT_GOV_ID, -1) THEN N', STUDENT_GOV_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_MUD_ID, -1) <> ISNULL(i.STUDENT_MUD_ID, -1) THEN N', STUDENT_MUD_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_DEGREE_ID, -1) <> ISNULL(i.STUDENT_DEGREE_ID, -1) THEN N', STUDENT_DEGREE_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_MAJOR_ID, -1) <> ISNULL(i.STUDENT_MAJOR_ID, -1) THEN N', STUDENT_MAJOR_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_DELEGATE_DECISION_NO, -1) <> ISNULL(i.STUDENT_DELEGATE_DECISION_NO, -1) THEN N', STUDENT_DELEGATE_DECISION_NO' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_STUDY_NO_OF_YEARS, -1) <> ISNULL(i.STUDENT_STUDY_NO_OF_YEARS, -1) THEN N', STUDENT_STUDY_NO_OF_YEARS' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_CURRENT_LEVEL_ID, -1) <> ISNULL(i.STUDENT_CURRENT_LEVEL_ID, -1) THEN N', STUDENT_CURRENT_LEVEL_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_AMOUNT, -1) <> ISNULL(i.STUDENT_AMOUNT, -1) THEN N', STUDENT_AMOUNT' ELSE N'' END) +
    (CASE WHEN ISNULL(d.AMOUNT_CURRENCY, -1) <> ISNULL(i.AMOUNT_CURRENCY, -1) THEN N', AMOUNT_CURRENCY' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_STUDY_STATUS_ID, -1) <> ISNULL(i.STUDENT_STUDY_STATUS_ID, -1) THEN N', STUDENT_STUDY_STATUS_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_AGENCY_TYPE_ID, -1) <> ISNULL(i.STUDENT_AGENCY_TYPE_ID, -1) THEN N', STUDENT_AGENCY_TYPE_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_MINISTRY_TYPE_ID, -1) <> ISNULL(i.STUDENT_MINISTRY_TYPE_ID, -1) THEN N', STUDENT_MINISTRY_TYPE_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_UNIVERSITY_TYPE_ID, -1) <> ISNULL(i.STUDENT_UNIVERSITY_TYPE_ID, -1) THEN N', STUDENT_UNIVERSITY_TYPE_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_ADDED_QUARTER, -1) <> ISNULL(i.STUDENT_ADDED_QUARTER, -1) THEN N', STUDENT_ADDED_QUARTER' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_LAST_QUARTER, -1) <> ISNULL(i.STUDENT_LAST_QUARTER, -1) THEN N', STUDENT_LAST_QUARTER' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDENT_BIRTHDATE AS NVARCHAR(50)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_BIRTHDATE AS NVARCHAR(50)), N'__NULL__') THEN N', STUDENT_BIRTHDATE' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDENT_PASSPORT_NUMBER AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_PASSPORT_NUMBER AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDENT_PASSPORT_NUMBER' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.PICTURE_PATH AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.PICTURE_PATH AS NVARCHAR(MAX)), N'__NULL__') THEN N', PICTURE_PATH' ELSE N'' END),
  1, 2, N''), N''),
  @cb, @ip, @sid, GETUTCDATE(), N'MOHE_SYSTEM'
FROM deleted d INNER JOIN inserted i ON i.STUDENT_ID = d.STUDENT_ID;
GO

