CREATE   TRIGGER MOHECORE.[TR_STUDENT_DEATH_CASE_TENANT]
ON MOHECORE.[STUDENT_DEATH_CASE] AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM inserted) RETURN;
    UPDATE t SET t.STUDY_COUNTRY_IN_ID = sd.STUDY_COUNTRY_IN
    FROM MOHECORE.[STUDENT_DEATH_CASE] t
    JOIN inserted i ON i.[STUDENT_ID] = t.[STUDENT_ID]
    JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDENT_ID = t.[STUDENT_ID]
    WHERE ISNULL(t.STUDY_COUNTRY_IN_ID, -1) <> ISNULL(sd.STUDY_COUNTRY_IN, -1);
END;
GO

CREATE TRIGGER [MOHECORE].[TR_Audit_STUDENT_DOCUMENT_HISTORY]
ON [MOHECORE].[STUDENT_DOCUMENT_HISTORY]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Action NVARCHAR(50);
    DECLARE @UserId NVARCHAR(100);

    SET @UserId = CAST(SESSION_CONTEXT(N'UserId') AS NVARCHAR(100));
    IF @UserId IS NULL SET @UserId = N'System';

    IF EXISTS (SELECT 1 FROM inserted)
    BEGIN
        IF EXISTS (SELECT 1 FROM deleted)
            SET @Action = N'UPDATE';
        ELSE
            SET @Action = N'INSERT';
    END
    ELSE
        SET @Action = N'DELETE';

    INSERT INTO [AUDITLOG].[AuditLogs] (TableName, RecordId, Action, OldValue, NewValue, ChangedBy, ChangedAt)
    SELECT
        N'STUDENT_DOCUMENT_HISTORY',
        COALESCE(i.HISTORY_ID, d.HISTORY_ID),
        @Action,
        (SELECT h.[HISTORY_ID], h.[DOCUMENT_ID], h.[STUDENT_ID], h.[DOCUMENT_NAME], h.[DOCUMENT_TYPE],
                h.[FILE_PATH], h.[ORIGINAL_FILENAME], h.[FILE_SIZE], h.[FILE_HASH], h.[VERSION_NO],
                h.[ACTION], h.[CHANGED_BY], h.[CHANGED_AT]
         FROM deleted h
         WHERE h.HISTORY_ID = COALESCE(i.HISTORY_ID, d.HISTORY_ID)
         FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
        (SELECT h.[HISTORY_ID], h.[DOCUMENT_ID], h.[STUDENT_ID], h.[DOCUMENT_NAME], h.[DOCUMENT_TYPE],
                h.[FILE_PATH], h.[ORIGINAL_FILENAME], h.[FILE_SIZE], h.[FILE_HASH], h.[VERSION_NO],
                h.[ACTION], h.[CHANGED_BY], h.[CHANGED_AT]
         FROM inserted h
         WHERE h.HISTORY_ID = COALESCE(i.HISTORY_ID, d.HISTORY_ID)
         FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
        @UserId,
        GETDATE()
    FROM inserted i
    FULL OUTER JOIN deleted d ON i.HISTORY_ID = d.HISTORY_ID;
END
GO

CREATE   TRIGGER MOHECORE.[TR_STUDENT_DOCUMENT_HISTORY_TENANT]
ON MOHECORE.[STUDENT_DOCUMENT_HISTORY] AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM inserted) RETURN;
    UPDATE t SET t.STUDY_COUNTRY_IN_ID = sd.STUDY_COUNTRY_IN
    FROM MOHECORE.[STUDENT_DOCUMENT_HISTORY] t
    JOIN inserted i ON i.[STUDENT_ID] = t.[STUDENT_ID]
    JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDENT_ID = t.[STUDENT_ID]
    WHERE ISNULL(t.STUDY_COUNTRY_IN_ID, -1) <> ISNULL(sd.STUDY_COUNTRY_IN, -1);
END;
GO

    CREATE   TRIGGER [MOHECORE].[TR_Audit_STUDENT_DOCUMENTS]
    ON [MOHECORE].[STUDENT_DOCUMENTS]
    AFTER INSERT, UPDATE, DELETE
    AS
    BEGIN
        SET NOCOUNT ON;

        DECLARE @Action NVARCHAR(50);
        DECLARE @UserId NVARCHAR(100);
        
        -- Get User from Session Context (set by application)
        SET @UserId = CAST(SESSION_CONTEXT(N'UserId') AS NVARCHAR(100));
        IF @UserId IS NULL SET @UserId = 'System'; -- Default if not set

        IF EXISTS (SELECT * FROM inserted)
        BEGIN
            IF EXISTS (SELECT * FROM deleted)
                SET @Action = 'UPDATE';
            ELSE
                SET @Action = 'INSERT';
        END
        ELSE
        BEGIN
            SET @Action = 'DELETE';
        END

        -- Insert into Audit Log
        INSERT INTO [AUDITLOG].[AuditLogs] (TableName, RecordId, Action, OldValue, NewValue, ChangedBy, ChangedAt)
        SELECT 
            'STUDENT_DOCUMENTS',
            COALESCE(i.DOCUMENT_ID, d.DOCUMENT_ID),
            @Action,
            (SELECT [DOCUMENT_ID], [STUDENT_ID], [DOCUMENT_NAME], [DOCUMENT_TYPE], [FILE_PATH], [ORIGINAL_FILENAME], [FILE_SIZE], [UPLOAD_DATE], [IS_ACTIVE] FROM deleted d WHERE d.DOCUMENT_ID = COALESCE(i.DOCUMENT_ID, d.DOCUMENT_ID) FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
            (SELECT [DOCUMENT_ID], [STUDENT_ID], [DOCUMENT_NAME], [DOCUMENT_TYPE], [FILE_PATH], [ORIGINAL_FILENAME], [FILE_SIZE], [UPLOAD_DATE], [IS_ACTIVE] FROM inserted i WHERE i.DOCUMENT_ID = COALESCE(i.DOCUMENT_ID, d.DOCUMENT_ID) FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
            @UserId,
            GETDATE()
        FROM inserted i
        FULL OUTER JOIN deleted d ON i.DOCUMENT_ID = d.DOCUMENT_ID;
    END
GO

