CREATE   TRIGGER MOHECORE.TR_STUDENT_FINANCE_Audit_Delete
ON MOHECORE.STUDENT_FINANCE AFTER DELETE AS
SET NOCOUNT ON;
DECLARE @cb NVARCHAR(100), @ip NVARCHAR(50), @sid NVARCHAR(255);
EXEC AUDITLOG.usp_ParseAuditContext @ChangedBy=@cb OUTPUT, @IpAddress=@ip OUTPUT, @SessionId=@sid OUTPUT;
INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES, CHANGED_BY, IP_ADDRESS, SESSION_ID, CHANGED_AT, APPLICATION_NAME, COUNTRY_ID)
SELECT N'MOHECORE', N'STUDENT_FINANCE', CAST(d.STUDENT_ID AS NVARCHAR(255)), N'DELETE', NULL, NULL, @cb, @ip, @sid, GETUTCDATE(), N'MOHE_SYSTEM', d.STUDY_COUNTRY_IN_ID FROM deleted d;
GO

CREATE   TRIGGER MOHECORE.TR_STUDENT_FINANCE_Audit_Insert
ON MOHECORE.STUDENT_FINANCE AFTER INSERT AS
SET NOCOUNT ON;
DECLARE @cb NVARCHAR(100), @ip NVARCHAR(50), @sid NVARCHAR(255);
EXEC AUDITLOG.usp_ParseAuditContext @ChangedBy=@cb OUTPUT, @IpAddress=@ip OUTPUT, @SessionId=@sid OUTPUT;
INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES, CHANGED_BY, IP_ADDRESS, SESSION_ID, CHANGED_AT, APPLICATION_NAME, COUNTRY_ID)
SELECT N'MOHECORE', N'STUDENT_FINANCE', CAST(i.STUDENT_ID AS NVARCHAR(255)), N'INSERT', NULL, NULL, @cb, @ip, @sid, GETUTCDATE(), N'MOHE_SYSTEM', i.STUDY_COUNTRY_IN_ID FROM inserted i;
GO

CREATE TRIGGER MOHECORE.TR_STUDENT_FINANCE_Audit_Update ON MOHECORE.STUDENT_FINANCE AFTER UPDATE AS
SET NOCOUNT ON;
DECLARE @cb NVARCHAR(100), @ip NVARCHAR(50), @sid NVARCHAR(255);
EXEC AUDITLOG.usp_ParseAuditContext @ChangedBy=@cb OUTPUT, @IpAddress=@ip OUTPUT, @SessionId=@sid OUTPUT;
INSERT INTO AUDITLOG.AuditTrail (SCHEMA_NAME, TABLE_NAME, RECORD_ID, OPERATION, OLD_VALUES, NEW_VALUES, CHANGED_COLUMNS, CHANGED_BY, IP_ADDRESS, SESSION_ID, CHANGED_AT, APPLICATION_NAME)
SELECT N'MOHECORE', N'STUDENT_FINANCE', CAST(d.STUDENT_ID AS NVARCHAR(255)), N'UPDATE', NULL, NULL,
  NULLIF(STUFF(
    (CASE WHEN ISNULL(CAST(d.STUDENT_FIN_ID AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_FIN_ID AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDENT_FIN_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDENT_FIN_NAME AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_FIN_NAME AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDENT_FIN_NAME' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_FIN_RECIEVED_YEAR, -1) <> ISNULL(i.STUDENT_FIN_RECIEVED_YEAR, -1) THEN N', STUDENT_FIN_RECIEVED_YEAR' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_FIN_RECIEVED_MONTH, -1) <> ISNULL(i.STUDENT_FIN_RECIEVED_MONTH, -1) THEN N', STUDENT_FIN_RECIEVED_MONTH' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_FIN_RECIEVED_AMOUNT, -1) <> ISNULL(i.STUDENT_FIN_RECIEVED_AMOUNT, -1) THEN N', STUDENT_FIN_RECIEVED_AMOUNT' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDY_COUNTRY_IN_ID, -1) <> ISNULL(i.STUDY_COUNTRY_IN_ID, -1) THEN N', STUDY_COUNTRY_IN_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDY_FINANCE_BANKE_ID, -1) <> ISNULL(i.STUDY_FINANCE_BANKE_ID, -1) THEN N', STUDY_FINANCE_BANKE_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDY_FINANCE_BANK_BRANCH_ID, -1) <> ISNULL(i.STUDY_FINANCE_BANK_BRANCH_ID, -1) THEN N', STUDY_FINANCE_BANK_BRANCH_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDY_CHECK_ID AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDY_CHECK_ID AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDY_CHECK_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDY_CHECK_DATE AS NVARCHAR(50)), N'__NULL__') <> ISNULL(CAST(i.STUDY_CHECK_DATE AS NVARCHAR(50)), N'__NULL__') THEN N', STUDY_CHECK_DATE' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDY_CHECK_FORM_NUMBER AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDY_CHECK_FORM_NUMBER AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDY_CHECK_FORM_NUMBER' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDY_FIN_RECIEVED_STATUS, -1) <> ISNULL(i.STUDY_FIN_RECIEVED_STATUS, -1) THEN N', STUDY_FIN_RECIEVED_STATUS' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDY_RECEIVED_WHOM_STATUS_ID, -1) <> ISNULL(i.STUDY_RECEIVED_WHOM_STATUS_ID, -1) THEN N', STUDY_RECEIVED_WHOM_STATUS_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDY_RECEIVED_WHOM_ID, -1) <> ISNULL(i.STUDY_RECEIVED_WHOM_ID, -1) THEN N', STUDY_RECEIVED_WHOM_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDY_FINANCE_MIDATE AS NVARCHAR(50)), N'__NULL__') <> ISNULL(CAST(i.STUDY_FINANCE_MIDATE AS NVARCHAR(50)), N'__NULL__') THEN N', STUDY_FINANCE_MIDATE' ELSE N'' END) +
    (CASE WHEN ISNULL(d.STUDENT_BANK_ID, -1) <> ISNULL(i.STUDENT_BANK_ID, -1) THEN N', STUDENT_BANK_ID' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDENT_ACCOUNT_NUMBER AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_ACCOUNT_NUMBER AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDENT_ACCOUNT_NUMBER' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDENT_ACCOUNT_ENGLISH_NAME AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_ACCOUNT_ENGLISH_NAME AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDENT_ACCOUNT_ENGLISH_NAME' ELSE N'' END) +
    (CASE WHEN ISNULL(CAST(d.STUDENT_BANK_NOTES AS NVARCHAR(MAX)), N'__NULL__') <> ISNULL(CAST(i.STUDENT_BANK_NOTES AS NVARCHAR(MAX)), N'__NULL__') THEN N', STUDENT_BANK_NOTES' ELSE N'' END),
  1, 2, N''), N''),
  @cb, @ip, @sid, GETUTCDATE(), N'MOHE_SYSTEM'
FROM deleted d INNER JOIN inserted i ON i.STUDENT_ID = d.STUDENT_ID;
GO

CREATE   TRIGGER MOHECORE.[TR_STUDENT_FINANCE_TENANT]
ON MOHECORE.[STUDENT_FINANCE] AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM inserted) RETURN;
    UPDATE t SET t.STUDY_COUNTRY_IN_ID = sd.STUDY_COUNTRY_IN
    FROM MOHECORE.[STUDENT_FINANCE] t
    JOIN inserted i ON i.[STUDENT_ID] = t.[STUDENT_ID]
    JOIN MOHECORE.STUDENT_DATA sd ON sd.STUDENT_ID = t.[STUDENT_ID]
    WHERE ISNULL(t.STUDY_COUNTRY_IN_ID, -1) <> ISNULL(sd.STUDY_COUNTRY_IN, -1);
END;
