        CREATE TRIGGER [MOHECORE].[TRG_UPDATE_FAMILY_MEMBER_AGE]
        ON [MOHECORE].[STUDENT_TRAVEL_TICKET_FAMILY_MEMBER]
        AFTER INSERT, UPDATE
        AS
        BEGIN
            SET NOCOUNT ON;
            UPDATE [MOHECORE].[STUDENT_TRAVEL_TICKET_FAMILY_MEMBER]
            SET [AGE] = DATEDIFF(YEAR, [BIRTHDATE], GETDATE()) - 
                        CASE 
                            WHEN DATEADD(YEAR, DATEDIFF(YEAR, [BIRTHDATE], GETDATE()), [BIRTHDATE]) > GETDATE() 
                            THEN 1 
                            ELSE 0 
                        END
            WHERE [FAMILY_MEMBER_ID] IN (SELECT [FAMILY_MEMBER_ID] FROM inserted);
        END
        
GO

