    CREATE   TRIGGER [UMSCORE].[TR_Audit_GroupRoles]
    ON [UMSCORE].[GroupRoles]
    AFTER INSERT, UPDATE, DELETE
    AS
    BEGIN
        SET NOCOUNT ON;

        DECLARE @Action NVARCHAR(50);
        DECLARE @UserId NVARCHAR(100);
        
        -- Get User from Session Context (set by application)
        SET @UserId = CAST(SESSION_CONTEXT(N'UserId') AS NVARCHAR(100));
        IF @UserId IS NULL SET @UserId = 'System'; -- Default if not set

        IF EXISTS (SELECT * FROM inserted)
        BEGIN
            IF EXISTS (SELECT * FROM deleted)
                SET @Action = 'UPDATE';
            ELSE
                SET @Action = 'INSERT';
        END
        ELSE
        BEGIN
            SET @Action = 'DELETE';
        END

        -- Insert into Audit Log
        INSERT INTO [AUDITLOG].[AuditLogs] (TableName, RecordId, Action, OldValue, NewValue, ChangedBy, ChangedAt)
        SELECT 
            'GroupRoles',
            COALESCE(i.Id, d.Id),
            @Action,
            (SELECT [Id], [GroupId], [RoleId], [AssignedAt], [AssignedBy], [IsActive] FROM deleted d WHERE d.Id = COALESCE(i.Id, d.Id) FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
            (SELECT [Id], [GroupId], [RoleId], [AssignedAt], [AssignedBy], [IsActive] FROM inserted i WHERE i.Id = COALESCE(i.Id, d.Id) FOR JSON PATH, WITHOUT_ARRAY_WRAPPER),
            @UserId,
            GETDATE()
        FROM inserted i
        FULL OUTER JOIN deleted d ON i.Id = d.Id;
    END
GO

